
    :root {
      color-scheme: dark;
      --ink: #effefa;
      --muted: #aac8c1;
      --cyan: #46f0d7;
      --green: #6cf0a4;
      --orange: #ff8e48;
      --red: #ff6174;
      --panel: rgba(9, 28, 29, 0.76);
      --line: rgba(70, 240, 215, 0.32);
      --line-strong: rgba(108, 240, 164, 0.76);
      --shadow: 0 30px 90px rgba(0, 0, 0, 0.44);
    }

    * {
      box-sizing: border-box;
      scrollbar-width: none;
      -ms-overflow-style: none;
      -webkit-user-select: none !important;
      user-select: none !important;
      -webkit-touch-callout: none;
    }

    input,
    textarea,
    [role="textbox"],
    [contenteditable="true"],
    [contenteditable=""] {
      -webkit-user-select: text !important;
      user-select: text !important;
      -webkit-touch-callout: default;
    }

    ::selection {
      background: transparent;
      color: inherit;
    }

    input::selection,
    textarea::selection,
    [role="textbox"]::selection,
    [contenteditable="true"]::selection,
    [contenteditable=""]::selection {
      background: rgba(70, 240, 215, 0.36);
      color: #ffffff;
    }

    @media print {
      html,
      body {
        display: none !important;
      }
    }

    *::-webkit-scrollbar {
      width: 0;
      height: 0;
      display: none;
    }

    html,
    body {
      width: 100%;
      min-height: 100%;
      margin: 0;
      overflow-x: hidden;
      background: #071112;
      color: var(--ink);
      font-family: "Segoe UI", Arial, sans-serif;
    }

    body {
      min-height: 100vh;
      min-height: 100dvh;
      overflow: hidden;
    }

    .future-update-notice-overlay {
      position: fixed;
      inset: 0;
      z-index: 2147483000;
      display: grid;
      place-items: center;
      padding: 22px;
      background:
        radial-gradient(circle at 50% 44%, rgba(70, 240, 215, 0.10), transparent 36%),
        rgba(2, 8, 10, 0.58);
      opacity: 0;
      pointer-events: none;
      transition: opacity 220ms ease;
      backdrop-filter: blur(10px) saturate(1.05);
    }

    .future-update-notice-overlay.is-visible {
      opacity: 1;
    }

    .future-update-notice-panel {
      position: relative;
      display: grid;
      grid-template-columns: 54px minmax(0, 1fr);
      gap: 16px;
      width: min(500px, calc(100vw - 34px));
      padding: 19px 20px 17px;
      border: 1px solid rgba(126, 255, 235, 0.24);
      border-radius: 18px;
      color: #effefa;
      background:
        linear-gradient(135deg, rgba(13, 31, 36, 0.94), rgba(6, 13, 19, 0.94)),
        rgba(5, 14, 18, 0.94);
      box-shadow:
        0 24px 80px rgba(0, 0, 0, 0.58),
        0 0 28px rgba(70, 240, 215, 0.10),
        0 0 0 1px rgba(255, 255, 255, 0.04),
        inset 0 0 28px rgba(70, 240, 215, 0.045);
      overflow: hidden;
      transform: translateY(12px) scale(0.97);
      transition: transform 300ms cubic-bezier(.16, .84, .22, 1);
    }

    .future-update-notice-overlay.is-visible .future-update-notice-panel {
      transform: translateY(0) scale(1);
    }

    .future-update-notice-panel::before {
      content: "";
      position: absolute;
      inset: -1px;
      background:
        linear-gradient(90deg, transparent, rgba(126, 255, 235, 0.42), transparent);
      opacity: 0;
      mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
      -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
      mask-composite: exclude;
      -webkit-mask-composite: xor;
      padding: 1px;
      animation: futureUpdateNoticeBorderScan 5s ease both;
      pointer-events: none;
    }

    .future-update-notice-panel::after {
      content: "";
      position: absolute;
      inset: 0;
      background:
        linear-gradient(90deg, transparent, rgba(126, 255, 235, 0.08), transparent);
      opacity: 0;
      transform: translateY(-34%);
      animation: futureUpdateNoticeDataScan 5s ease both;
      pointer-events: none;
    }

    .future-update-notice-signal {
      position: relative;
      width: 54px;
      height: 54px;
      border: 1px solid rgba(126, 255, 235, 0.25);
      border-radius: 16px;
      background:
        radial-gradient(circle at 50% 50%, rgba(236, 255, 249, 0.14) 0 7px, transparent 8px),
        conic-gradient(from 210deg, transparent 0 12%, rgba(70, 240, 215, 0.46) 14% 20%, transparent 22% 55%, rgba(108, 240, 164, 0.28) 58% 64%, transparent 66% 100%),
        linear-gradient(135deg, rgba(126, 255, 235, 0.10), transparent 38%),
        linear-gradient(135deg, rgba(10, 34, 38, 0.94), rgba(4, 13, 18, 0.90));
      box-shadow:
        0 0 18px rgba(70, 240, 215, 0.14),
        inset 0 0 18px rgba(126, 255, 235, 0.07),
        inset 0 0 0 1px rgba(255, 255, 255, 0.035);
      animation:
        futureUpdateNoticePulse 2.2s ease-in-out infinite,
        futureUpdateNoticeCoreTurn 5s linear both;
      isolation: isolate;
      overflow: hidden;
      z-index: 1;
    }

    .future-update-notice-signal::before,
    .future-update-notice-signal::after {
      content: "";
      position: absolute;
      background: #061112;
    }

    .future-update-notice-signal::before {
      left: 18px;
      top: 15px;
      z-index: 2;
      width: 18px;
      height: 21px;
      background:
        linear-gradient(180deg, rgba(255, 255, 255, 0.72), transparent 24%),
        linear-gradient(135deg, #d8fff7, #46f0d7 58%, #5eb8ff);
      clip-path: polygon(50% 0, 100% 46%, 72% 46%, 72% 100%, 28% 100%, 28% 46%, 0 46%);
      filter:
        drop-shadow(0 0 5px rgba(70, 240, 215, 0.42))
        drop-shadow(0 2px 5px rgba(0, 0, 0, 0.28));
      animation: futureUpdateNoticeArrowBoost 5s cubic-bezier(.16, .84, .22, 1) both;
    }

    .future-update-notice-signal::after {
      inset: 8px;
      z-index: 1;
      border: 1px solid rgba(126, 255, 235, 0.18);
      border-top-color: rgba(126, 255, 235, 0.62);
      border-right-color: rgba(108, 240, 164, 0.34);
      border-radius: 50%;
      background:
        radial-gradient(circle, transparent 0 48%, rgba(70, 240, 215, 0.08) 49% 52%, transparent 53%);
      opacity: 0.84;
      animation: futureUpdateNoticeOrbit 5s cubic-bezier(.16, .84, .22, 1) both;
    }

    .future-update-notice-copy {
      min-width: 0;
      display: grid;
      gap: 7px;
    }

    .future-update-notice-title {
      font-size: 16px;
      font-weight: 950;
      line-height: 1.2;
      color: #ffffff;
      text-shadow: 0 0 14px rgba(70, 240, 215, 0.12);
    }

    .future-update-notice-message {
      color: rgba(239, 254, 250, 0.74);
      font-size: 12.5px;
      font-weight: 650;
      line-height: 1.42;
    }

    .future-update-notice-meta {
      width: fit-content;
      max-width: 100%;
      padding: 4px 8px;
      border: 1px solid rgba(70, 240, 215, 0.22);
      border-radius: 999px;
      color: #8fffe9;
      background:
        linear-gradient(90deg, rgba(70, 240, 215, 0.09), rgba(108, 240, 164, 0.05)),
        rgba(70, 240, 215, 0.07);
      font-size: 10px;
      font-weight: 900;
      line-height: 1;
      text-transform: uppercase;
      white-space: nowrap;
    }

    .future-update-notice-progress {
      position: relative;
      height: 4px;
      margin-top: 4px;
      border-radius: 999px;
      background:
        linear-gradient(90deg, rgba(255, 255, 255, 0.08), rgba(70, 240, 215, 0.10)),
        rgba(255, 255, 255, 0.08);
      overflow: hidden;
    }

    .future-update-notice-progress > span {
      position: absolute;
      inset: 0 auto 0 0;
      width: 100%;
      border-radius: inherit;
      background:
        linear-gradient(90deg, #46f0d7, #6cf0a4),
        linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.55), transparent);
      box-shadow: 0 0 10px rgba(70, 240, 215, 0.22);
      transform-origin: left center;
      animation: futureUpdateNoticeProgress 5s linear both;
    }

    @keyframes futureUpdateNoticePulse {
      0%, 100% { transform: scale(1); filter: brightness(1); }
      50% { transform: scale(1.025); filter: brightness(1.04); }
    }

    @keyframes futureUpdateNoticeBorderScan {
      0%, 8% { opacity: 0; transform: translateX(-55%); }
      24% { opacity: 0.34; }
      66% { opacity: 0.18; }
      100% { opacity: 0; transform: translateX(55%); }
    }

    @keyframes futureUpdateNoticeDataScan {
      0%, 14% { opacity: 0; transform: translateX(-28%); }
      30% { opacity: 0.24; }
      78% { opacity: 0.12; }
      100% { opacity: 0; transform: translateX(28%); }
    }

    @keyframes futureUpdateNoticeCoreTurn {
      0% { background-position: center, center, center, center; filter: brightness(0.98); }
      24% { filter: brightness(1.06); }
      100% { background-position: center, center, 18px 0, center; filter: brightness(1); }
    }

    @keyframes futureUpdateNoticeArrowBoost {
      0%, 10% { transform: translateY(4px) scale(0.94); opacity: 0; }
      24% { transform: translateY(-1px) scale(1.04); opacity: 1; }
      38%, 82% { transform: translateY(0) scale(1); opacity: 1; }
      100% { transform: translateY(-4px) scale(0.96); opacity: 0.55; }
    }

    @keyframes futureUpdateNoticeOrbit {
      0%, 8% { transform: rotate(-24deg) scale(0.92); opacity: 0; }
      24% { transform: rotate(18deg) scale(1); opacity: 0.86; }
      82% { transform: rotate(260deg) scale(1); opacity: 0.66; }
      100% { transform: rotate(318deg) scale(0.96); opacity: 0.28; }
    }

    @keyframes futureUpdateNoticeProgress {
      from { transform: scaleX(1); }
      to { transform: scaleX(0); }
    }

    @media (max-width: 520px) {
      .future-update-notice-panel {
        grid-template-columns: 48px minmax(0, 1fr);
        gap: 12px;
        padding: 16px 15px 14px;
        border-radius: 18px;
      }

      .future-update-notice-signal {
        width: 48px;
        height: 48px;
        border-radius: 16px;
      }

      .future-update-notice-signal::before {
        left: 15px;
        top: 13px;
        width: 18px;
        height: 20px;
      }

      .future-update-notice-signal::after {
        inset: 7px;
      }
    }

    @media (pointer: fine) {
      html.ft-holo-cursor-ready,
      html.ft-holo-cursor-ready body,
      html.ft-holo-cursor-ready body *,
      html.ft-holo-cursor-ready body *::before,
      html.ft-holo-cursor-ready body *::after {
        cursor: none !important;
      }

      html.ft-holo-cursor-ready.ft-holo-cursor-native body :where(input, textarea, select, [contenteditable="true"], [contenteditable=""]) {
        cursor: text !important;
      }

      html.ft-holo-cursor-ready.ft-holo-cursor-native body :where(canvas, .ft-paint-canvas, .ft-paint-board) {
        cursor: crosshair !important;
      }

      .ft-holo-cursor {
        --cursor-x: -120px;
        --cursor-y: -120px;
        --cursor-accent: 70, 240, 215;
        position: fixed;
        left: 0;
        top: 0;
        z-index: 2147483000;
        width: 1px;
        height: 1px;
        pointer-events: none;
        opacity: 0;
        transform: translate3d(var(--cursor-x), var(--cursor-y), 0) scale(var(--cursor-scale, 1));
        transform-origin: 0 0;
        transition:
          opacity 120ms ease,
          filter 120ms ease;
        mix-blend-mode: screen;
        filter:
          drop-shadow(0 0 1px rgba(0, 0, 0, 0.9))
          drop-shadow(0 0 9px rgba(var(--cursor-accent), 0.8))
          drop-shadow(0 0 20px rgba(108, 240, 164, 0.22));
        will-change: transform, opacity;
      }

      html.ft-holo-cursor-active .ft-holo-cursor {
        opacity: 1;
      }

      html.ft-holo-cursor-native .ft-holo-cursor,
      html.ft-holo-cursor-hidden .ft-holo-cursor {
        opacity: 0;
      }

      .ft-holo-cursor::before,
      .ft-holo-cursor::after,
      .ft-holo-cursor-core,
      .ft-holo-cursor-rail {
        content: "";
        position: absolute;
        pointer-events: none;
      }

      .ft-holo-cursor::before {
        left: -1px;
        top: -1px;
        width: 28px;
        height: 34px;
        clip-path: polygon(1px 0, 1px 30px, 8px 22px, 13px 33px, 21px 30px, 16px 20px, 27px 20px);
        background:
          linear-gradient(135deg, rgba(236, 255, 249, 0.94), rgba(236, 255, 249, 0.18) 25%, rgba(var(--cursor-accent), 0.88) 58%, rgba(108, 240, 164, 0.68)),
          linear-gradient(45deg, transparent 0 44%, rgba(255, 255, 255, 0.86) 48%, transparent 52% 100%);
        box-shadow:
          inset 0 0 0 1px rgba(2, 8, 12, 0.78),
          inset 0 0 0 2px rgba(236, 255, 249, 0.46),
          0 0 0 1px rgba(var(--cursor-accent), 0.66),
          0 0 18px rgba(var(--cursor-accent), 0.58);
        opacity: 0.94;
      }

      .ft-holo-cursor::after {
        left: -11px;
        top: -11px;
        width: 25px;
        height: 25px;
        border: 1px solid rgba(var(--cursor-accent), 0.72);
        border-radius: 999px;
        background:
          radial-gradient(circle, rgba(255, 255, 255, 0.58) 0 2px, transparent 3px),
          conic-gradient(from 80deg, transparent 0 16%, rgba(var(--cursor-accent), 0.68) 22%, transparent 32% 54%, rgba(255, 209, 102, 0.5) 62%, transparent 74% 100%);
        box-shadow:
          inset 0 0 8px rgba(var(--cursor-accent), 0.16),
          0 0 14px rgba(var(--cursor-accent), 0.38);
        animation: holoCursorOrbit 1.4s linear infinite;
      }

      .ft-holo-cursor-core {
        left: -3px;
        top: -3px;
        width: 7px;
        height: 7px;
        border-radius: 50%;
        background: radial-gradient(circle, #effefa 0 1px, rgba(var(--cursor-accent), 0.96) 2px, rgba(var(--cursor-accent), 0.1) 70%, transparent 72%);
        box-shadow:
          0 0 8px rgba(var(--cursor-accent), 0.74),
          0 0 18px rgba(108, 240, 164, 0.24);
      }

      .ft-holo-cursor-rail {
        left: 17px;
        top: 30px;
        width: 38px;
        height: 1px;
        transform: rotate(18deg);
        transform-origin: left center;
        background:
          linear-gradient(90deg, rgba(236, 255, 249, 0.9), rgba(var(--cursor-accent), 0.54), transparent),
          repeating-linear-gradient(90deg, transparent 0 5px, rgba(236, 255, 249, 0.46) 5px 6px, transparent 6px 10px);
        opacity: 0.7;
      }

      html.ft-holo-cursor-pointer .ft-holo-cursor {
        --cursor-accent: 255, 209, 102;
        --cursor-scale: 1.02;
      }

      html.ft-holo-cursor-drag .ft-holo-cursor {
        --cursor-accent: 216, 108, 255;
        --cursor-scale: 1.05;
      }

      html.ft-holo-cursor-down .ft-holo-cursor {
        --cursor-scale: 0.92;
        filter:
          drop-shadow(0 0 12px rgba(var(--cursor-accent), 0.72))
          drop-shadow(0 0 24px rgba(236, 255, 249, 0.16));
      }

      html.ft-holo-cursor-idle .ft-holo-cursor,
      html.ft-holo-cursor-hidden .ft-holo-cursor,
      html.ft-lesson-vault-motion-off .ft-holo-cursor {
        mix-blend-mode: normal;
        will-change: auto;
        filter: none;
      }

      html.ft-holo-cursor-idle .ft-holo-cursor::after,
      html.ft-holo-cursor-hidden .ft-holo-cursor::after,
      html.ft-lesson-vault-motion-off .ft-holo-cursor::after {
