        opacity: 0.38;
      }

      @keyframes holoCursorOrbit {
        from { transform: rotate(0turn); }
        to { transform: rotate(1turn); }
      }
    }

    html.ft-holo-cursor-ready,
    html.ft-holo-cursor-ready body,
    html.ft-holo-cursor-ready body *,
    html.ft-holo-cursor-ready body *::before,
    html.ft-holo-cursor-ready body *::after {
