    /* ============================================================
       Reward gems -- synced with inventory faceted engine.
       Same facet wedges + crown sheen + drifting glint + float.
       Per-type palette and silhouette mirror the inventory tones.
       ============================================================ */
    .ft-cup-reward-gem {
      position: relative;
      width: 40px;
      aspect-ratio: 1;
      justify-self: center;
      transform-style: preserve-3d;
      --rg-core: #ffffff;
      --rg-mid: #7effeb;
      --rg-deep: #167f6e;
      --rg-glow: rgba(126, 255, 235, 0.6);
      --rg-facets:
        conic-gradient(from var(--rg-spin, 210deg) at 50% 46%,
          color-mix(in srgb, var(--rg-core) 92%, transparent) 0deg,
          var(--rg-mid) 34deg,
          var(--rg-deep) 70deg,
          var(--rg-mid) 104deg,
          color-mix(in srgb, var(--rg-core) 88%, transparent) 142deg,
          var(--rg-deep) 188deg,
          var(--rg-mid) 232deg,
          var(--rg-deep) 286deg,
          var(--rg-mid) 326deg,
          color-mix(in srgb, var(--rg-core) 92%, transparent) 360deg);
      clip-path: polygon(50% 0, 84% 16%, 96% 50%, 84% 84%, 50% 100%, 16% 84%, 4% 50%, 16% 16%);
      background:
        radial-gradient(130% 100% at 42% -16%, rgba(255, 255, 255, 0.96), rgba(255, 255, 255, 0) 40%),
        var(--rg-facets),
        linear-gradient(158deg, var(--rg-mid), var(--rg-deep) 100%);
      filter:
        saturate(1.28)
        drop-shadow(0 4px 6px rgba(0, 0, 0, 0.42))
        drop-shadow(0 0 11px var(--rg-glow));
      animation: cupRewardGemFloat 3600ms ease-in-out infinite;
    }

    .ft-cup-reward-gem::before {
      content: "";
      position: absolute;
      inset: 0;
      pointer-events: none;
      clip-path: inherit;
      background:
        linear-gradient(180deg, rgba(255, 255, 255, 0.95) 0%, rgba(255, 255, 255, 0.16) 16%, rgba(255, 255, 255, 0) 36%),
        linear-gradient(58deg, rgba(255, 255, 255, 0) 46%, rgba(255, 255, 255, 0.4) 50%, rgba(255, 255, 255, 0) 54%),
        linear-gradient(122deg, rgba(255, 255, 255, 0) 46%, rgba(255, 255, 255, 0.3) 50%, rgba(255, 255, 255, 0) 54%),
        radial-gradient(75% 55% at 50% 104%, rgba(0, 0, 0, 0.34), rgba(0, 0, 0, 0) 62%);
      mix-blend-mode: screen;
      opacity: 0.92;
    }

    .ft-cup-reward-gem::after {
      content: "";
      position: absolute;
      inset: -2px;
      pointer-events: none;
      clip-path: inherit;
      background:
        conic-gradient(from 0deg at 50% 50%,
          rgba(255, 255, 255, 0) 0deg, rgba(255, 255, 255, 0.9) 10deg, rgba(255, 255, 255, 0) 26deg,
          rgba(255, 255, 255, 0) 150deg, rgba(255, 255, 255, 0.55) 178deg, rgba(255, 255, 255, 0) 200deg,
          rgba(255, 255, 255, 0) 360deg);
      mix-blend-mode: screen;
      opacity: 0.7;
      animation: cupRewardGemShimmer 4600ms linear infinite;
    }

    /* Space_Q -- single tall hexagonal quartz crystal point (matches inventory is-spaceq) */
    .ft-cup-reward-gem.is-space-q {
      --rg-core: #fff7e0;
      --rg-mid: #ffc05e;
      --rg-deep: #9c4a12;
      --rg-glow: rgba(255, 184, 86, 0.66);
      clip-path: polygon(50% 0, 70% 14%, 70% 70%, 50% 100%, 30% 70%, 30% 14%);
      background:
        radial-gradient(120% 80% at 44% -10%, rgba(255, 255, 255, 0.95), rgba(255, 255, 255, 0) 34%),
        linear-gradient(108deg, rgba(255, 255, 255, 0.34) 0 38%, rgba(0, 0, 0, 0.22) 38% 50%, rgba(255, 255, 255, 0.2) 50% 64%, rgba(0, 0, 0, 0.18) 64%),
        var(--rg-facets),
        linear-gradient(168deg, var(--rg-core), var(--rg-mid) 44%, var(--rg-deep) 100%);
    }

    .ft-cup-reward-gem.is-bookgold {
      clip-path: none;
      background: url("data:image/svg+xml;base64,") center / contain no-repeat;
