    @keyframes cupRewardWingFlap {
      0%, 100% {
        transform: translateZ(0);
        filter: var(--ft-wing-shadow) var(--ft-wing-glow) brightness(1) saturate(1);
      }
      18% {
        transform: translateY(-1.2px) translateZ(0);
        filter: var(--ft-wing-shadow) var(--ft-wing-glow-strong) brightness(1.03) saturate(1.03);
      }
      34% {
        transform: translateZ(0);
        filter: var(--ft-wing-shadow) var(--ft-wing-glow) brightness(1.01) saturate(1.01);
      }
      46% {
        transform: translateY(-0.8px) translateZ(0);
        filter: var(--ft-wing-shadow) var(--ft-wing-glow-strong) brightness(1.06) saturate(1.04);
      }
      62% {
        transform: translateZ(0);
        filter: var(--ft-wing-shadow) var(--ft-wing-glow) brightness(1.02) saturate(1.01);
      }
    }

    @keyframes cupRewardGemShimmer {
      from { transform: rotate(0deg); }
      to   { transform: rotate(360deg); }
    }

    @keyframes cupRewardWingFlapHover {
      0%, 100% {
        transform: translateZ(0);
        filter: var(--ft-wing-shadow) var(--ft-wing-glow) brightness(1.04) saturate(1.03);
      }
      20% {
        transform: translateY(-1.8px) translateZ(0);
        filter: var(--ft-wing-shadow) var(--ft-wing-glow-strong) brightness(1.1) saturate(1.06);
      }
      42% {
        transform: translateY(-1.1px) translateZ(0);
        filter: var(--ft-wing-shadow) var(--ft-wing-glow-strong) brightness(1.14) saturate(1.08);
      }
