      }
    }

    @keyframes cupRewardWingLeftY {
      0%, 36%, 100% {
        transform: perspective(360px) rotateY(0deg);
      }
      42% {
        transform: perspective(360px) rotateY(8deg);
      }
      48% {
        transform: perspective(360px) rotateY(26deg);
      }
      56% {
        transform: perspective(360px) rotateY(6deg);
