    .ft-cup-type-option[data-cup-type="space_s"] { --type-index: 4; --type-accent: #ff8f70; --type-accent-soft: rgba(255, 143, 112, 0.17); }
    .ft-cup-type-option[data-cup-type="space_l"] { --type-index: 5; --type-accent: #a8c7ff; --type-accent-soft: rgba(168, 199, 255, 0.17); }

    .ft-cup-type-icon {
      --icon-accent: #6cf0a4;
      position: relative;
      width: 30px;
      height: 30px;
      border: 1px solid color-mix(in srgb, var(--icon-accent) 58%, transparent);
      border-radius: 8px;
      display: grid;
      place-items: center;
      background:
        radial-gradient(circle at 50% 28%, color-mix(in srgb, var(--icon-accent) 34%, transparent), transparent 52%),
        rgba(3, 13, 16, 0.76);
      box-shadow: 0 0 18px color-mix(in srgb, var(--icon-accent) 22%, transparent);
      overflow: hidden;
      flex: 0 0 auto;
    }

    .ft-cup-type-icon::before,
    .ft-cup-type-icon::after,
    .ft-cup-type-icon span {
      content: "";
      position: absolute;
      display: block;
      background: var(--icon-accent);
      box-shadow: 0 0 10px color-mix(in srgb, var(--icon-accent) 52%, transparent);
    }

    .ft-cup-type-icon::after {
      opacity: 0.45;
      animation: cupTypeIconPulse 1.9s ease-in-out infinite;
    }

    .ft-cup-type-icon.is-space-v { --icon-accent: #6cf0a4; }
    .ft-cup-type-icon.is-space-v::before { width: 16px; height: 18px; border-radius: 4px 4px 2px 2px; background: transparent; border: 2px solid var(--icon-accent); }
    .ft-cup-type-icon.is-space-v::after { width: 10px; height: 2px; top: 11px; left: 10px; box-shadow: 0 5px 0 var(--icon-accent), 0 10px 0 var(--icon-accent); }
    .ft-cup-type-icon.is-space-v span { width: 4px; height: 4px; right: 5px; top: 6px; border-radius: 50%; }

    .ft-cup-type-icon.is-space-w { --icon-accent: #ffd166; }
    .ft-cup-type-icon.is-space-w::before { width: 15px; height: 16px; border-radius: 2px; transform: rotate(-10deg); }
    .ft-cup-type-icon.is-space-w::after { width: 15px; height: 16px; border-radius: 2px; background: transparent; border: 2px solid var(--icon-accent); transform: translate(4px, -2px) rotate(9deg); }
    .ft-cup-type-icon.is-space-w span { width: 12px; height: 2px; left: 8px; bottom: 8px; }

    .ft-cup-type-icon.is-space-q { --icon-accent: #67e8f9; }
    .ft-cup-type-icon.is-space-q::before { width: 17px; height: 13px; border-radius: 8px; background: transparent; border: 2px solid var(--icon-accent); }
    .ft-cup-type-icon.is-space-q::after { width: 7px; height: 2px; right: 7px; bottom: 8px; transform: rotate(42deg); }
    .ft-cup-type-icon.is-space-q span { width: 3px; height: 3px; border-radius: 50%; box-shadow: -5px 0 0 var(--icon-accent), 5px 0 0 var(--icon-accent); }

    .ft-cup-type-icon.is-space-p { --icon-accent: #f7a8ff; }
    .ft-cup-type-icon.is-space-p::before { width: 18px; height: 2px; top: 10px; left: 6px; box-shadow: 0 5px 0 var(--icon-accent), 0 10px 0 var(--icon-accent); }
    .ft-cup-type-icon.is-space-p::after { width: 10px; height: 10px; right: 5px; top: 5px; border-radius: 50%; background: transparent; border: 2px solid var(--icon-accent); }
    .ft-cup-type-icon.is-space-p span { width: 4px; height: 14px; left: 8px; top: 8px; border-radius: 5px; transform: rotate(24deg); }

    .ft-cup-type-icon.is-space-s { --icon-accent: #ff8f70; }
    .ft-cup-type-icon.is-space-s::before { width: 10px; height: 15px; top: 5px; border-radius: 8px; }
    .ft-cup-type-icon.is-space-s::after { width: 18px; height: 9px; bottom: 6px; border-radius: 0 0 12px 12px; background: transparent; border: 2px solid var(--icon-accent); border-top: 0; }
    .ft-cup-type-icon.is-space-s span { width: 2px; height: 7px; bottom: 3px; }

    .ft-cup-type-icon.is-space-l { --icon-accent: #a8c7ff; }
    .ft-cup-type-icon.is-space-l::before { width: 18px; height: 18px; border-radius: 50%; background: transparent; border: 2px solid var(--icon-accent); border-bottom-color: transparent; }
    .ft-cup-type-icon.is-space-l::after { width: 6px; height: 10px; left: 5px; bottom: 7px; border-radius: 4px; box-shadow: 14px 0 0 var(--icon-accent); }
    .ft-cup-type-icon.is-space-l span { width: 12px; height: 2px; bottom: 7px; }

    @keyframes cupTypeItemFloat {
