    }

    .ft-cup-viewer-close {
      width: 30px;
      height: 30px;
      border: 1px solid rgba(255, 132, 162, 0.38);
      border-radius: 10px;
      color: #ff9fb1;
      background: rgba(255, 97, 116, 0.10);
      cursor: pointer;
      font-weight: 950;
    }

    .ft-cup-viewer-list {
      display: grid;
      gap: 8px;
      max-height: calc(min(520px, calc(100dvh - 150px)) - 58px);
      overflow: auto;
      padding: 10px;
    }

    .ft-cup-viewer-row {
      display: grid;
      grid-template-columns: 46px minmax(0, 1fr) auto;
      align-items: center;
      gap: 10px;
      min-height: 58px;
      padding: 9px 10px;
      border: 1px solid rgba(70, 240, 215, 0.18);
      border-radius: 14px;
      background: rgba(255, 255, 255, 0.035);
      box-shadow: inset 0 0 16px rgba(70, 240, 215, 0.045);
    }

    .ft-cup-viewer-row .ft-cup-avatar {
      width: 42px;
      height: 42px;
      border-radius: 14px;
    }

    .ft-cup-viewer-name {
      min-width: 0;
      color: #ecfff9;
      font-size: 12px;
      font-weight: 950;
      overflow: visible;
      text-overflow: clip;
      white-space: normal;
      overflow-wrap: anywhere;
      word-break: break-word;
      line-height: 1.18;
    }

    .ft-cup-viewer-user,
    .ft-cup-viewer-time {
      color: rgba(170, 200, 193, 0.78);
      font-size: 10px;
      font-weight: 850;
      white-space: nowrap;
    }


    .ft-cup-row {
      display: grid;
      grid-template-columns: 52px 58px minmax(0, 1fr) minmax(92px, auto);
      align-items: stretch;
      gap: 12px;
      min-height: 118px;
      padding: 12px 14px;
      border-radius: 16px;
      animation: cupRankIn 360ms cubic-bezier(.16, .84, .22, 1) both;
      animation-delay: calc(var(--rank, 1) * 45ms);
    }

    .ft-cup-podium-card.is-preview,
    .ft-cup-row.is-preview {
      border-color: rgba(126, 255, 235, 0.30);
      background:
        linear-gradient(140deg, rgba(126, 255, 235, 0.10), transparent 42%),
        rgba(4, 14, 18, 0.70);
    }

    .ft-cup-row-rank {
      display: grid;
      place-items: center;
      width: 36px;
      height: 36px;
      border: 1px solid rgba(70, 240, 215, 0.34);
      border-radius: 12px;
      color: #8fffe9;
      font-weight: 950;
      background: rgba(70, 240, 215, 0.08);
      box-shadow: inset 0 0 16px rgba(70, 240, 215, 0.07);
    }

    .ft-cup-rank-wrap {
      display: grid;
      gap: 4px;
      place-items: center;
      align-self: center;
    }

    .ft-cup-rank-move {
      position: relative;
      min-width: 42px;
      height: 24px;
      border: 1px solid rgba(70, 240, 215, 0.30);
      border-radius: 999px;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 5px;
      padding: 0 9px 0 8px;
      color: rgba(239, 254, 250, 0.88);
      background:
        radial-gradient(circle at 30% 18%, rgba(126, 255, 235, 0.22), transparent 48%),
        linear-gradient(135deg, rgba(6, 18, 24, 0.88), rgba(5, 10, 17, 0.78));
      font-size: 11px;
      font-weight: 950;
      line-height: 1;
      letter-spacing: 0;
      text-transform: uppercase;
      white-space: nowrap;
      font-variant-numeric: tabular-nums;
      overflow: hidden;
      isolation: isolate;
    }

    .ft-cup-rank-move::after {
      content: "";
      position: absolute;
      inset: 1px auto 1px -54%;
      width: 52%;
      border-radius: inherit;
      background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.38), transparent);
      opacity: 0;
      transform: skewX(-20deg);
      pointer-events: none;
      z-index: 0;
    }

    .ft-cup-rank-icon {
      position: relative;
      z-index: 1;
      width: 15px;
      height: 15px;
      flex: 0 0 auto;
      display: inline-block;
      color: var(--rank-arrow, #8fffe9);
      filter:
        drop-shadow(0 0 4px var(--rank-arrow-glow, rgba(70, 240, 215, 0.42)))
        drop-shadow(0 2px 7px rgba(0, 0, 0, 0.22));
    }

    .ft-cup-rank-icon::before {
      content: "";
      position: absolute;
      inset: 1px 2px 1px 2px;
      border-radius: 2px;
      background:
        linear-gradient(180deg, rgba(255, 255, 255, 0.95), transparent 26%),
        linear-gradient(135deg, var(--rank-arrow-hot, #f3fff9), var(--rank-arrow, #46f0d7) 54%, var(--rank-arrow-deep, #18a7ff));
      clip-path: polygon(50% 0, 100% 45%, 72% 45%, 72% 100%, 28% 100%, 28% 45%, 0 45%);
    }

    .ft-cup-rank-icon::after {
      content: "";
      position: absolute;
      left: -3px;
      right: -3px;
      bottom: -1px;
      height: 5px;
      border-radius: 999px;
      background:
        linear-gradient(90deg, transparent, var(--rank-arrow-glow, rgba(70, 240, 215, 0.48)), transparent);
      opacity: 0.6;
      filter: blur(0.4px);
    }

    .ft-cup-rank-delta {
      position: relative;
      z-index: 1;
      top: 0.5px;
      min-width: 7px;
      text-align: center;
    }

    .ft-cup-rank-move.is-up {
      --rank-arrow: #6cf0a4;
      --rank-arrow-hot: #f4fff7;
      --rank-arrow-deep: #46f0d7;
      --rank-arrow-glow: rgba(108, 240, 164, 0.62);
      color: #eafff5;
      border-color: rgba(108, 240, 164, 0.58);
      background:
        radial-gradient(circle at 28% 20%, rgba(108, 240, 164, 0.30), transparent 44%),
        linear-gradient(135deg, rgba(5, 22, 18, 0.92), rgba(3, 12, 16, 0.82));
      box-shadow:
        0 0 18px rgba(108, 240, 164, 0.18),
        inset 0 0 14px rgba(108, 240, 164, 0.10);
      animation:
        cupRankMoveUp 1.8s cubic-bezier(.16, .84, .22, 1) both,
        cupRankMoveUpBeat 10s ease-in-out 2s infinite;
    }

    .ft-cup-rank-move.is-down {
      --rank-arrow: #ff6174;
      --rank-arrow-hot: #fff1f3;
      --rank-arrow-deep: #ff9f6b;
      --rank-arrow-glow: rgba(255, 97, 116, 0.58);
      color: #fff2f4;
      border-color: rgba(255, 97, 116, 0.54);
      background:
        radial-gradient(circle at 28% 20%, rgba(255, 97, 116, 0.24), transparent 45%),
        linear-gradient(135deg, rgba(28, 8, 15, 0.92), rgba(12, 7, 14, 0.82));
      box-shadow:
        0 0 18px rgba(255, 97, 116, 0.15),
        inset 0 0 14px rgba(255, 97, 116, 0.08);
      animation:
        cupRankMoveDown 1.8s cubic-bezier(.16, .84, .22, 1) both,
        cupRankMoveDownBeat 10s ease-in-out 2s infinite;
    }

    .ft-cup-rank-move.is-down .ft-cup-rank-icon {
      transform: rotate(180deg);
    }

    .ft-cup-rank-move.is-new {
      color: #061112;
      border-color: rgba(255, 209, 102, 0.72);
      background: linear-gradient(135deg, #fff0a8, #ffb74a);
      box-shadow: 0 0 15px rgba(255, 209, 102, 0.2);
      animation: cupRankMoveNew 1.9s cubic-bezier(.16, .84, .22, 1) both;
    }

    .ft-cup-rank-move.is-up::after,
    .ft-cup-rank-move.is-down::after,
    .ft-cup-rank-move.is-new::after {
      animation: cupRankMoveGlint 10s ease-in-out 2s infinite;
    }

    .ft-cup-rank-move.is-up .ft-cup-rank-icon {
      animation: cupRankArrowUpBeat 10s cubic-bezier(.16, .84, .22, 1) 2s infinite;
    }

    .ft-cup-rank-move.is-down .ft-cup-rank-icon {
      animation: cupRankArrowDownBeat 10s cubic-bezier(.16, .84, .22, 1) 2s infinite;
    }

    .ft-cup-rank-move.is-preview {
      color: #061112;
      border-color: rgba(126, 255, 235, 0.68);
      background: linear-gradient(135deg, #8fffe9, #ffd166);
      box-shadow: 0 0 15px rgba(70, 240, 215, 0.18);
    }

    .ft-cup-row-meta {
      min-width: 0;
      display: grid;
      align-content: center;
      gap: 5px;
    }

    .ft-cup-row-score {
      align-self: center;
      justify-self: end;
      text-align: right;
      white-space: nowrap;
    }

    .ft-cup-today {
      width: max-content;
      max-width: 100%;
      border: 1px solid rgba(108, 240, 164, 0.3);
      border-radius: 999px;
      display: inline-flex;
      align-items: center;
      gap: 5px;
      padding: 3px 8px;
      color: #baffd7;
      background: rgba(108, 240, 164, 0.08);
      box-shadow: inset 0 0 14px rgba(108, 240, 164, 0.06);
    }

    .ft-cup-today-icon {
      position: relative;
      width: 11px;
      height: 11px;
      flex: 0 0 auto;
      color: #6cf0a4;
      filter: drop-shadow(0 0 4px rgba(108, 240, 164, 0.28));
    }

    .ft-cup-today-icon::before {
      content: "";
      position: absolute;
      inset: 1px 2px 0;
      border-radius: 2px;
      background: currentColor;
      clip-path: polygon(50% 0, 100% 46%, 72% 46%, 72% 100%, 28% 100%, 28% 46%, 0 46%);
    }

    .ft-cup-today-text {
      min-width: 0;
    }

    .ft-cup-today.is-zero {
      display: inline-block;
      color: rgba(170, 200, 193, 0.64);
      border-color: rgba(170, 200, 193, 0.18);
      background: rgba(255, 255, 255, 0.035);
      box-shadow: none;
    }

    .ft-cup-period {
      color: rgba(255, 249, 219, 0.68);
    }

    .ft-cup-row-bar {
      position: relative;
      height: 5px;
      overflow: hidden;
      border-radius: 99px;
      background: rgba(255, 255, 255, 0.08);
    }

    .ft-cup-row-bar span {
      display: block;
      height: 100%;
      width: var(--score-width, 0%);
      border-radius: inherit;
      background: linear-gradient(90deg, #46f0d7, #6cf0a4, #ffd166);
      box-shadow: 0 0 14px rgba(108, 240, 164, 0.36);
      animation: cupBarIn 620ms cubic-bezier(.16, .84, .22, 1) both;
      animation-delay: calc(var(--rank, 1) * 45ms + 180ms);
    }

    .ft-cup-row.is-current {
      border-color: rgba(108, 240, 164, 0.58);
      box-shadow: 0 0 30px rgba(108, 240, 164, 0.12), inset 0 0 24px rgba(108, 240, 164, 0.1);
    }

    .ft-cup-row.is-rank-up,
    .ft-cup-podium-card.is-rank-up {
      animation-name: cupRankLift;
      animation-duration: 820ms;
      animation-timing-function: cubic-bezier(.16, .84, .22, 1);
      box-shadow:
        0 0 32px rgba(108, 240, 164, 0.18),
        inset 0 0 24px rgba(108, 240, 164, 0.12);
    }

    .ft-cup-row.is-rank-down,
    .ft-cup-podium-card.is-rank-down {
      animation-name: cupRankDrop;
      animation-duration: 820ms;
      animation-timing-function: cubic-bezier(.16, .84, .22, 1);
      box-shadow:
        0 0 26px rgba(255, 97, 116, 0.13),
        inset 0 0 22px rgba(255, 97, 116, 0.09);
    }

    .ft-cup-row.is-rank-new,
    .ft-cup-podium-card.is-rank-new {
      animation-name: cupRankNew;
      animation-duration: 920ms;
      animation-timing-function: cubic-bezier(.16, .84, .22, 1);
      box-shadow:
        0 0 30px rgba(255, 209, 102, 0.16),
        inset 0 0 24px rgba(255, 209, 102, 0.1);
    }

    .ft-cup-empty {
      padding: 28px 18px;
      border: 1px dashed rgba(70, 240, 215, 0.28);
      border-radius: 18px;
      color: rgba(239, 254, 250, 0.76);
      text-align: center;
      font-weight: 850;
      background: rgba(4, 14, 18, 0.62);
    }

    .ft-cup-status {
      grid-column: 1 / -1;
      min-height: 18px;
      margin: 0;
    }

    @keyframes cupCardIn {
      from { opacity: 0; transform: translateY(24px) scale(0.96); filter: blur(8px); }
      to { opacity: 1; transform: translateY(0) scale(1); filter: blur(0); }
    }

    @keyframes cupScan {
      to { transform: translateX(120%); }
    }

    @keyframes cupRankIn {
      from { opacity: 0; transform: translateY(16px) scale(0.94); filter: blur(5px); }
      to { opacity: 1; transform: translateY(0) scale(1); filter: blur(0); }
    }

    @keyframes cupRankLift {
      0% { opacity: 0.35; transform: translateY(22px) scale(0.96); filter: blur(5px); }
      52% { opacity: 1; transform: translateY(-7px) scale(1.025); filter: blur(0); }
      100% { opacity: 1; transform: translateY(0) scale(1); filter: blur(0); }
    }

    @keyframes cupRankDrop {
      0% { opacity: 0.45; transform: translateY(-18px) scale(0.98); filter: blur(4px); }
      54% { opacity: 1; transform: translateY(7px) scale(1.01); filter: blur(0); }
      100% { opacity: 1; transform: translateY(0) scale(1); filter: blur(0); }
    }

    @keyframes cupRankNew {
      0% { opacity: 0; transform: translateY(18px) scale(0.9); filter: blur(7px); }
      46% { opacity: 1; transform: translateY(-5px) scale(1.04); filter: blur(0); }
      100% { opacity: 1; transform: translateY(0) scale(1); filter: blur(0); }
    }

    @keyframes cupRankMoveUp {
      0% { transform: translateY(6px) scale(0.9); opacity: 0; filter: blur(4px); }
      38% { transform: translateY(-3px) scale(1.08); opacity: 1; filter: blur(0); }
      62% { transform: translateY(0) scale(1); }
      100% { transform: translateY(0) scale(1); }
    }

    @keyframes cupRankMoveDown {
      0% { transform: translateY(-6px) scale(0.9); opacity: 0; filter: blur(4px); }
      38% { transform: translateY(3px) scale(1.06); opacity: 1; filter: blur(0); }
      62% { transform: translateY(0) scale(1); }
      100% { transform: translateY(0) scale(1); }
    }

    @keyframes cupRankMoveNew {
      0% { transform: translateY(4px) scale(0.86); opacity: 0; filter: blur(5px); }
      36% { transform: translateY(-2px) scale(1.1); opacity: 1; filter: blur(0); }
      64% { transform: translateY(0) scale(1); }
      100% { transform: translateY(0) scale(1); }
    }

    @keyframes cupRankMoveGlint {
      0%, 3% { opacity: 0; transform: translateX(0) skewX(-20deg); }
      5% { opacity: 0.85; }
      10%, 100% { opacity: 0; transform: translateX(330%) skewX(-20deg); }
    }

    @keyframes cupRankMoveUpBeat {
      0%, 88%, 100% {
        transform: translateY(0) scale(1);
        box-shadow:
          0 0 18px rgba(108, 240, 164, 0.18),
          inset 0 0 14px rgba(108, 240, 164, 0.10);
        filter: brightness(1);
      }
      91% {
        transform: translateY(-3px) scale(1.1);
        box-shadow:
          0 0 24px rgba(108, 240, 164, 0.34),
          0 -8px 18px rgba(70, 240, 215, 0.18),
          inset 0 0 18px rgba(108, 240, 164, 0.16);
        filter: brightness(1.14);
      }
      94% {
        transform: translateY(0) scale(1);
      }
    }

    @keyframes cupRankMoveDownBeat {
      0%, 88%, 100% {
        transform: translateY(0) scale(1);
        box-shadow:
          0 0 18px rgba(255, 97, 116, 0.15),
          inset 0 0 14px rgba(255, 97, 116, 0.08);
        filter: brightness(1);
      }
      91% {
        transform: translateY(3px) scale(1.08);
        box-shadow:
          0 0 22px rgba(255, 97, 116, 0.28),
          0 8px 18px rgba(255, 97, 116, 0.14),
          inset 0 0 17px rgba(255, 97, 116, 0.14);
        filter: brightness(1.1);
      }
      94% {
        transform: translateY(0) scale(1);
      }
    }

    @keyframes cupRankArrowUpBeat {
      0%, 87%, 100% { transform: translateY(0) scale(1); opacity: 1; filter: brightness(1); }
      89% { transform: translateY(3px) scale(0.92); opacity: 0.78; filter: brightness(0.95); }
      92% { transform: translateY(-5px) scale(1.18); opacity: 1; filter: brightness(1.25); }
      95% { transform: translateY(0) scale(1); }
    }

    @keyframes cupRankArrowDownBeat {
      0%, 87%, 100% { transform: rotate(180deg) translateY(0) scale(1); opacity: 1; filter: brightness(1); }
      89% { transform: rotate(180deg) translateY(3px) scale(0.92); opacity: 0.78; filter: brightness(0.95); }
      92% { transform: rotate(180deg) translateY(-5px) scale(1.16); opacity: 1; filter: brightness(1.2); }
      95% { transform: rotate(180deg) translateY(0) scale(1); }
    }

    @keyframes cupRowShine {
      0% { transform: translateX(-115%); opacity: 0; }
      28% { opacity: 1; }
      100% { transform: translateX(115%); opacity: 0; }
    }

    @keyframes cupStatusScan {
      0%, 72% { transform: translateX(-110%); opacity: 0; }
      80% { opacity: 0.72; }
      100% { transform: translateX(110%); opacity: 0; }
    }

    @keyframes cupStatusPulse {
      0%, 100% { transform: scale(1); filter: brightness(1); }
      48% { transform: scale(1.08); filter: brightness(1.22); }
    }

    @keyframes cupReactionPickerIn {
      from { opacity: 0; transform: translateY(8px) scale(0.9); filter: blur(2px); }
      to { opacity: 1; transform: translateY(0) scale(1); filter: blur(0); }
    }

    @keyframes cupBarIn {
      from { width: 0; }
      to { width: var(--score-width, 0%); }
    }

    @keyframes cupTrophyFloat {
      0%, 100% { transform: translateY(0) rotateZ(-0.8deg); }
      50% { transform: translateY(-5px) rotateZ(0.8deg); }
    }

    @keyframes cupTrophyHalo {
      0%, 100% { transform: rotateX(64deg) scale(0.86); opacity: 0.18; }
      50% { transform: rotateX(64deg) scale(1.12); opacity: 0.42; }
    }

    @keyframes cupTrophySpark {
      0%, 100% { opacity: 0.28; transform: scale(0.86); }
      50% { opacity: 0.95; transform: scale(1.12); }
    }

    @keyframes cupRewardGemPulse {
      0%, 100% { filter: brightness(1); }
      50% { filter: brightness(1.18); }
    }

    @keyframes cupRewardGemShine {
      0%, 34% { transform: translateX(-135%); opacity: 0; }
      48% { opacity: 0.9; }
      72%, 100% { transform: translateX(135%); opacity: 0; }
    }

    @media (max-width: 620px) {
