    .ft-world-point-marker {
      --point-x: 50%;
      --point-y: 50%;
      position: absolute;
      left: var(--point-x);
      top: var(--point-y);
      z-index: 9000;
      width: 34px;
      height: 34px;
      border: 1px solid rgba(70, 240, 215, 0.78);
      border-radius: 999px;
      transform: translate(-50%, -50%);
      opacity: 0;
      pointer-events: none;
      box-shadow:
        0 0 18px rgba(70, 240, 215, 0.38),
        inset 0 0 16px rgba(255, 209, 102, 0.16);
    }

    .ft-world-point-marker.is-visible {
      opacity: 1;
      animation: ftWorldPointPulse 1.8s ease-in-out infinite;
    }

    .ft-world-point-marker::before,
    .ft-world-point-marker::after {
      content: "";
      position: absolute;
      left: 50%;
      top: 50%;
      background: rgba(255, 209, 102, 0.85);
      transform: translate(-50%, -50%);
      box-shadow: 0 0 10px rgba(255, 209, 102, 0.5);
    }

    .ft-world-point-marker::before {
      width: 2px;
      height: 26px;
    }

    .ft-world-point-marker::after {
      width: 26px;
      height: 2px;
    }

    .ft-world-move-marker {
      --move-x: 50%;
      --move-y: 50%;
      position: absolute;
      left: var(--move-x);
      top: var(--move-y);
      z-index: 9000;
      width: 76px;
      height: 76px;
      opacity: 0;
      pointer-events: none;
      transform: translate(-50%, -50%) rotateX(58deg) scale(0.78);
      transform-origin: 50% 50%;
      filter: drop-shadow(0 0 16px rgba(255, 209, 102, 0.32));
    }

    .ft-world-move-marker.is-visible {
      opacity: 1;
      animation: ftWorldMoveMarkerDrop 420ms cubic-bezier(0.18, 0.9, 0.24, 1.16) both;
    }

    .ft-world-move-marker.is-arrived {
      animation: ftWorldMoveMarkerArrive 420ms ease-out both;
    }

    .ft-world-move-marker::before,
    .ft-world-move-marker::after,
    .ft-world-move-marker span,
    .ft-world-move-marker i,
    .ft-world-move-marker b {
      content: "";
      position: absolute;
      left: 50%;
      top: 50%;
      border-radius: 999px;
      transform: translate(-50%, -50%);
      pointer-events: none;
    }

    .ft-world-move-marker::before {
      width: 72px;
      height: 72px;
      border: 2px solid rgba(255, 209, 102, 0.74);
      background:
        conic-gradient(from 18deg, rgba(255, 209, 102, 0.0) 0 7%, rgba(255, 209, 102, 0.9) 8% 13%, transparent 14% 27%, rgba(124, 255, 240, 0.86) 28% 34%, transparent 35% 51%, rgba(255, 126, 52, 0.86) 52% 58%, transparent 59% 76%, rgba(255, 209, 102, 0.8) 77% 82%, transparent 83% 100%),
        radial-gradient(circle, rgba(124, 255, 240, 0.14), rgba(255, 126, 52, 0.06) 44%, transparent 66%);
      box-shadow:
        0 0 26px rgba(255, 209, 102, 0.42),
        0 0 38px rgba(124, 255, 240, 0.22),
        inset 0 0 18px rgba(255, 126, 52, 0.12);
      animation: ftWorldMoveMarkerSpin 1.45s linear infinite;
    }

    .ft-world-move-marker::after {
      width: 38px;
      height: 38px;
      border: 1px dashed rgba(124, 255, 240, 0.72);
      box-shadow: inset 0 0 14px rgba(124, 255, 240, 0.14), 0 0 16px rgba(124, 255, 240, 0.2);
      animation: ftWorldMoveMarkerSpinReverse 1.9s linear infinite;
    }

    .ft-world-move-marker span {
      width: 11px;
      height: 11px;
      background: #fff6b8;
      box-shadow: 0 0 18px rgba(255, 209, 102, 0.86), 0 0 32px rgba(255, 126, 52, 0.44);
      animation: ftWorldMoveMarkerCore 900ms ease-in-out infinite;
    }

    .ft-world-move-marker i,
    .ft-world-move-marker b {
      width: 4px;
      height: 54px;
      border-radius: 999px;
      background: linear-gradient(180deg, transparent, rgba(255, 209, 102, 0.82), transparent);
      box-shadow: 0 0 12px rgba(255, 209, 102, 0.4);
      opacity: 0.88;
    }

    .ft-world-move-marker b {
      transform: translate(-50%, -50%) rotate(90deg);
      background: linear-gradient(180deg, transparent, rgba(124, 255, 240, 0.78), transparent);
    }

    .ft-world-move-marker em {
      position: absolute;
      left: 50%;
      top: 50%;
      z-index: 5;
      width: 34px;
      height: 58px;
      pointer-events: none;
      transform-style: preserve-3d;
      transform-origin: 50% 82%;
      animation: ftWorldMoveMarkerArrow 1.55s ease-in-out infinite;
      filter:
        drop-shadow(0 13px 16px rgba(0, 0, 0, 0.34))
        drop-shadow(0 0 16px rgba(255, 209, 102, 0.38));
    }

    .ft-world-move-marker em::before,
    .ft-world-move-marker em::after {
      content: "";
      position: absolute;
      left: 50%;
      pointer-events: none;
      transform: translateX(-50%);
    }

    .ft-world-move-marker em::before {
      top: 0;
      width: 14px;
      height: 38px;
      border: 1px solid rgba(255, 247, 200, 0.9);
      border-radius: 999px 999px 10px 10px;
      background:
        linear-gradient(90deg, rgba(255, 255, 255, 0.82), rgba(255, 209, 102, 0.96) 28%, rgba(255, 126, 52, 0.95) 70%, rgba(124, 255, 240, 0.88)),
        linear-gradient(180deg, rgba(255, 255, 255, 0.24), rgba(0, 0, 0, 0.14));
      box-shadow:
        inset -5px 0 8px rgba(0, 0, 0, 0.24),
        inset 4px 0 6px rgba(255, 255, 255, 0.34),
        0 0 18px rgba(255, 209, 102, 0.56);
