    .ft-world-move-marker em::after {
      bottom: 0;
      width: 0;
      height: 0;
      border-left: 17px solid transparent;
      border-right: 17px solid transparent;
      border-top: 22px solid #ffcf5f;
      filter:
        drop-shadow(0 0 8px rgba(255, 209, 102, 0.92))
        drop-shadow(0 0 17px rgba(255, 126, 52, 0.44));
