    .ft-world-battle-arena::before {
      top: 45%;
      left: 24%;
      width: 44px;
      height: 44px;
      border-radius: 50% 50% 50% 12px;
      background:
        radial-gradient(circle at 31% 23%, #fffbe1 0 10%, transparent 21%),
        radial-gradient(circle at 48% 48%, #fff19f 0 18%, #ffb13d 35%, #ff5b35 58%, #7b1309 76%, rgba(255, 70, 30, 0) 82%),
        conic-gradient(from 210deg, rgba(255, 245, 170, 0.95), rgba(255, 88, 46, 0.9), rgba(255, 176, 61, 0.78), rgba(70, 240, 215, 0.34), rgba(255, 245, 170, 0.95));
