    .ft-world-battle-arena::after {
      top: 48.5%;
      left: 24%;
      width: 42%;
      height: 12px;
      border-radius: 999px;
      background:
        radial-gradient(circle at 6px 50%, #fffbe7 0 3px, transparent 4px),
        linear-gradient(90deg, rgba(255, 245, 190, 0), rgba(255, 255, 235, 0.98) 11%, #7cfff0 29%, #ff477e 55%, rgba(255, 71, 126, 0));
      box-shadow:
        0 0 18px rgba(124, 255, 240, 0.82),
        0 0 36px rgba(255, 71, 126, 0.52),
        0 0 72px rgba(255, 71, 126, 0.24);
      transform-origin: 0 50%;
    }

    .ft-world-battle-card.is-casting-left.is-attack-fire .ft-world-battle-arena::before {
