    .ft-world-battle-player,
    .ft-world-battle-referee {
      position: relative;
      min-height: 0;
      border: 1px solid rgba(70, 240, 215, 0.22);
      border-radius: 20px;
      background:
        radial-gradient(circle at 50% 12%, rgba(255, 126, 52, 0.14), transparent 42%),
