      animation: none !important;
      transition: none !important;
      pointer-events: none !important;
    }

    .ft-auth-panel-fx {
      position: absolute;
      z-index: 4;
      pointer-events: none;
      overflow: visible;
      transform: translateZ(0);
    }

    .ft-auth-corner-flash {
      position: absolute;
      width: 84px;
      height: 84px;
      border-radius: 50%;
      opacity: 0;
      transform: translate(-50%, -50%) scale(0.72);
      background:
        radial-gradient(circle, rgba(255, 255, 255, 0.78) 0 4%, rgba(255, 236, 196, 0.52) 5% 10%, rgba(108, 240, 164, 0.38) 18%, rgba(70, 240, 215, 0.2) 36%, transparent 72%);
      box-shadow:
        0 0 34px rgba(255, 236, 196, 0.52),
        0 0 72px rgba(108, 240, 164, 0.48),
        0 0 118px rgba(70, 240, 215, 0.32);
      mix-blend-mode: screen;
      will-change: transform, opacity, filter;
    }

    .ft-auth-corner-flash::before,
    .ft-auth-corner-flash::after {
      content: "";
      position: absolute;
      inset: 4px;
      border-radius: inherit;
      background: radial-gradient(circle, rgba(255, 255, 255, 0.58), rgba(108, 240, 164, 0.22) 38%, transparent 72%);
      filter: blur(9px);
      opacity: 0;
    }

    .ft-auth-corner-flash::after {
      inset: -18px;
      background: radial-gradient(circle, rgba(70, 240, 215, 0.24), rgba(70, 240, 215, 0.12) 34%, transparent 68%);
      filter: blur(15px);
    }

    .ft-auth-corner-flash.is-corner-0 {
      left: 8px;
      top: 8px;
    }

    .ft-auth-corner-flash.is-corner-1 {
      right: 8px;
      top: 8px;
      transform: translate(50%, -50%) scale(0.72);
    }

    .ft-auth-corner-flash.is-corner-2 {
      right: 8px;
      bottom: 8px;
      transform: translate(50%, 50%) scale(0.72);
    }

    .ft-auth-corner-flash.is-corner-3 {
      left: 8px;
      bottom: 8px;
      transform: translate(-50%, 50%) scale(0.72);
    }

    .ft-auth-panel-shockwave {
      position: absolute;
      inset: -12px;
      border-radius: inherit;
      opacity: 0;
      border: 1px solid rgba(108, 240, 164, 0.78);
      box-shadow:
        0 0 0 1px rgba(255, 236, 196, 0.18),
        0 0 42px rgba(70, 240, 215, 0.45),
        0 0 92px rgba(108, 240, 164, 0.26),
        inset 0 0 28px rgba(108, 240, 164, 0.14);
      background:
        conic-gradient(from 12deg, transparent 0 8%, rgba(255, 236, 196, 0.62) 9% 11%, transparent 12% 24%, rgba(70, 240, 215, 0.5) 25% 28%, transparent 29% 44%, rgba(108, 240, 164, 0.62) 45% 48%, transparent 49% 66%, rgba(255, 142, 72, 0.38) 67% 70%, transparent 71% 100%);
      transform: scale(0.985);
      mix-blend-mode: screen;
      will-change: transform, opacity, filter;
    }

    .ft-auth-panel-shockwave::before,
    .ft-auth-panel-shockwave::after {
      content: "";
      position: absolute;
      inset: -8px;
      border-radius: inherit;
      opacity: 0;
      pointer-events: none;
    }

    .ft-auth-panel-shockwave::before {
      border: 1px solid rgba(255, 236, 196, 0.48);
      box-shadow:
        0 0 22px rgba(255, 236, 196, 0.32),
        0 0 50px rgba(70, 240, 215, 0.28);
      clip-path: polygon(0 0, 42% 0, 42% 8%, 58% 8%, 58% 0, 100% 0, 100% 44%, 92% 44%, 92% 58%, 100% 58%, 100% 100%, 54% 100%, 54% 92%, 40% 92%, 40% 100%, 0 100%, 0 56%, 8% 56%, 8% 42%, 0 42%);
    }

    .ft-auth-panel-shockwave::after {
      inset: -18px;
      background:
        linear-gradient(115deg, transparent 0 18%, rgba(255, 236, 196, 0.7) 19%, transparent 21% 100%),
        linear-gradient(245deg, transparent 0 28%, rgba(70, 240, 215, 0.58) 29%, transparent 31% 100%),
        linear-gradient(22deg, transparent 0 62%, rgba(108, 240, 164, 0.5) 63%, transparent 65% 100%);
      filter: blur(1.5px);
    }

    .ft-auth-hud,
    .ft-auth-clock {
      position: absolute;
      z-index: 2;
      pointer-events: none;
      border: 1px solid rgba(70, 240, 215, 0.3);
      background: linear-gradient(180deg, rgba(8, 28, 30, 0.78), rgba(4, 12, 14, 0.66));
      box-shadow: 0 24px 70px rgba(0, 0, 0, 0.42), 0 0 34px rgba(70, 240, 215, 0.12), inset 0 0 22px rgba(70, 240, 215, 0.08);
      -webkit-backdrop-filter: blur(12px);
      backdrop-filter: blur(12px);
      transition:
        opacity 300ms cubic-bezier(.16, .84, .22, 1),
        transform 360ms cubic-bezier(.16, .84, .22, 1),
        filter 360ms cubic-bezier(.16, .84, .22, 1);
    }

    .ft-auth-hud {
      left: clamp(16px, 5vw, 76px);
      top: 50%;
      width: min(330px, 28vw);
      min-height: 230px;
      max-height: min(430px, 72vh);
      border-radius: 18px;
      padding: 15px;
      transform: translateY(-50%);
      overflow: hidden;
    }

    .ft-auth-hud::before {
      content: "";
      position: absolute;
      inset: 0;
      background:
        linear-gradient(90deg, rgba(70, 240, 215, 0.065) 1px, transparent 1px),
        linear-gradient(180deg, rgba(255, 255, 255, 0.05), transparent 45%);
      background-size: 18px 100%, auto;
      pointer-events: none;
      opacity: 0.9;
    }

    .ft-auth-hud::after {
      content: "";
      position: absolute;
      top: -30%;
      right: -18%;
      width: 132px;
      height: 132px;
      border-radius: 50%;
      background: radial-gradient(circle, rgba(255, 142, 72, 0.2), transparent 64%);
      filter: blur(4px);
      pointer-events: none;
    }

    .ft-auth-hud-head,
    .ft-auth-hud-list,
    .ft-auth-hud-status {
      position: relative;
      z-index: 1;
    }

    .ft-auth-hud-head {
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      gap: 12px;
      min-height: 56px;
      padding-right: 64px;
    }

    .ft-auth-hud-title {
      margin: 0;
      color: var(--cyan);
      font-size: 12px;
      font-weight: 950;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    .ft-auth-hud-stamp {
      color: rgba(255, 236, 196, 0.86);
      font-size: 10px;
      font-weight: 950;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    .ft-auth-hud-effect {
      position: absolute;
      top: 13px;
      right: 13px;
      z-index: 2;
      width: 56px;
      height: 56px;
      border: 1px solid rgba(70, 240, 215, 0.58);
      border-radius: 16px;
      background:
        radial-gradient(circle at 50% 50%, rgba(108, 240, 164, 0.62), transparent 10px),
        linear-gradient(135deg, rgba(70, 240, 215, 0.22), rgba(255, 142, 72, 0.16));
      box-shadow: 0 0 34px rgba(70, 240, 215, 0.28), inset 0 0 22px rgba(70, 240, 215, 0.18);
      overflow: hidden;
    }

    .ft-auth-hud-effect::before,
    .ft-auth-hud-effect::after {
      content: "";
      position: absolute;
      inset: 8px;
      border-radius: 50%;
      border: 1px dashed rgba(108, 240, 164, 0.82);
      animation: authClockSpin 5.4s linear infinite;
    }

    .ft-auth-hud-effect::after {
      inset: 17px;
      border-style: solid;
      border-color: rgba(255, 178, 96, 0.68);
      animation-duration: 3.2s;
      animation-direction: reverse;
    }

    .ft-auth-hud-scan {
      position: absolute;
      left: 50%;
      bottom: 50%;
      width: 2px;
      height: 25px;
      transform-origin: bottom center;
      background: linear-gradient(180deg, rgba(247, 255, 249, 0.92), transparent);
      box-shadow: 0 0 12px rgba(108, 240, 164, 0.76);
      animation: authClockSpin 2.2s linear infinite;
    }

    .ft-auth-hud-list {
      display: grid;
      gap: 9px;
      max-height: 275px;
      overflow: hidden;
      padding-right: 2px;
    }

    .ft-auth-hud-message {
      position: relative;
      padding: 9px 10px 9px 13px;
      border: 1px solid rgba(70, 240, 215, 0.13);
      border-left-color: rgba(108, 240, 164, 0.68);
      border-radius: 12px;
      color: rgba(247, 255, 249, 0.9);
      background:
        linear-gradient(90deg, rgba(70, 240, 215, 0.09), transparent),
        rgba(3, 12, 14, 0.42);
      font-size: 12px;
      font-weight: 850;
      line-height: 1.42;
      box-shadow: inset 0 0 18px rgba(70, 240, 215, 0.045);
    }

    .ft-auth-hud-message::first-letter {
      color: #ffffff;
      font-size: 1.12em;
      font-weight: 950;
      text-transform: uppercase;
    }

    .ft-auth-hud-message::before {
      content: "";
      position: absolute;
      left: -4px;
      top: 13px;
      width: 7px;
      height: 7px;
      border-radius: 50%;
      background: var(--green);
      box-shadow: 0 0 14px rgba(108, 240, 164, 0.72);
    }

    .ft-auth-hud-message:nth-child(2n) {
      border-left-color: rgba(255, 142, 72, 0.62);
      background:
        linear-gradient(90deg, rgba(255, 142, 72, 0.085), transparent),
        rgba(3, 12, 14, 0.42);
    }

    .ft-auth-hud-message:nth-child(2n)::before {
      background: var(--orange);
      box-shadow: 0 0 14px rgba(255, 142, 72, 0.66);
    }

    /* Added 2026-07-07: login HUD exposes frontend version/update time for cache checks. */
    .ft-auth-hud-version {
      border-left-color: rgba(255, 194, 84, 0.72);
      color: #ffcf73;
      background:
        linear-gradient(90deg, rgba(255, 194, 84, 0.13), transparent),
        rgba(3, 12, 14, 0.48);
    }

    .ft-auth-hud-version::before {
      background: #ffb84c;
      box-shadow: 0 0 14px rgba(255, 194, 84, 0.7);
    }

    .ft-auth-hud-status {
      margin-top: 13px;
      display: grid;
      grid-template-columns: auto 1fr;
      gap: 8px;
      align-items: center;
      color: var(--muted);
      font-size: 11px;
      font-weight: 850;
    }

    .ft-auth-hud-pulse {
      width: 10px;
      height: 10px;
      border-radius: 50%;
      background: var(--green);
      box-shadow: 0 0 18px rgba(108, 240, 164, 0.8);
      animation: authNodePulse 1.4s ease-in-out infinite;
    }

    .ft-auth-clock {
      right: clamp(16px, 5vw, 76px);
      top: 50%;
      width: 168px;
      height: 168px;
      border-radius: 50%;
      transform: translateY(-50%);
      display: grid;
      place-items: center;
    }

    .ft-auth-clock::before,
    .ft-auth-clock::after {
      content: "";
      position: absolute;
      border-radius: 50%;
      pointer-events: none;
    }

    .ft-auth-clock::before {
      inset: 18px;
      border: 1px dashed rgba(108, 240, 164, 0.42);
      animation: authClockSpin 10s linear infinite;
    }

    .ft-auth-clock::after {
      inset: 42px;
      border: 1px solid rgba(255, 142, 72, 0.34);
      box-shadow: inset 0 0 18px rgba(255, 142, 72, 0.08);
      animation: authClockSpin 6s linear infinite reverse;
    }

    .ft-auth-clock-hand {
      position: absolute;
      width: 2px;
      height: 58px;
      top: 26px;
      left: 50%;
      transform-origin: bottom center;
      background: linear-gradient(180deg, var(--cyan), transparent);
      filter: drop-shadow(0 0 9px rgba(70, 240, 215, 0.8));
      animation: authClockSpin 4.8s linear infinite;
    }

    .ft-auth-clock-core {
      position: relative;
      z-index: 1;
      width: 70px;
      height: 70px;
      border-radius: 50%;
      display: grid;
      place-items: center;
      color: var(--ink);
      font-size: 12px;
      font-weight: 950;
      background: radial-gradient(circle, rgba(70, 240, 215, 0.24), rgba(70, 240, 215, 0.04) 64%, transparent);
      box-shadow: 0 0 28px rgba(70, 240, 215, 0.2);
    }

    .ft-login-vault-preview {
      position: fixed;
      inset: 0;
      z-index: 48;
      display: grid;
      place-items: center;
      padding: 18px;
      pointer-events: none;
      opacity: 0;
      transform: scale(0.985);
      transition: opacity 420ms cubic-bezier(.16, .84, .22, 1), transform 420ms cubic-bezier(.16, .84, .22, 1);
      background:
        radial-gradient(circle at 50% 20%, rgba(70, 240, 215, 0.18), transparent 36%),
        radial-gradient(circle at 82% 78%, rgba(255, 142, 72, 0.11), transparent 30%),
        rgba(2, 7, 8, 0.35);
    }

    .ft-login-vault-preview.is-visible {
      opacity: 0.88;
      transform: scale(1);
    }

    .ft-login-vault-shell {
      width: min(1120px, calc(100vw - 36px));
      height: min(680px, 82dvh);
      display: grid;
      grid-template-rows: auto 1fr;
      gap: 14px;
      filter: blur(0.25px) saturate(0.96) brightness(0.92);
    }

    .ft-login-vault-tabs {
      display: flex;
      gap: 10px;
      justify-content: center;
    }

    .ft-login-vault-tabs span {
      min-width: 148px;
      padding: 10px 18px;
      border: 1px solid rgba(70, 240, 215, 0.3);
      border-radius: 8px;
      background: linear-gradient(135deg, rgba(5, 18, 18, 0.86), rgba(13, 36, 33, 0.58));
      color: rgba(220, 255, 247, 0.86);
      font: 800 11px/1.1 var(--font-ui);
      letter-spacing: 0.12em;
      text-align: center;
      text-transform: uppercase;
      box-shadow: 0 18px 42px rgba(0, 0, 0, 0.34), inset 0 0 22px rgba(70, 240, 215, 0.08);
    }

    .ft-login-vault-tabs span.is-active {
      border-color: rgba(70, 240, 215, 0.58);
      background: linear-gradient(135deg, rgba(14, 54, 48, 0.88), rgba(8, 26, 26, 0.66));
      color: rgba(245, 255, 252, 0.96);
      box-shadow: 0 0 26px rgba(70, 240, 215, 0.18), inset 0 -2px 0 rgba(255, 142, 72, 0.42);
    }

    .ft-login-vault-grid {
      display: grid;
      grid-template-columns: minmax(360px, 1fr) minmax(360px, 0.92fr);
      gap: 16px;
      min-height: 0;
    }

    .ft-login-vault-panel {
      position: relative;
      min-height: 0;
      border: 1px solid rgba(70, 240, 215, 0.2);
      border-radius: 14px;
      padding: 18px;
      overflow: hidden;
      background:
        linear-gradient(135deg, rgba(4, 16, 18, 0.78), rgba(7, 27, 26, 0.62)),
        radial-gradient(circle at 18% 0%, rgba(70, 240, 215, 0.16), transparent 36%);
      box-shadow: 0 22px 66px rgba(0, 0, 0, 0.42), inset 0 0 30px rgba(70, 240, 215, 0.06);
    }

    .ft-login-vault-panel::before,
    .ft-login-vault-panel::after {
      content: "";
      position: absolute;
      pointer-events: none;
    }

    .ft-login-vault-panel::before {
      inset: 12px;
      border-top: 1px solid rgba(70, 240, 215, 0.26);
      border-right: 1px solid rgba(70, 240, 215, 0.18);
      clip-path: polygon(0 0, 84% 0, 100% 22px, 100% 100%, 0 100%);
      opacity: 0.7;
    }

    .ft-login-vault-panel::after {
      right: 18px;
      bottom: 16px;
      width: 110px;
      height: 2px;
      background: linear-gradient(90deg, transparent, rgba(255, 142, 72, 0.65), rgba(70, 240, 215, 0.5), transparent);
      opacity: 0.72;
    }

    .ft-login-vault-head {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 14px;
      margin-bottom: 14px;
      color: rgba(234, 255, 250, 0.9);
      font: 900 13px/1.1 var(--font-ui);
      letter-spacing: 0.1em;
      text-transform: uppercase;
    }

    .ft-login-vault-head small {
      color: rgba(255, 184, 120, 0.78);
      font-size: 10px;
      letter-spacing: 0.12em;
    }

    .ft-login-vault-path {
      display: flex;
      flex-wrap: wrap;
      gap: 8px;
      margin: 0 0 12px;
    }

    .ft-login-vault-path span {
      padding: 7px 10px;
      border: 1px solid rgba(70, 240, 215, 0.22);
      border-radius: 7px;
      color: rgba(220, 255, 247, 0.86);
      background: linear-gradient(135deg, rgba(70, 240, 215, 0.1), rgba(5, 18, 18, 0.56));
      font: 800 10px/1 var(--font-ui);
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    .ft-login-vault-toolbar {
      display: flex;
      align-items: center;
      gap: 10px;
      min-height: 40px;
      margin: 0 0 14px;
      padding: 9px 12px;
      border: 1px solid rgba(255, 142, 72, 0.2);
      border-radius: 10px;
      background: linear-gradient(135deg, rgba(255, 142, 72, 0.12), rgba(70, 240, 215, 0.06));
      color: rgba(238, 255, 249, 0.84);
      font: 800 11px/1.25 var(--font-ui);
    }

    .ft-login-vault-toolbar b {
      color: rgba(255, 188, 128, 0.92);
      text-transform: uppercase;
      letter-spacing: 0.08em;
    }

    .ft-login-vault-stats {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 8px;
      margin: 0 0 14px;
    }

    .ft-login-vault-stats span {
      min-width: 0;
      padding: 10px 8px;
      border: 1px solid rgba(70, 240, 215, 0.18);
      border-radius: 10px;
      color: rgba(215, 255, 246, 0.78);
      background: linear-gradient(135deg, rgba(70, 240, 215, 0.1), rgba(255, 142, 72, 0.055));
      font: 800 10px/1.2 var(--font-ui);
      text-align: center;
      text-transform: uppercase;
    }

    .ft-login-vault-stats b {
      display: block;
      color: rgba(247, 255, 252, 0.96);
      font-size: 16px;
      line-height: 1.05;
    }

    .ft-login-vault-list,
    .ft-login-task-stack {
      display: grid;
      gap: 12px;
    }

    .ft-login-vault-item,
    .ft-login-task-item {
      display: grid;
      grid-template-columns: auto 1fr auto;
      align-items: center;
      gap: 12px;
      min-height: 74px;
      padding: 12px;
      border: 1px solid rgba(70, 240, 215, 0.14);
      border-radius: 12px;
      background: linear-gradient(135deg, rgba(8, 28, 28, 0.72), rgba(8, 20, 20, 0.54));
      box-shadow: inset 0 0 20px rgba(70, 240, 215, 0.04);
    }

    .ft-login-vault-orb {
      display: grid;
      place-items: center;
      width: 42px;
      height: 42px;
      border-radius: 50%;
      border: 1px solid rgba(70, 240, 215, 0.28);
      color: rgba(235, 255, 249, 0.84);
      font: 900 12px/1 var(--font-ui);
      background: radial-gradient(circle at 35% 30%, rgba(70, 240, 215, 0.36), rgba(255, 142, 72, 0.09) 58%, rgba(6, 20, 20, 0.88));
    }

    .ft-login-vault-title {
      display: block;
      min-width: 0;
      max-width: min(340px, 42vw);
      color: rgba(245, 255, 252, 0.94);
      font: 900 13px/1.22 var(--font-ui);
      letter-spacing: 0.02em;
      white-space: normal;
    }

    .ft-login-vault-meta {
      display: block;
      max-width: min(320px, 40vw);
      margin-top: 10px;
      color: rgba(167, 218, 208, 0.76);
      font: normal 800 10px/1.25 var(--font-ui);
      letter-spacing: 0.06em;
      text-transform: uppercase;
    }

    .ft-login-vault-progress {
      --p: 50%;
      width: 58px;
      height: 58px;
      border-radius: 50%;
      background:
        radial-gradient(circle at center, rgba(4, 14, 14, 0.9) 0 47%, transparent 48%),
        conic-gradient(from -80deg, rgba(70, 240, 215, 0.76) 0 var(--p), rgba(255, 142, 72, 0.2) var(--p), rgba(70, 240, 215, 0.08));
      box-shadow: 0 0 18px rgba(70, 240, 215, 0.16);
    }

    .ft-login-task-item {
      grid-template-columns: 1fr auto;
      min-height: 94px;
      border-color: rgba(255, 142, 72, 0.18);
      background: linear-gradient(135deg, rgba(29, 18, 12, 0.62), rgba(6, 22, 22, 0.64));
    }

    .ft-login-task-severity {
      min-width: 72px;
      min-height: 24px;
      display: grid;
      place-items: center;
      border-radius: 999px;
      border: 1px solid rgba(255, 142, 72, 0.36);
      background: linear-gradient(90deg, rgba(255, 142, 72, 0.26), rgba(70, 240, 215, 0.1));
      color: rgba(255, 226, 196, 0.92);
      font: 900 9px/1 var(--font-ui);
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    .ft-login-task-item.is-critical .ft-login-task-severity {
      border-color: rgba(255, 98, 98, 0.5);
      color: rgba(255, 210, 210, 0.96);
      background: linear-gradient(90deg, rgba(255, 80, 80, 0.28), rgba(255, 142, 72, 0.12));
    }

    .ft-login-task-item.is-high .ft-login-task-severity {
      border-color: rgba(255, 190, 90, 0.48);
      color: rgba(255, 235, 190, 0.96);
      background: linear-gradient(90deg, rgba(255, 184, 72, 0.25), rgba(70, 240, 215, 0.08));
    }

    @media (max-width: 760px) {
      .ft-login-vault-preview {
        padding: 10px;
      }

      .ft-login-vault-shell {
        height: calc(100dvh - 20px);
      }

      .ft-login-vault-grid {
        grid-template-columns: 1fr;
      }

      .ft-login-vault-panel.is-task {
        display: none;
      }
    }

    .ft-auth-panel::before,
    .ft-auth-panel::after {
      content: "";
      position: absolute;
      pointer-events: none;
    }

    .ft-auth-panel::before {
      inset: -1px;
      border-radius: inherit;
      background:
        linear-gradient(90deg, transparent, rgba(70, 240, 215, 0.42), transparent),
        linear-gradient(180deg, transparent, rgba(255, 142, 72, 0.22), transparent);
      opacity: 0.38;
      mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
      -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
      padding: 1px;
      mask-composite: exclude;
      -webkit-mask-composite: xor;
      animation: authBorderSweep 3.2s linear infinite;
    }

    .ft-auth-panel::after {
      display: none;
      animation: none;
    }

    .ft-auth-orb {
      width: 48px;
