    .ft-auth-eye-icon::after {
      content: "";
      position: absolute;
      left: -3px;
      right: -3px;
      top: 50%;
      height: 2px;
      border-radius: 999px;
      background: currentColor;
      opacity: 0;
      transform: translateY(-50%) rotate(-34deg);
    }

    .ft-auth-secret-toggle.is-visible .ft-auth-eye-icon::after {
      opacity: 1;
