    .ft-auth-gate:not(.is-auth-motion-full) .ft-auth-clock::after {
      animation: authClockSpin 7s linear infinite reverse !important;
    }

    .ft-auth-gate:not(.is-auth-motion-full) .ft-auth-clock-hand,
    .ft-auth-gate:not(.is-auth-motion-full) .ft-auth-hud-scan {
      animation: authClockSpin 4.8s linear infinite !important;
    }

    .ft-auth-gate:not(.is-auth-motion-full) .ft-auth-hud-effect::before {
      animation: authClockSpin 5.4s linear infinite !important;
    }

    .ft-auth-gate:not(.is-auth-motion-full) .ft-auth-hud-effect::after {
