    @keyframes authBorderSweep {
      0% { opacity: 0.22; transform: translateX(-18%); }
      50% { opacity: 0.5; }
      100% { opacity: 0.22; transform: translateX(18%); }
    }

    @keyframes authScan {
      0%, 100% { transform: translateY(0); opacity: 0.22; }
      50% { transform: translateY(260px); opacity: 0.7; }
    }

    @keyframes authConnectorFlow {
      to { stroke-dashoffset: -96; }
    }

    @keyframes authConnectorSpark {
      to { stroke-dashoffset: -128; }
    }

    @keyframes authRungPulse {
      0%, 100% { opacity: 0.34; }
      50% { opacity: 0.92; }
    }

    @keyframes authNodePulse {
      0%, 100% { opacity: 0.55; transform: scale(0.8); }
      50% { opacity: 1; transform: scale(1.25); }
    }

    @keyframes authCornerImpactFlash {
      0% { opacity: 0; filter: brightness(1); }
      12% { opacity: 0.95; filter: brightness(1.85) blur(0); }
      38% { opacity: 0.58; filter: brightness(1.32) blur(0.4px); }
      100% { opacity: 0; filter: brightness(1) blur(1.8px); }
    }

    @keyframes authCornerImpactReticle {
      0% { opacity: 0; transform: scale(0.55); }
      20% { opacity: 0.82; }
      100% { opacity: 0; transform: scale(1.62); }
    }

    @keyframes authPanelBorderShockwave {
      0% { opacity: 0; transform: scale(0.985); filter: brightness(1); }
      10% { opacity: 0.92; transform: scale(1); filter: brightness(2.1); }
      36% { opacity: 0.7; transform: scale(1.038); filter: brightness(1.55); }
      100% { opacity: 0; transform: scale(1.14); filter: brightness(1); }
    }

    @keyframes authPanelElectricFrame {
      0% { opacity: 0; transform: scale(0.99); filter: brightness(1); }
      14% { opacity: 1; transform: scale(1.01); filter: brightness(2.2); }
      46% { opacity: 0.72; transform: scale(1.05); filter: brightness(1.45); }
      100% { opacity: 0; transform: scale(1.16); filter: brightness(1); }
    }

    @keyframes authPanelElectricTrace {
      0% { opacity: 0; transform: translate3d(-8px, 5px, 0) scale(0.98); }
      12% { opacity: 0.9; }
      28% { opacity: 0.42; transform: translate3d(7px, -3px, 0) scale(1.01); }
      42% { opacity: 0.74; transform: translate3d(-4px, -7px, 0) scale(1.035); }
      64% { opacity: 0.32; transform: translate3d(8px, 6px, 0) scale(1.07); }
      100% { opacity: 0; transform: translate3d(0, 0, 0) scale(1.16); }
    }

    @keyframes authHudLine {
      0%, 100% { transform: scaleX(0.58); opacity: 0.45; }
      50% { transform: scaleX(1); opacity: 1; }
    }

    @keyframes authClockSpin {
      to { transform: rotate(360deg); }
    }

    @keyframes authActionSweep {
      0%, 42% { transform: translateX(-120%); }
      78%, 100% { transform: translateX(120%); }
    }

