    .ft-task-user-notice-face {
      position: absolute;
      right: 22px;
      top: 24px;
      z-index: 2;
      width: 126px;
      height: 142px;
      display: grid;
      grid-template-columns: repeat(11, 1fr);
      grid-template-rows: repeat(12, 1fr);
      gap: 3px;
      opacity: 0;
      transform: translateY(8px) scale(0.94);
      pointer-events: none;
      filter: drop-shadow(0 0 18px rgba(70, 240, 215, 0.34));
    }

    .ft-task-user-notice.is-face-style.is-live .ft-task-user-notice-face {
      opacity: 1;
      transform: translateY(0) scale(1);
    }

    .ft-task-user-notice-face span {
      --tx: 0px;
      --ty: 0px;
      --d: 0ms;
      border: 1px solid rgba(236, 255, 249, 0.16);
      border-radius: 3px;
      background: rgba(70, 240, 215, 0.22);
      box-shadow:
        inset 0 0 8px rgba(236, 255, 249, 0.08),
        0 0 10px rgba(70, 240, 215, 0.16);
      opacity: 0;
      transform: translate(var(--tx), var(--ty)) scale(0.18) rotate(18deg);
    }

    .ft-task-user-notice.is-face-style.is-live .ft-task-user-notice-face span {
      animation: taskNoticeFaceAssemble 720ms cubic-bezier(.14, .88, .18, 1) var(--d) both;
    }

    .ft-task-user-notice-face .is-core {
      background: linear-gradient(135deg, rgba(70, 240, 215, 0.42), rgba(216, 108, 255, 0.22));
      border-color: rgba(70, 240, 215, 0.28);
    }

    .ft-task-user-notice-face .is-edge {
      background: rgba(255, 194, 84, 0.24);
      border-color: rgba(255, 194, 84, 0.26);
    }

    .ft-task-user-notice-face .is-eye {
      background: rgba(236, 255, 249, 0.9);
      border-color: rgba(236, 255, 249, 0.72);
      box-shadow:
        0 0 16px rgba(236, 255, 249, 0.75),
        0 0 28px rgba(70, 240, 215, 0.36);
    }

    .ft-task-user-notice-face .is-mouth {
      background: rgba(255, 194, 84, 0.7);
      border-color: rgba(255, 226, 158, 0.68);
      box-shadow: 0 0 14px rgba(255, 194, 84, 0.55);
    }

    .ft-task-user-notice.is-face-style.is-speaking .ft-task-user-notice-face .is-eye {
      animation:
        taskNoticeFaceAssemble 720ms cubic-bezier(.14, .88, .18, 1) var(--d) both,
        taskNoticeFaceEye 1.4s ease-in-out 760ms infinite;
    }

    .ft-task-user-notice.is-face-style.is-speaking .ft-task-user-notice-face .is-mouth,
    .ft-task-user-notice.is-face-style.is-live .ft-task-user-notice-face .is-mouth {
      animation:
        taskNoticeFaceAssemble 720ms cubic-bezier(.14, .88, .18, 1) var(--d) both,
        taskNoticeFaceTalk 520ms steps(4, end) 760ms infinite;
    }

    .ft-task-user-notice.is-face-style.is-speaking .ft-task-user-notice-face .is-core {
      animation:
        taskNoticeFaceAssemble 720ms cubic-bezier(.14, .88, .18, 1) var(--d) both,
        taskNoticeFacePulse 1.1s ease-in-out 760ms infinite;
    }

    @keyframes taskNoticeFaceAssemble {
      0% {
        opacity: 0;
        transform: translate(var(--tx), var(--ty)) scale(0.18) rotate(18deg);
        filter: blur(2px) brightness(1.8);
      }
      62% {
        opacity: 1;
        transform: translate(0, 0) scale(1.12) rotate(0deg);
        filter: blur(0) brightness(1.38);
      }
      100% {
        opacity: 1;
        transform: translate(0, 0) scale(1) rotate(0deg);
        filter: blur(0) brightness(1);
      }
    }

    @keyframes taskNoticeFaceEye {
      0%, 100% { filter: brightness(1); }
      45% { filter: brightness(1.9); }
      52% { filter: brightness(0.35); }
      60% { filter: brightness(2.2); }
    }

    @keyframes taskNoticeFaceTalk {
      0%, 100% { transform: translate(0, 0) scale(1); }
      50% { transform: translate(0, 1px) scaleY(1.55); }
    }

    @keyframes taskNoticeFacePulse {
      0%, 100% { box-shadow: inset 0 0 8px rgba(236, 255, 249, 0.08), 0 0 10px rgba(70, 240, 215, 0.16); }
      50% { box-shadow: inset 0 0 14px rgba(236, 255, 249, 0.16), 0 0 18px rgba(70, 240, 215, 0.38); }
    }

