        linear-gradient(90deg, transparent 0%, rgba(255, 194, 84, 0.5) 18%, rgba(236, 255, 249, 0.48) 50%, rgba(70, 240, 215, 0.28) 82%, transparent 100%) top / 100% 1px no-repeat,
        linear-gradient(90deg, transparent 0%, rgba(70, 240, 215, 0.24) 18%, rgba(255, 194, 84, 0.42) 50%, rgba(216, 108, 255, 0.18) 82%, transparent 100%) bottom / 100% 1px no-repeat,
        radial-gradient(ellipse at 50% 0, rgba(255, 194, 84, 0.1), transparent 46%) top / 100% 34px no-repeat,
        radial-gradient(ellipse at 50% 100%, rgba(70, 240, 215, 0.1), transparent 48%) bottom / 100% 34px no-repeat;
