    .ft-task-card::before {
      content: "";
      position: absolute;
      left: 11px;
      right: 11px;
      top: 8px;
      height: 1px;
      z-index: 1;
      background:
        linear-gradient(90deg, transparent 0%, rgba(70, 240, 215, 0.15) 22%, rgba(239, 254, 250, 0.84) 34%, rgba(255, 194, 84, 0.34) 47%, transparent 68%);
      background-size: 230% 100%;
