    .ft-space-navigator {
      --nav-x: 0px;
      --nav-y: 0px;
      --nav-power: 0;
      --nav-speed: 0;
      --nav-conic-angle: 35deg;
      --nav-vector-width: 18px;
      --nav-vector-opacity: 0.28;
      --nav-dot-opacity: 0.26;
      --nav-tilt-x: 0deg;
      --nav-tilt-y: 0deg;
      position: fixed;
      right: clamp(16px, 2.6vw, 30px);
      bottom: clamp(16px, 2.6vw, 30px);
      z-index: 90;
      display: none;
      width: clamp(94px, 9vw, 132px);
      aspect-ratio: 1;
      border: 1px solid rgba(126, 255, 235, 0.54);
      border-radius: 50%;
      padding: 0;
      place-items: center;
      color: rgba(236, 255, 249, 0.92);
      background:
        radial-gradient(circle at 38% 28%, rgba(236, 255, 249, 0.34), transparent 0 8%, rgba(70, 240, 215, 0.18) 9% 22%, transparent 23%),
        radial-gradient(circle at 62% 70%, rgba(255, 209, 102, 0.18), transparent 0 10%, transparent 18%),
        radial-gradient(circle at 50% 50%, rgba(70, 240, 215, 0.22), transparent 62%),
        repeating-radial-gradient(circle at 50% 50%, transparent 0 13px, rgba(126, 255, 235, 0.18) 14px 15px, transparent 16px 27px),
        conic-gradient(from var(--nav-conic-angle), rgba(70, 240, 215, 0.12), rgba(216, 108, 255, 0.3), rgba(255, 209, 102, 0.18), rgba(70, 240, 215, 0.12));
      box-shadow:
        0 0 0 1px rgba(236, 255, 249, 0.06) inset,
        0 0 26px rgba(70, 240, 215, 0.28),
        0 18px 54px rgba(0, 0, 0, 0.34);
      cursor: crosshair;
      user-select: none;
      touch-action: none;
      opacity: 0;
      transform: translate3d(0, 8px, 0) scale(0.96);
      transition: opacity 180ms ease, transform 180ms ease, filter 180ms ease;
      overflow: hidden;
    }

    .ft-space-navigator.is-live {
      display: grid;
      opacity: 0.86;
      transform: translate3d(0, 0, 0) scale(1) rotateX(var(--nav-tilt-y)) rotateY(var(--nav-tilt-x));
    }

    .ft-space-navigator.is-live:not(.is-near):not(.is-active):not(.is-coasting) {
      opacity: 0;
      pointer-events: none;
      transform: translate3d(0, 10px, 0) scale(0.58);
      filter: saturate(0.8) brightness(0.72);
    }

    .ft-space-navigator.is-live.is-near,
    .ft-space-navigator.is-live.is-active,
    .ft-space-navigator.is-live.is-coasting {
      pointer-events: auto;
    }

    .ft-space-navigator:hover,
    .ft-space-navigator.is-near,
    .ft-space-navigator.is-active,
    .ft-space-navigator.is-coasting {
      opacity: 1;
      filter: brightness(1.14) saturate(1.18);
    }

    .ft-space-navigator::before,
    .ft-space-navigator::after {
      content: "";
      position: absolute;
      pointer-events: none;
      border-radius: 50%;
    }

    .ft-space-navigator::before {
      inset: 8%;
      border: 1px solid rgba(236, 255, 249, 0.3);
      background:
        linear-gradient(90deg, transparent 0 47%, rgba(126, 255, 235, 0.54) 48% 52%, transparent 53%),
        linear-gradient(180deg, transparent 0 47%, rgba(216, 108, 255, 0.32) 48% 52%, transparent 53%);
      transform: rotateX(64deg) rotateZ(-18deg);
      box-shadow: 0 0 18px rgba(70, 240, 215, 0.2);
    }

    .ft-space-navigator::after {
      inset: -8%;
      border: 1px dashed rgba(126, 255, 235, 0.36);
      animation: ftSpaceNavigatorOrbit 10s linear infinite;
    }

    .ft-space-navigator.is-active::after,
    .ft-space-navigator.is-coasting::after {
      animation-duration: 6.8s;
    }

    .ft-space-navigator:not(.is-near):not(:hover):not(.is-active):not(.is-coasting)::after,
    .ft-space-navigator:not(.is-near):not(:hover):not(.is-active):not(.is-coasting) .ft-space-navigator-ring,
    .ft-space-navigator:not(.is-near):not(:hover):not(.is-active):not(.is-coasting) .ft-space-navigator-spark {
      animation-play-state: paused;
    }

