    .ft-inventory-gem {
      --ig-core: #ffffff;
      --ig-mid: #7effeb;
      --ig-deep: #167f6e;
      --ig-glow: rgba(126, 255, 235, 0.6);
      --ig-facets:
        conic-gradient(from var(--ig-spin, 210deg) at 50% 46%,
          color-mix(in srgb, var(--ig-core) 92%, transparent) 0deg,
          var(--ig-mid) 34deg,
          var(--ig-deep) 70deg,
          var(--ig-mid) 104deg,
          color-mix(in srgb, var(--ig-core) 88%, transparent) 142deg,
          var(--ig-deep) 188deg,
          var(--ig-mid) 232deg,
          var(--ig-deep) 286deg,
          var(--ig-mid) 326deg,
          color-mix(in srgb, var(--ig-core) 92%, transparent) 360deg);
      position: relative;
      width: 40px;
      aspect-ratio: 1;
      clip-path: polygon(50% 0, 88% 23%, 75% 78%, 50% 100%, 25% 78%, 12% 23%);
      background:
        radial-gradient(130% 100% at 42% -16%, rgba(255, 255, 255, 0.96), rgba(255, 255, 255, 0) 40%),
        var(--ig-facets),
        linear-gradient(158deg, var(--ig-mid), var(--ig-deep) 100%);
      filter:
        saturate(1.28)
        drop-shadow(0 4px 6px rgba(0, 0, 0, 0.42))
        drop-shadow(0 0 11px var(--ig-glow));
      animation: cupRewardGemFloat 3600ms ease-in-out infinite;
    }

    /* crown sheen + faint internal facet seams */
    .ft-inventory-gem::before {
      content: "";
      position: absolute;
      inset: 0;
      clip-path: inherit;
      pointer-events: none;
      background:
        linear-gradient(180deg, rgba(255, 255, 255, 0.95) 0%, rgba(255, 255, 255, 0.16) 16%, rgba(255, 255, 255, 0) 36%),
        linear-gradient(58deg, rgba(255, 255, 255, 0) 46%, rgba(255, 255, 255, 0.4) 50%, rgba(255, 255, 255, 0) 54%),
