    .ft-q-root-text {
      --q-root-line-height: 1.34;
      margin: 0;
      min-height: 2.2em;
      position: relative;
      display: block;
      align-self: stretch;
      color: #f4fffb;
      font-size: var(--q-root-font-size, clamp(28px, 5vw, 56px));
      line-height: var(--q-root-line-height);
      letter-spacing: 0;
      text-shadow: 0 0 28px rgba(70, 240, 215, 0.22);
      white-space: pre-wrap;
      tab-size: 4;
      isolation: isolate;
      min-height: 0;
      overflow-x: hidden;
      overflow-y: auto;
      overscroll-behavior: contain;
      scrollbar-gutter: stable;
      padding: 24px 12px 30px 0;
      scroll-padding-block: 30px;
      -webkit-mask-image: linear-gradient(180deg, transparent 0, #000 30px, #000 calc(100% - 34px), transparent 100%);
      mask-image: linear-gradient(180deg, transparent 0, #000 30px, #000 calc(100% - 34px), transparent 100%);
      scrollbar-width: thin;
      scrollbar-color: transparent transparent;
      cursor: default;
      -webkit-user-select: none;
      user-select: none;
      --q-root-scroll-track-cyan: rgba(70, 240, 215, 0);
      --q-root-scroll-track-violet: rgba(216, 108, 255, 0);
      --q-root-scroll-thumb-top: rgba(236, 255, 249, 0);
      --q-root-scroll-thumb-mid: rgba(70, 240, 215, 0);
      --q-root-scroll-thumb-end: rgba(216, 108, 255, 0);
      --q-root-scroll-glow: rgba(70, 240, 215, 0);
      transition: scrollbar-color 280ms ease;
    }

    .ft-q-root-card,
    .ft-q-audio-card,
    .ft-q-picture-card,
    .ft-q-question-card,
    .ft-q-root-info-card,
    .ft-q-picture-answer-card,
    .ft-q-guidance-layer,
    .ft-q-select-connector-layer,
    .ft-q-picture-answer-layer {
      cursor: default;
      -webkit-user-select: none;
      user-select: none;
    }

    .ft-q-root-card *,
    .ft-q-audio-card *,
    .ft-q-picture-card *,
    .ft-q-question-card *,
    .ft-q-root-info-card *,
    .ft-q-picture-answer-card *,
    .ft-q-guidance-layer * {
      -webkit-user-select: none;
      user-select: none;
    }

    .ft-q-root-text,
    .ft-q-root-text *,
    .ft-q-audio-text,
    .ft-q-audio-text *,
    .ft-q-question-text,
    .ft-q-question-text *,
    .ft-q-info-text,
    .ft-q-info-text *,
    .ft-q-root-info-body,
    .ft-q-root-info-body *,
    .ft-q-answer-feedback,
    .ft-q-choice-label,
    .ft-q-picture-answer-label {
      cursor: default;
    }

    .ft-q-root-card :where(input, textarea, select, [contenteditable="true"]),
    .ft-q-audio-card :where(input, textarea, select, [contenteditable="true"]),
    .ft-q-picture-card :where(input, textarea, select, [contenteditable="true"]),
    .ft-q-question-card :where(input, textarea, select, [contenteditable="true"]),
    .ft-q-root-info-card :where(input, textarea, select, [contenteditable="true"]),
    .ft-q-picture-answer-card :where(input, textarea, select, [contenteditable="true"]) {
      -webkit-user-select: text;
      user-select: text;
      cursor: text;
    }

    .ft-q-root-text.is-root-scrollbar-active {
      scrollbar-color: rgba(126, 255, 235, 0.58) transparent;
      --q-root-scroll-track-cyan: rgba(70, 240, 215, 0.2);
      --q-root-scroll-track-violet: rgba(216, 108, 255, 0.14);
      --q-root-scroll-thumb-top: rgba(236, 255, 249, 0.9);
      --q-root-scroll-thumb-mid: rgba(70, 240, 215, 0.82);
      --q-root-scroll-thumb-end: rgba(216, 108, 255, 0.62);
      --q-root-scroll-glow: rgba(70, 240, 215, 0.28);
    }

    .ft-q-root-text::-webkit-scrollbar {
      width: 1px;
      display: block;
    }

    .ft-q-root-text::-webkit-scrollbar-track {
      margin-block: 30px;
      background:
        linear-gradient(180deg, transparent, var(--q-root-scroll-track-cyan) 20%, var(--q-root-scroll-track-violet) 74%, transparent);
      transition: background 280ms ease;
    }

    .ft-q-root-text::-webkit-scrollbar-thumb {
      min-height: 52px;
      background:
        linear-gradient(180deg, var(--q-root-scroll-thumb-top), var(--q-root-scroll-thumb-mid) 54%, var(--q-root-scroll-thumb-end));
      box-shadow:
        0 0 8px var(--q-root-scroll-glow);
      transition: background 280ms ease, box-shadow 280ms ease;
    }

    .ft-q-root-text.is-root-scrollbar-active::-webkit-scrollbar-thumb:hover {
      background:
        linear-gradient(180deg, #ecfff9, rgba(126, 255, 235, 0.92) 48%, rgba(216, 108, 255, 0.76));
