    .ft-q-root-card.is-typing .ft-q-root-text {
      filter: saturate(1.08) brightness(1.04);
      text-shadow:
        0 0 12px rgba(236, 255, 249, 0.12),
        0 0 24px rgba(70, 240, 215, 0.2),
        0 0 42px rgba(70, 240, 215, 0.14);
