    .ft-q-choice.is-reacting {
      animation: ftQChoiceReactBurst 420ms cubic-bezier(0.16, 0.82, 0.22, 1) both;
    }

    .ft-q-choice.is-reacting::before {
      animation: ftQChoiceReactRail 420ms cubic-bezier(0.16, 0.82, 0.22, 1) both;
    }

    .ft-q-choice.is-reacting::after {
      animation: ftQChoiceReactGlow 420ms cubic-bezier(0.16, 0.82, 0.22, 1) both;
    }

    .ft-q-choice.is-reacting .ft-q-choice-signal i {
      animation: ftQChoiceReactSignal 420ms cubic-bezier(0.16, 0.82, 0.22, 1) both;
    }

    .ft-q-choice.is-picked.is-correct {
      animation-name: ftQChoiceReactBurstCorrect;
    }

    .ft-q-choice.is-picked.is-wrong {
      animation-name: ftQChoiceReactBurstWrong;
    }

    @keyframes ftQChoiceReactBurst {
      0% { transform: translateY(0) scale(1); filter: brightness(1); }
      22% { transform: translateY(-1px) scale(1.012); filter: brightness(1.08); }
      54% { transform: translateY(0) scale(0.998); filter: brightness(1.03); }
      100% { transform: translateY(0) scale(1); filter: brightness(1); }
    }

    @keyframes ftQChoiceReactBurstCorrect {
      0% { box-shadow: 0 0 0 rgba(108, 240, 164, 0); }
      36% {
        box-shadow:
          0 0 0 1px rgba(108, 240, 164, 0.38),
          0 0 24px rgba(108, 240, 164, 0.22),
          inset 0 0 18px rgba(108, 240, 164, 0.12);
      }
      100% {
        box-shadow:
          0 0 0 rgba(108, 240, 164, 0),
          inset 0 0 0 rgba(108, 240, 164, 0);
      }
    }

    @keyframes ftQChoiceReactBurstWrong {
      0% { box-shadow: 0 0 0 rgba(255, 142, 72, 0); }
      36% {
        box-shadow:
          0 0 0 1px rgba(255, 142, 72, 0.38),
          0 0 24px rgba(255, 142, 72, 0.22),
          inset 0 0 18px rgba(255, 142, 72, 0.12);
      }
      100% {
        box-shadow:
          0 0 0 rgba(255, 142, 72, 0),
          inset 0 0 0 rgba(255, 142, 72, 0);
      }
    }

    @keyframes ftQChoiceReactRail {
      0% { opacity: 0.62; transform: translateY(-50%) scaleY(0.86); }
      28% { opacity: 1; transform: translateY(-50%) scaleY(1.08); }
      100% { opacity: 0.62; transform: translateY(-50%) scaleY(1); }
    }

    @keyframes ftQChoiceReactGlow {
      0% { opacity: 0.28; }
      35% { opacity: 0.96; }
      100% { opacity: 0.36; }
    }

    @keyframes ftQChoiceReactSignal {
      0% { opacity: 0.58; transform: translateX(0); }
      30% { opacity: 1; transform: translateX(2px); }
      100% { opacity: 0.72; transform: translateX(0); }
    }

