}

.ft-admin-target-title {
  margin: 0;
  color: #f5fbff;
  font: 800 clamp(1.35rem, 3vw, 1.75rem)/1.12 Georgia, "Times New Roman", serif;
  letter-spacing: -0.025em;
}

.ft-admin-target-close {
  display: grid;
  flex: 0 0 40px;
  width: 40px;
  height: 40px;
  place-items: center;
  border: 1px solid rgba(148, 184, 207, 0.24);
  border-radius: 13px;
  background: rgba(255, 255, 255, 0.055);
  color: #cce8f6;
  cursor: pointer;
  font: 400 1.65rem/1 Arial, sans-serif;
  transition: 150ms ease;
}

.ft-admin-target-close:hover,
.ft-admin-target-close:focus-visible {
  border-color: rgba(251, 191, 36, 0.72);
  background: rgba(245, 158, 11, 0.13);
  color: #fde68a;
  transform: rotate(4deg) scale(1.04);
}

.ft-admin-target-body {
  margin: 10px 54px 20px 0;
  color: #9fc0d2;
  font-size: 0.92rem;
  line-height: 1.55;
}

.ft-admin-target-choices {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 9px;
  margin-bottom: 16px;
  padding: 5px;
  border: 1px solid rgba(132, 184, 211, 0.17);
  border-radius: 17px;
  background: rgba(1, 10, 19, 0.38);
}

.ft-admin-target-choice {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 10px;
  min-height: 44px;
  padding: 9px 13px;
  border: 1px solid transparent;
  border-radius: 12px;
  background: transparent;
  color: #9ebccc;
  cursor: pointer;
  font: 800 0.86rem/1.2 "Trebuchet MS", sans-serif;
  transition: 150ms ease;
}

.ft-admin-target-choice::before {
  display: grid;
  flex: 0 0 24px;
  width: 24px;
  height: 24px;
  place-items: center;
  border: 1px solid rgba(148, 184, 207, 0.22);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.05);
  color: #82aabd;
  content: "";
  font-size: 0.8rem;
  transition: 150ms ease;
}

.ft-admin-target-choice[data-target-kind="self"]::before {
  content: "◎";
}

.ft-admin-target-choice[data-target-kind="user"]::before {
  content: "◇";
}

.ft-admin-target-choice:hover,
.ft-admin-target-choice:focus-visible {
  color: #effbff;
  background: rgba(255, 255, 255, 0.055);
}

.ft-admin-target-choice.is-active {
  border-color: rgba(45, 212, 191, 0.42);
  background: linear-gradient(135deg, rgba(13, 148, 136, 0.25), rgba(8, 145, 178, 0.18));
  box-shadow: 0 8px 24px rgba(1, 12, 20, 0.24), inset 0 1px rgba(255, 255, 255, 0.06);
  color: #d7fffa;
}

.ft-admin-target-choice.is-active::before {
  border-color: rgba(94, 234, 212, 0.45);
  background: rgba(45, 212, 191, 0.2);
  color: #99f6e4;
}

.ft-admin-target-search {
  width: 100%;
  box-sizing: border-box;
  margin-bottom: 12px;
  padding: 12px 14px;
  border: 1px solid rgba(125, 181, 211, 0.28);
  border-radius: 14px;
  outline: none;
  background: rgba(1, 12, 22, 0.55);
  color: #eaf9ff;
  font: 700 0.92rem/1.2 "Trebuchet MS", sans-serif;
}

.ft-admin-target-search:focus {
  border-color: #2dd4bf;
  box-shadow: 0 0 0 3px rgba(45, 212, 191, 0.13);
}

.ft-admin-target-list {
  display: grid;
  gap: 8px;
  min-height: 52px;
  color: #8fb0c2;
}

.ft-admin-target-user {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  width: 100%;
  padding: 11px 13px;
  border: 1px solid rgba(107, 170, 201, 0.18);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.035);
  color: #d7f1fc;
  cursor: pointer;
  text-align: left;
  transition: 140ms ease;
}

.ft-admin-target-user:hover,
.ft-admin-target-user:focus-visible,
.ft-admin-target-user.is-active {
  border-color: rgba(45, 212, 191, 0.62);
  background: rgba(13, 148, 136, 0.15);
  transform: translateY(-1px);
}

.ft-admin-target-user span {
  color: #83a9bd;
  font-size: 0.82rem;
}

.ft-admin-target-summary {
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr);
  align-items: center;
  gap: 12px;
  margin: 15px 0 12px;
  padding: 13px 14px;
  border: 1px solid rgba(125, 181, 211, 0.19);
  border-radius: 16px;
  background: rgba(1, 11, 20, 0.42);
}

.ft-admin-target-summary-icon {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  border-radius: 13px;
  background: rgba(125, 181, 211, 0.1);
}

.ft-admin-target-summary-icon::before {
  content: "\2192";
  color: #8eb2c5;
  font-size: 1.25rem;
}

.ft-admin-target-summary.is-ready {
  border-color: rgba(45, 212, 191, 0.34);
  background: linear-gradient(135deg, rgba(13, 148, 136, 0.13), rgba(14, 116, 144, 0.08));
}

.ft-admin-target-summary.is-ready .ft-admin-target-summary-icon {
  background: linear-gradient(145deg, #14b8a6, #0891b2);
  box-shadow: 0 8px 24px rgba(8, 145, 178, 0.24);
}

.ft-admin-target-summary.is-ready .ft-admin-target-summary-icon::before {
  content: "\2713";
  color: #fff;
}

.ft-admin-target-summary-content {
  display: grid;
  min-width: 0;
  gap: 2px;
}

.ft-admin-target-summary small {
  color: #6f9aae;
  font-size: 0.63rem;
  font-weight: 900;
  letter-spacing: 0.13em;
}

.ft-admin-target-summary strong {
  overflow: hidden;
  color: #e8fbff;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ft-admin-target-destination-label {
  display: grid;
  gap: 7px;
  margin: 12px 0;
  color: #8eb2c5;
  font-size: 0.78rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.ft-admin-target-destination {
  width: 100%;
  box-sizing: border-box;
  padding: 11px 12px;
  border: 1px solid rgba(125, 181, 211, 0.28);
  border-radius: 13px;
  outline: none;
  background: #0b2435;
  color: #eaf9ff;
}

.ft-admin-target-destination:focus {
  border-color: #2dd4bf;
  box-shadow: 0 0 0 3px rgba(45, 212, 191, 0.13);
}

.ft-admin-target-footer {
  position: sticky;
  bottom: -24px;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 9px;
  margin: 18px -24px -24px;
  padding: 16px 24px 20px;
  border-top: 1px solid rgba(125, 181, 211, 0.13);
  background: linear-gradient(to bottom, rgba(7, 24, 39, 0.9), #071827 28%);
  backdrop-filter: blur(12px);
}

.ft-admin-target-footer .ft-task-confirm-button {
  min-width: 112px;
  min-height: 42px;
  border: 1px solid rgba(45, 212, 191, 0.55);
  border-radius: 13px;
  background: linear-gradient(135deg, #0f9f91, #087e9b);
  color: #fff;
  font-weight: 900;
  box-shadow: 0 9px 24px rgba(8, 145, 178, 0.2);
}

.ft-admin-target-footer .ft-task-confirm-button.is-cancel {
  border-color: rgba(148, 184, 207, 0.22);
  background: rgba(255, 255, 255, 0.04);
  color: #acc8d6;
  box-shadow: none;
}

.ft-admin-target-footer .ft-task-confirm-button:disabled {
  cursor: not-allowed;
  filter: saturate(0.25);
  opacity: 0.48;
}

.ft-admin-target-pager {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin: 12px 0;
  color: #759bad;
  font-size: 0.8rem;
}

.ft-admin-target-pager button {
  padding: 7px 11px;
  border: 1px solid rgba(125, 181, 211, 0.25);
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.045);
  color: #b9d9e8;
  cursor: pointer;
}

@keyframes ft-admin-target-enter {
  from {
    opacity: 0;
    transform: translateY(14px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@media (max-width: 560px) {
  .ft-admin-target-modal {
    align-items: end;
    padding: 10px;
  }

  .ft-admin-target-card {
    width: 100%;
    max-height: 92vh;
    padding: 20px;
    border-radius: 24px 24px 18px 18px;
  }

  .ft-admin-target-body {
    margin-right: 0;
  }

  .ft-admin-target-choices {
    grid-template-columns: 1fr;
  }

  .ft-admin-target-footer {
    bottom: -20px;
    margin: 16px -20px -20px;
    padding: 14px 20px 18px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .ft-admin-target-card {
    animation: none;
  }

  .ft-admin-target-close,
  .ft-admin-target-choice,
  .ft-admin-target-user {
    transition: none;
  }
}


