      background:
        conic-gradient(from 0deg, transparent 0deg 28deg, rgba(70, 240, 215, 0.7) 35deg, transparent 52deg 126deg, rgba(216, 108, 255, 0.52) 138deg, transparent 156deg 232deg, rgba(108, 240, 164, 0.66) 244deg, transparent 266deg 360deg);
