      overflow: hidden;
      overflow-wrap: normal;
      white-space: nowrap;
      word-break: keep-all;
      border-color: rgba(216, 108, 255, 0.72);
      background:
        linear-gradient(135deg, rgba(216, 108, 255, 0.92), rgba(70, 240, 215, 0.9)),
        repeating-linear-gradient(90deg, rgba(255,255,255,0.28) 0 1px, transparent 1px 9px);
      color: #061112;
      font-size: clamp(16px, 2.4vw, 24px);
      font-weight: 950;
      letter-spacing: 0;
      text-transform: none;
      text-align: center;
      text-shadow: 0 1px 0 rgba(255, 255, 255, 0.26);
      box-shadow:
        0 0 24px rgba(216, 108, 255, 0.22),
        0 0 34px rgba(70, 240, 215, 0.16),
        inset 0 0 18px rgba(255, 255, 255, 0.16);
    }

    .ft-vocab-chip.is-answer-word::before {
      content: "";
      position: absolute;
      inset: 0;
      background: linear-gradient(100deg, transparent 0 32%, rgba(255, 255, 255, 0.42) 48%, transparent 64% 100%);
      transform: translateX(-120%);
      animation: vocabAnswerWordScan 1500ms ease-in-out infinite;
      pointer-events: none;
    }

    .ft-vocab-chip.is-answer-word::after {
      content: "WORD";
      position: absolute;
      right: 6px;
      top: 4px;
      color: rgba(6, 17, 18, 0.5);
      font-size: 8px;
      font-weight: 950;
      letter-spacing: 0.12em;
    }

    @keyframes vocabAnswerWordScan {
      0%, 26% { transform: translateX(-120%); }
      68%, 100% { transform: translateX(120%); }
    }

    .ft-vocab-timer {
      position: relative;
      display: grid;
      grid-template-columns: auto 1fr;
      align-items: center;
      gap: 12px;
      min-height: 68px;
      border: 1px solid rgba(70, 240, 215, 0.42);
      border-radius: 18px;
      background:
        radial-gradient(circle at 42px 50%, rgba(108, 240, 164, 0.22), transparent 58px),
        radial-gradient(circle at 86% 12%, rgba(216, 108, 255, 0.16), transparent 54px),
        linear-gradient(135deg, rgba(4, 20, 26, 0.78), rgba(25, 12, 38, 0.66)),
        repeating-linear-gradient(90deg, rgba(108, 240, 164, 0.09) 0 1px, transparent 1px 13px);
      padding: 8px 13px;
      overflow: hidden;
      box-shadow:
        inset 0 0 34px rgba(70, 240, 215, 0.12),
        0 0 28px rgba(108, 240, 164, 0.14);
    }

    .ft-vocab-timer::before {
      content: "";
      position: absolute;
      inset: 0;
      background: linear-gradient(90deg, transparent, rgba(108, 240, 164, 0.18), transparent);
      transform: translateX(-100%);
      animation: vocabTimerSweep 2600ms ease-in-out infinite;
      pointer-events: none;
    }

    .ft-vocab-timer-orbit {
      position: relative;
      width: 56px;
      height: 56px;
      border: 1px solid rgba(108, 240, 164, 0.62);
      border-radius: 50%;
      background:
        radial-gradient(circle, rgba(247, 255, 249, 0.98) 0 2px, rgba(108, 240, 164, 0.34) 3px, transparent 5px),
        repeating-radial-gradient(circle, rgba(70, 240, 215, 0.24) 0 1px, transparent 1px 9px),
        conic-gradient(
          from -90deg,
          rgba(108, 240, 164, 0.58) 0deg 120deg,
          rgba(255, 190, 141, 0.66) 120deg 200deg,
          rgba(216, 108, 255, 0.62) 200deg 360deg
        );
      box-shadow:
        0 0 18px rgba(70, 240, 215, 0.42),
        0 0 36px rgba(108, 240, 164, 0.16),
        inset 0 0 20px rgba(3, 13, 14, 0.84);
    }

    .ft-vocab-timer-orbit::before,
    .ft-vocab-timer-orbit::after {
      content: "";
      position: absolute;
      inset: 7px;
      border: 1px solid rgba(70, 240, 215, 0.22);
      border-radius: 50%;
    }

    .ft-vocab-timer-orbit::before {
      background: conic-gradient(from -90deg, rgba(247, 255, 249, 0.92), rgba(70, 240, 215, 0.28) 34deg, transparent 82deg 360deg);
      border: 0;
      filter: drop-shadow(0 0 11px rgba(70, 240, 215, 0.78));
      animation: vocabRadarSweep 45s linear 1 forwards;
      mask: radial-gradient(circle, transparent 0 4px, #000 5px 100%);
    }

    .ft-vocab-timer-orbit::after {
      inset: 4px;
      border: 0;
      background:
        linear-gradient(0deg, transparent 48%, rgba(247, 255, 249, 0.58) 48% 52%, transparent 52%),
        linear-gradient(90deg, transparent 48%, rgba(70, 240, 215, 0.42) 48% 52%, transparent 52%);
      opacity: 0.78;
    }

    .ft-vocab-timer-orbit i:first-child {
      position: absolute;
      left: 50%;
      top: 50%;
      width: 1px;
      height: 25px;
      background: linear-gradient(180deg, #effefa, #46f0d7);
      transform-origin: 50% 0;
      animation: vocabClockHand 45s linear 1 forwards;
      box-shadow: 0 0 12px rgba(70, 240, 215, 0.74);
    }

    .ft-vocab-timer-orbit i:last-child {
      position: absolute;
      left: 50%;
      top: 50%;
      width: 6px;
      height: 6px;
      border-radius: 50%;
      background: #effefa;
      transform: translate(-50%, -50%);
      box-shadow: 0 0 12px rgba(108, 240, 164, 0.78);
    }

    .ft-vocab-timer-mark {
      position: absolute;
      left: 50%;
      top: 50%;
      width: 8px;
      height: 8px;
      border: 1px solid rgba(247, 255, 249, 0.82);
      border-radius: 50%;
      background: rgba(3, 13, 14, 0.9);
      box-shadow: 0 0 12px rgba(247, 255, 249, 0.42);
      transform: translate(-50%, -50%) rotate(var(--angle)) translateY(-27px);
    }

    .ft-vocab-timer-mark.m1 {
      --angle: 120deg;
      border-color: rgba(108, 240, 164, 0.94);
      box-shadow: 0 0 14px rgba(108, 240, 164, 0.76);
    }

    .ft-vocab-timer-mark.m2 {
      --angle: 200deg;
      border-color: rgba(255, 190, 141, 0.94);
      box-shadow: 0 0 14px rgba(255, 190, 141, 0.7);
    }

    .ft-vocab-timer-mark.m3 {
      --angle: 360deg;
      border-color: rgba(216, 108, 255, 0.94);
      box-shadow: 0 0 14px rgba(216, 108, 255, 0.7);
    }

    .ft-vocab-timer-text {
      position: relative;
      z-index: 1;
      color: #bdfcf2;
      font-size: 12px;
      font-weight: 900;
      line-height: 1.25;
      letter-spacing: 0.03em;
      text-transform: uppercase;
    }

    .ft-vocab-timer.is-alert {
      border-color: rgba(255, 190, 141, 0.54);
      box-shadow:
        inset 0 0 24px rgba(255, 190, 141, 0.1),
        0 0 18px rgba(255, 190, 141, 0.12);
    }

    .ft-vocab-timer.is-answer {
      border-color: rgba(216, 108, 255, 0.58);
      box-shadow:
        inset 0 0 24px rgba(216, 108, 255, 0.12),
        0 0 22px rgba(216, 108, 255, 0.16);
    }

    .ft-vocab-timer.is-miss {
      border-color: rgba(255, 190, 141, 0.72);
      animation: vocabTimerMissPulse 760ms ease-in-out 2;
      box-shadow:
        inset 0 0 28px rgba(255, 190, 141, 0.16),
        0 0 24px rgba(255, 190, 141, 0.2),
        0 0 34px rgba(70, 240, 215, 0.1);
    }

    @keyframes vocabClockHand {
      from { transform: rotate(0deg); }
      to { transform: rotate(360deg); }
    }

    @keyframes vocabRadarSweep {
      from { transform: rotate(0deg); }
      to { transform: rotate(360deg); }
    }

    @keyframes vocabTimerMissPulse {
      0%, 100% {
        filter: brightness(1);
        transform: translateY(0);
      }
      45% {
        filter: brightness(1.42);
        transform: translateY(-1px);
      }
    }

    @keyframes vocabCardSweep {
      0% { opacity: 0; transform: rotate(-16deg) scale(0.94); }
      24% { opacity: 0.86; }
      100% { opacity: 0; transform: rotate(32deg) scale(1.1); }
    }

    @keyframes vocabCardWave {
      0% { opacity: 0; transform: scale(0.96); filter: brightness(1); }
      26% { opacity: 0.92; filter: brightness(1.36); }
      100% { opacity: 0; transform: scale(1.12); filter: brightness(1.05); }
    }

    @keyframes vocabCardRoundSweep {
      0% { opacity: 0; transform: rotate(-24deg) scale(0.93); }
      30% { opacity: 0.95; }
      100% { opacity: 0; transform: rotate(58deg) scale(1.14); }
    }

    @keyframes vocabCardRoundWave {
      0% { opacity: 0; transform: scale(0.95); filter: brightness(1); }
      28% { opacity: 1; filter: brightness(1.5); }
      100% { opacity: 0; transform: scale(1.16); filter: brightness(1.08); }
    }

    @keyframes vocabTimerSweep {
      0%, 28% { transform: translateX(-105%); }
      58%, 100% { transform: translateX(105%); }
    }

    @keyframes vocabGearSpin {
      to { transform: rotate(360deg); }
    }

    @keyframes vocabModePopupIn {
      0% { opacity: 0; transform: translate(-50%, -50%) scale(0.78); filter: blur(5px); }
      58% { opacity: 1; transform: translate(-50%, -50%) scale(1.04); filter: blur(0); }
      100% { opacity: 1; transform: translate(-50%, -50%) scale(1); filter: blur(0); }
    }

    @keyframes vocabModeGearSpin {
      to { transform: rotate(360deg); }
    }

    @keyframes vocabModeSpark {
      0%, 100% { opacity: 0.28; transform: translateX(-16%); }
      50% { opacity: 0.9; transform: translateX(16%); }
    }

    @keyframes vocabChipTextReveal {
      0% {
        opacity: 0;
        transform: translateY(4px) scale(0.98);
        filter: blur(2px) brightness(1);
      }
      58% {
        opacity: 1;
        transform: translateY(-1px) scale(1.02);
        filter: blur(0) brightness(1.22);
      }
      100% {
        opacity: 1;
        transform: translateY(0) scale(1);
        filter: blur(0) brightness(1);
      }
    }

    @keyframes vocabHintSignal {
      0%, 100% {
        filter: brightness(1);
        text-shadow: 0 0 0 rgba(255, 216, 126, 0);
      }
      48% {
        filter: brightness(1.14);
        text-shadow:
          0 0 10px rgba(255, 216, 126, 0.34),
          0 0 18px rgba(70, 240, 215, 0.18);
      }
      72% {
        filter: brightness(1.06);
        text-shadow: 0 0 9px rgba(70, 240, 215, 0.18);
      }
    }

    @keyframes vocabHintScan {
      0% {
        opacity: 0;
        transform: translateX(-42%) rotate(8deg);
      }
      30%, 58% {
        opacity: .34;
      }
      100% {
        opacity: 0;
        transform: translateX(42%) rotate(8deg);
      }
    }

    @keyframes vocabRoundChipPulse {
      0%, 100% {
        transform: translateY(0) scale(1);
        border-color: rgba(216, 108, 255, 0.38);
        box-shadow: 0 0 0 rgba(216, 108, 255, 0);
        color: #bdfcf2;
      }
      18%, 52% {
        transform: translateY(-1px) scale(1.055);
        border-color: rgba(255, 230, 150, 0.92);
        box-shadow:
          0 0 18px rgba(255, 230, 150, 0.42),
          0 0 34px rgba(216, 108, 255, 0.24),
          inset 0 0 18px rgba(70, 240, 215, 0.14);
        color: #fff2b0;
      }
      34%, 72% {
        transform: translateY(0) scale(1.015);
        border-color: rgba(70, 240, 215, 0.86);
        box-shadow:
          0 0 16px rgba(70, 240, 215, 0.34),
          inset 0 0 16px rgba(216, 108, 255, 0.13);
        color: #effefa;
      }
    }

    .ft-vocab-answer-row {
      display: grid;
      grid-template-columns: 1fr;
      gap: 10px;
    }

    .ft-vocab-input {
      width: 100%;
      min-height: 58px;
      border: 1px solid rgba(70, 240, 215, 0.38);
      border-radius: 14px;
      background: rgba(4, 13, 20, 0.78);
      color: #effefa;
      padding: 12px 14px;
      font-size: clamp(20px, 4vw, 32px);
      font-weight: 850;
      outline: none;
      box-shadow: inset 0 0 24px rgba(70, 240, 215, 0.08);
    }

    .ft-vocab-input:focus {
      border-color: rgba(108, 240, 164, 0.8);
      box-shadow: 0 0 0 3px rgba(108, 240, 164, 0.14), inset 0 0 24px rgba(70, 240, 215, 0.1);
    }

    .ft-vocab-card.is-input-locked .ft-vocab-input {
      border-color: rgba(108, 240, 164, 0.52);
      box-shadow:
        0 0 0 3px rgba(108, 240, 164, 0.1),
        inset 0 0 26px rgba(70, 240, 215, 0.12);
    }

    .ft-vocab-card.is-drill .ft-vocab-input {
      border-color: rgba(255, 190, 141, 0.48);
      background:
        radial-gradient(circle at 100% 0, rgba(255, 190, 141, 0.12), transparent 44%),
        rgba(6, 16, 22, 0.82);
      box-shadow: inset 0 0 26px rgba(255, 190, 141, 0.08), 0 0 20px rgba(255, 190, 141, 0.08);
    }

    .ft-vocab-card.is-shuffle .ft-vocab-input {
      border-color: rgba(216, 108, 255, 0.48);
      background:
        radial-gradient(circle at 0 0, rgba(216, 108, 255, 0.12), transparent 44%),
        rgba(6, 16, 24, 0.84);
      box-shadow: inset 0 0 26px rgba(216, 108, 255, 0.08), 0 0 20px rgba(216, 108, 255, 0.08);
    }

    .ft-vocab-voice-option {
      border: 0;
      border-radius: 14px;
      background: linear-gradient(135deg, #6cf0a4, #46f0d7);
      color: #061112;
      padding: 11px 15px;
      font-size: 13px;
      font-weight: 950;
      cursor: pointer;
    }

    .ft-vocab-audio {
      display: grid;
      gap: 8px;
    }

    .ft-vocab-voice-switch {
      position: relative;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 6px;
      min-height: 44px;
      padding: 5px;
      border: 1px solid rgba(70, 240, 215, 0.34);
      border-radius: 16px;
      background:
        linear-gradient(90deg, rgba(70, 240, 215, 0.08), rgba(216, 108, 255, 0.1)),
        rgba(4, 13, 20, 0.62);
      box-shadow:
        inset 0 0 24px rgba(70, 240, 215, 0.08),
        0 0 26px rgba(70, 240, 215, 0.08);
      overflow: hidden;
    }

    .ft-vocab-voice-switch::before {
      content: "";
      position: absolute;
      inset: 5px auto 5px 5px;
      width: calc(50% - 8px);
      border-radius: 12px;
      background: linear-gradient(135deg, rgba(108, 240, 164, 0.96), rgba(70, 240, 215, 0.9));
      box-shadow: 0 0 22px rgba(70, 240, 215, 0.34);
      transform: translateX(0);
      transition: transform 220ms ease, background 220ms ease;
    }

    .ft-vocab-voice-switch.is-us::before {
      transform: translateX(calc(100% + 6px));
      background: linear-gradient(135deg, rgba(216, 108, 255, 0.94), rgba(70, 240, 215, 0.88));
    }

    .ft-vocab-voice-option {
      position: relative;
      z-index: 1;
      min-height: 34px;
      background: transparent;
      color: #bdfcf2;
      padding: 8px 12px;
      transition: color 180ms ease, text-shadow 180ms ease;
    }

    .ft-vocab-voice-option.is-active {
      color: #061112;
      text-shadow: none;
    }

    .ft-vocab-voice-option:not(.is-active):hover,
    .ft-vocab-voice-option:not(.is-active):focus-visible {
      color: #effefa;
      text-shadow: 0 0 12px rgba(70, 240, 215, 0.44);
      outline: none;
    }

    .ft-vocab-card.is-drill .ft-vocab-voice-switch::before {
      background: linear-gradient(135deg, rgba(255, 190, 141, 0.96), rgba(70, 240, 215, 0.88));
    }

    .ft-vocab-card.is-shuffle .ft-vocab-voice-switch::before {
      background: linear-gradient(135deg, rgba(216, 108, 255, 0.92), rgba(70, 240, 215, 0.88));
    }

    .ft-vocab-feedback {
      min-height: 24px;
      color: #bdfcf2;
      font-size: 13px;
      font-weight: 850;
    }

    .ft-vocab-feedback.is-error {
      color: #ffbe8d;
    }

    .ft-vocab-feedback.is-ok {
      color: #6cf0a4;
    }

    .ft-vocab-strip {
      display: flex;
      flex-wrap: wrap;
      gap: 7px;
      padding-top: 5px;
      border-top: 1px solid rgba(70, 240, 215, 0.18);
    }

    .ft-vocab-token {
      min-width: 34px;
      border: 1px solid rgba(108, 240, 164, 0.24);
      padding: 6px 9px;
      color: rgba(239, 254, 250, 0.62);
      background: rgba(108, 240, 164, 0.08);
      font-size: 12px;
      font-weight: 900;
      text-align: center;
    }

    .ft-vocab-token.is-done {
      color: #061112;
      background: linear-gradient(135deg, #6cf0a4, #46f0d7);
    }

    .ft-vocab-detail-panel,
    .ft-vocab-picture-panel {
      position: absolute;
      z-index: 5;
      min-width: 0;
      max-width: calc(100vw - 20px);
      border: 1px solid rgba(70, 240, 215, 0.36);
      border-radius: 18px;
      background:
        linear-gradient(145deg, rgba(7, 28, 34, 0.9), rgba(16, 10, 31, 0.84)),
        repeating-linear-gradient(180deg, rgba(255,255,255,0.035) 0 1px, transparent 1px 7px);
      box-shadow:
        0 24px 70px rgba(0, 0, 0, 0.34),
        0 0 34px rgba(70, 240, 215, 0.12),
        inset 0 0 30px rgba(70, 240, 215, 0.08);
      overflow: hidden;
    }

    .ft-vocab-detail-panel::before,
    .ft-vocab-picture-panel::before {
      content: "";
      position: absolute;
      inset: 0;
      background:
        linear-gradient(90deg, rgba(70, 240, 215, 0.14), transparent 36%, rgba(255, 142, 72, 0.08)),
        radial-gradient(circle at 100% 0, rgba(216, 108, 255, 0.16), transparent 36%);
      pointer-events: none;
    }

    .ft-vocab-detail-panel {
      top: clamp(28px, 5vh, 76px);
      left: clamp(18px, 5vw, 76px);
      width: min(340px, calc(100vw - 34px));
      padding: 14px;
      max-height: min(300px, calc(100vh - 28px));
    }

    .ft-vocab-picture-panel {
      right: clamp(22px, 5vw, 96px);
      bottom: clamp(28px, 7vh, 92px);
      width: min(300px, calc(100vw - 34px));
      padding: 12px;
      max-height: min(320px, calc(100vh - 28px));
    }

    .ft-vocab-side-content {
      position: relative;
      z-index: 1;
      display: grid;
      gap: 8px;
      min-width: 0;
      min-height: 0;
      max-height: inherit;
    }

    .ft-vocab-detail-panel .ft-vocab-side-content {
      grid-template-rows: auto auto minmax(0, 1fr);
    }

    .ft-vocab-picture-panel .ft-vocab-side-content {
      grid-template-rows: auto minmax(0, 1fr) auto;
    }

    .ft-vocab-side-title {
      margin: 0;
      color: #46f0d7;
      font-size: 12px;
      font-weight: 950;
      letter-spacing: 0.11em;
      text-transform: uppercase;
    }

    .ft-vocab-detail-word {
      margin: 0;
      color: #effefa;
      font-size: 22px;
      line-height: 1.05;
      font-weight: 950;
      overflow-wrap: anywhere;
      text-shadow: 0 0 18px rgba(70, 240, 215, 0.26);
    }

    .ft-vocab-detail-list {
      display: grid;
      gap: 7px;
      min-height: 0;
      max-height: none;
      overflow-y: auto;
      overscroll-behavior: contain;
      padding-right: 8px;
      scrollbar-width: thin;
      scrollbar-color: rgba(70, 240, 215, 0.7) rgba(4, 17, 22, 0.38);
    }

    .ft-vocab-detail-list::-webkit-scrollbar {
      width: 7px;
      display: block;
    }

    .ft-vocab-detail-list::-webkit-scrollbar-track {
      background: rgba(4, 17, 22, 0.4);
      border-radius: 999px;
    }

    .ft-vocab-detail-list::-webkit-scrollbar-thumb {
      border-radius: 999px;
      background: linear-gradient(180deg, rgba(70, 240, 215, 0.78), rgba(216, 108, 255, 0.6));
      box-shadow: 0 0 12px rgba(70, 240, 215, 0.42);
    }

    .ft-vocab-detail-row {
      position: relative;
      display: grid;
      gap: 3px;
      border-left: 2px solid rgba(70, 240, 215, 0.62);
      background: rgba(4, 17, 22, 0.62);
      padding: 7px 9px 7px 11px;
      color: rgba(239, 254, 250, 0.88);
      font-size: 12px;
      font-weight: 820;
      line-height: 1.35;
    }

    .ft-vocab-detail-row[data-kind="pos"] {
      border-left-color: rgba(108, 240, 164, 0.82);
      color: #6cf0a4;
      text-transform: uppercase;
      letter-spacing: 0.04em;
    }

    .ft-vocab-detail-row[data-kind="ex"] {
      border-left-color: rgba(255, 190, 141, 0.76);
    }

    .ft-vocab-detail-row small {
      color: rgba(255, 236, 196, 0.82);
      font-size: 11px;
      font-weight: 760;
    }

    .ft-vocab-picture-frame {
      position: relative;
      aspect-ratio: 4 / 3;
      min-height: 0;
      max-height: 210px;
      border: 1px solid rgba(108, 240, 164, 0.32);
      border-radius: 14px;
      overflow: hidden;
      background:
        radial-gradient(circle, rgba(70, 240, 215, 0.18), transparent 58%),
        rgba(3, 13, 14, 0.86);
      box-shadow: inset 0 0 28px rgba(70, 240, 215, 0.1);
      cursor: zoom-in;
      outline: none;
      transition: transform 180ms ease, border-color 180ms ease, box-shadow 180ms ease;
    }

    .ft-vocab-picture-frame:hover,
    .ft-vocab-picture-frame:focus-visible {
      transform: translateY(-2px) scale(1.012);
      border-color: rgba(108, 240, 164, 0.78);
      box-shadow: inset 0 0 28px rgba(70, 240, 215, 0.14), 0 12px 30px rgba(0, 0, 0, 0.32), 0 0 24px rgba(70, 240, 215, 0.18);
    }

    .ft-vocab-picture-frame::after {
      content: "";
      position: absolute;
      inset: 0;
      background:
        linear-gradient(90deg, transparent, rgba(247, 255, 249, 0.22), transparent),
        repeating-linear-gradient(180deg, rgba(255,255,255,0.045) 0 1px, transparent 1px 8px);
      mix-blend-mode: screen;
      opacity: 0.45;
      pointer-events: none;
    }

    .ft-vocab-picture-img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      display: block;
