      border: 1px solid rgba(216, 108, 255, 0.44);
      border-radius: 24px;
      background: radial-gradient(circle at 20% 0%, rgba(216, 108, 255, 0.2), transparent 34%), radial-gradient(circle at 86% 12%, rgba(70, 240, 215, 0.16), transparent 32%), linear-gradient(180deg, rgba(35, 20, 48, 0.96), rgba(6, 17, 22, 0.96));
      box-shadow: 0 30px 86px rgba(0, 0, 0, 0.5), 0 0 42px rgba(216, 108, 255, 0.13), inset 0 0 38px rgba(70, 240, 215, 0.08);
      padding: 18px;
