      inset: -9px;
      z-index: -1;
      border-radius: 31px;
      opacity: 0;
      pointer-events: none;
      transition: opacity 180ms ease;
    }

    .ft-speak-panel::before {
      border: 1px solid rgba(70, 240, 215, 0.42);
      background:
        radial-gradient(circle at var(--speak-electric-x, 22%) 0%, rgba(70, 240, 215, 0.42), transparent 24%),
        radial-gradient(circle at 82% var(--speak-electric-y, 18%), rgba(255, 113, 206, 0.3), transparent 28%);
