    @keyframes speakCircuitOrbit {
      0% {
        --speak-electric-x: 12%;
        --speak-electric-y: 18%;
        transform: scale(1);
        filter: drop-shadow(0 0 12px rgba(70, 240, 215, 0.26));
      }
      50% {
        --speak-electric-x: 88%;
        --speak-electric-y: 76%;
        transform: scale(1.01);
        filter: drop-shadow(0 0 24px rgba(216, 108, 255, 0.34));
      }
      100% {
        --speak-electric-x: 12%;
        --speak-electric-y: 18%;
        transform: scale(1);
        filter: drop-shadow(0 0 12px rgba(70, 240, 215, 0.26));
      }
    }

    @keyframes speakOuterWave {
      0% {
        transform: scale(0.96);
        opacity: 0.72;
      }
      100% {
        transform: scale(1.08);
        opacity: 0;
      }
    }

    @keyframes speakWaveScan {
      0% { transform: translateX(-100%); }
