    .ft-connector {
      position: absolute;
      top: var(--connector-top, 50%);
      left: var(--connector-left, calc(50% + 270px));
      width: var(--connector-width, 150px);
      height: var(--connector-height, 80px);
      z-index: 2;
      opacity: 0;
      transform: scale(1);
      transform-origin: center;
      pointer-events: none;
      filter: drop-shadow(0 0 10px rgba(70, 240, 215, 0.36));
    }

    .ft-connector.is-live {
      animation: connectorIn 180ms ease-out forwards;
    }

    .ft-connector.is-dim {
      opacity: 0.34 !important;
      filter: drop-shadow(0 0 6px rgba(70, 240, 215, 0.18));
    }

    .ft-connector.is-active {
      z-index: 3;
      opacity: 1 !important;
      filter: drop-shadow(0 0 14px rgba(126, 255, 235, 0.48)) drop-shadow(0 0 26px rgba(216, 108, 255, 0.16));
    }

    .ft-connector-svg {
      position: absolute;
      width: 100%;
      height: 100%;
      inset: 0;
      overflow: visible;
    }

    .ft-connector-glow,
    .ft-connector-path {
      fill: none;
      stroke-linecap: round;
      stroke-linejoin: round;
      vector-effect: non-scaling-stroke;
    }

    .ft-connector-glow {
      stroke: rgba(126, 255, 235, 0.24);
      stroke-width: 7;
      filter: blur(3px);
      stroke-dasharray: var(--connector-length, 260);
      stroke-dashoffset: var(--connector-length, 260);
    }

    .ft-connector-path {
      stroke: url(#ft-connector-gradient);
      stroke-width: 1.9;
      stroke-dasharray: var(--connector-length, 260);
      stroke-dashoffset: var(--connector-length, 260);
    }

    .ft-connector.is-live .ft-connector-glow,
    .ft-connector.is-live .ft-connector-path {
      animation: connectorDraw var(--connector-draw-ms, 760ms) cubic-bezier(.16, .84, .22, 1) forwards;
    }

    .ft-connector.is-complete .ft-connector-path {
      stroke-dasharray: 7 13;
      stroke-dashoffset: 0;
      animation: connectorDash 1500ms linear infinite;
    }

    .ft-connector.is-active .ft-connector-glow {
      stroke-width: 9;
      stroke: rgba(126, 255, 235, 0.34);
    }

    .ft-connector.is-active .ft-connector-path {
      stroke-width: 2.5;
    }

    .ft-connector[data-panel="ipa"].is-live {
      opacity: 1 !important;
      filter:
        drop-shadow(0 0 14px rgba(126, 255, 235, 0.48))
        drop-shadow(0 0 28px rgba(108, 240, 164, 0.2));
    }

    .ft-connector[data-panel="ipa"].is-live .ft-connector-glow {
      stroke: rgba(126, 255, 235, 0.34);
      stroke-width: 9;
    }

    .ft-connector[data-panel="ipa"].is-live .ft-connector-path {
      stroke-width: 2.4;
    }

    .ft-connector-dot {
      position: absolute;
      left: var(--dot-x, 0px);
      top: var(--dot-y, 0px);
      width: 9px;
      height: 9px;
      border-radius: 50%;
      background: radial-gradient(circle, #effefa 0 16%, var(--green) 20% 58%, rgba(70, 240, 215, 0.12) 62%);
      box-shadow: 0 0 18px rgba(108, 240, 164, 0.96), 0 0 32px rgba(70, 240, 215, 0.38);
      opacity: 0;
      transform: translate(-50%, -50%);
      transition: opacity 180ms ease, transform 180ms ease;
    }

    .ft-connector.is-live .ft-connector-start {
      opacity: 1;
    }

    .ft-connector.is-complete .ft-connector-end {
      opacity: 1;
      transform: translate(-50%, -50%) scale(1.12);
    }

    .ft-connector-start { --dot-x: var(--connector-start-x, 0px); --dot-y: var(--connector-start-y, 50%); }
    .ft-connector-end { --dot-x: var(--connector-end-x, 100%); --dot-y: var(--connector-end-y, 50%); }

    .ft-ipa-panel {
      position: absolute;
      top: 50%;
      left: calc(50% + 410px);
      width: min(340px, calc(100vw - 28px));
      border: 1px solid transparent;
      border-radius: 20px;
      background:
        linear-gradient(180deg, rgba(6, 31, 34, 0.98), rgba(5, 15, 23, 0.96)) padding-box,
        linear-gradient(135deg, rgba(126, 255, 235, 0.78), rgba(70, 240, 215, 0.46) 54%, rgba(216, 108, 255, 0.42)) border-box;
      box-shadow:
        0 24px 70px rgba(0, 0, 0, 0.38),
        0 0 34px rgba(70, 240, 215, 0.14),
        inset 0 0 30px rgba(108, 240, 164, 0.1);
      padding: 20px;
      opacity: 0;
      transform: translateY(-50%) translateX(18px) scale(0.92);
      pointer-events: none;
      isolation: isolate;
      overflow: visible;
    }

    .ft-ipa-panel > * {
      position: relative;
      z-index: 1;
    }

    .ft-ipa-panel::before,
    .ft-ipa-panel::after {
      content: "";
      position: absolute;
      inset: -12px;
      border: 1px solid rgba(70, 240, 215, 0.36);
      border-radius: 26px;
      opacity: 0.62;
      pointer-events: none;
      transform: none;
    }

    .ft-ipa-panel::before {
      background:
        linear-gradient(90deg, transparent 0 10%, rgba(126, 255, 235, 0.56) 10% 34%, transparent 34% 100%) top / 100% 1px no-repeat,
        linear-gradient(90deg, transparent 0 54%, rgba(216, 108, 255, 0.42) 54% 84%, transparent 84% 100%) bottom / 100% 1px no-repeat,
        linear-gradient(180deg, transparent 0 16%, rgba(70, 240, 215, 0.42) 16% 54%, transparent 54% 100%) left / 1px 100% no-repeat,
        linear-gradient(180deg, rgba(108, 240, 164, 0.48), transparent 30% 72%, rgba(216, 108, 255, 0.34)) right / 1px 100% no-repeat;
      box-shadow:
        0 0 24px rgba(70, 240, 215, 0.16),
        inset 0 0 22px rgba(70, 240, 215, 0.06);
    }

    .ft-ipa-panel::after {
      inset: 7px;
      border-radius: 15px;
      border-color: rgba(126, 255, 235, 0.2);
      border-left-color: transparent;
      opacity: 0.42;
      box-shadow:
        inset 0 0 18px rgba(70, 240, 215, 0.08),
        inset -10px 0 18px rgba(216, 108, 255, 0.05);
    }

    .ft-ipa-panel.is-live {
      animation: ipaIn 780ms cubic-bezier(.16, .84, .22, 1) forwards;
      pointer-events: auto;
      box-shadow:
        0 24px 70px rgba(0, 0, 0, 0.38),
        0 0 34px rgba(70, 240, 215, 0.2),
        0 0 58px rgba(108, 240, 164, 0.1),
        inset 0 0 34px rgba(108, 240, 164, 0.12);
    }

    .ft-ipa-panel.is-measuring {
      display: block !important;
      visibility: hidden !important;
      opacity: 0 !important;
      pointer-events: none !important;
      animation: none !important;
      transform: translateY(-50%) translateX(0) scale(1) !important;
    }

    .ft-ipa-panel.is-speaking {
      box-shadow:
        0 24px 70px rgba(0, 0, 0, 0.38),
        0 0 42px rgba(70, 240, 215, 0.18),
        inset 0 0 34px rgba(108, 240, 164, 0.12);
    }

    .ft-ipa-panel.is-speaking::before {
      animation: ipaShockwave 1180ms ease-out infinite;
    }

    .ft-ipa-panel.is-speaking::after {
      animation: ipaShockwave 1180ms ease-out 420ms infinite;
      border-color: rgba(216, 108, 255, 0.36);
    }

