    .ft-english {
      margin: 14px 0 0;
      border-left: 2px solid rgba(70, 240, 215, 0.34);
      padding-left: 10px;
      color: rgba(223, 255, 250, 0.72);
      font-size: 15px;
      line-height: 1.35;
    }

    .ft-word {
      display: inline-block;
      border-radius: 8px;
      padding: 1px 2px;
      margin: 0 -1px;
      transition: color 140ms ease, background 140ms ease, box-shadow 140ms ease, transform 140ms ease;
    }

    .ft-word.is-reading {
      color: #061316;
      background: linear-gradient(135deg, var(--green), var(--cyan));
      box-shadow: 0 0 16px rgba(70, 240, 215, 0.45);
      transform: translateY(-1px);
