    .ft-voice-shell,
    .ft-play,
    .ft-next {
      min-height: 40px;
      border-radius: 999px;
      font: inherit;
      font-size: 12px;
      font-weight: 850;
    }

    .ft-voice-shell {
      position: relative;
      min-width: 0;
      min-height: 46px;
      overflow: hidden;
      border: 1px solid rgba(70, 240, 215, 0.42);
      background:
        linear-gradient(135deg, rgba(70, 240, 215, 0.18), rgba(216, 108, 255, 0.1)),
        rgba(3, 13, 14, 0.82);
      box-shadow:
        inset 0 0 0 1px rgba(239, 254, 250, 0.04),
        0 0 20px rgba(70, 240, 215, 0.14);
    }

    .ft-voice-shell::before {
      content: "";
      position: absolute;
      inset: 1px;
      border-radius: inherit;
      pointer-events: none;
      background:
        linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.16), transparent),
        radial-gradient(circle at 16% 10%, rgba(108, 240, 164, 0.22), transparent 34%),
        radial-gradient(circle at 86% 80%, rgba(216, 108, 255, 0.18), transparent 38%);
      opacity: 0.8;
      mix-blend-mode: screen;
    }

    .ft-voice-shell::after {
      content: "";
      position: absolute;
      right: 15px;
      top: 50%;
      width: 8px;
      height: 8px;
      border-right: 2px solid rgba(108, 240, 164, 0.92);
      border-bottom: 2px solid rgba(108, 240, 164, 0.92);
      transform: translateY(-68%) rotate(45deg);
      pointer-events: none;
      filter: drop-shadow(0 0 6px rgba(108, 240, 164, 0.5));
    }

    .ft-voice {
      position: absolute;
      inset: 0;
      z-index: 1;
      width: 100%;
      height: 100%;
      border: 0;
      appearance: none;
      -webkit-appearance: none;
      color-scheme: dark;
      background: transparent;
      color: var(--ink);
      padding: 0 42px 0 15px;
      outline: none;
      opacity: 0;
      pointer-events: none;
    }

    .ft-ipa-controls .ft-voice-shell {
      grid-column: 1 / -1;
    }

    .ft-voice-proxy {
      display: flex;
      align-items: center;
      position: relative;
      z-index: 2;
      width: 100%;
      min-height: 46px;
      border: 0;
      background: transparent;
      color: var(--ink);
      padding: 7px 42px 7px 15px;
      text-align: left;
      font: inherit;
      font-size: 12px;
      font-weight: 850;
    }

    .ft-voice-proxy-text {
      min-width: 0;
      overflow: hidden;
      overflow-wrap: anywhere;
      white-space: normal;
      line-height: 1.22;
      display: -webkit-box;
      line-clamp: 2;
      -webkit-line-clamp: 2;
      -webkit-box-orient: vertical;
    }

    .ft-voice-shell.is-embedded-selected {
      border-color: rgba(216, 108, 255, 0.72);
      background:
        linear-gradient(135deg, rgba(216, 108, 255, 0.28), rgba(70, 240, 215, 0.14)),
        rgba(3, 13, 14, 0.88);
      box-shadow:
        inset 0 0 0 1px rgba(239, 254, 250, 0.06),
        0 0 22px rgba(216, 108, 255, 0.24),
        0 0 30px rgba(70, 240, 215, 0.1);
    }

    .ft-voice-shell.is-embedded-selected::after {
      border-color: rgba(216, 108, 255, 0.96);
      filter: drop-shadow(0 0 7px rgba(216, 108, 255, 0.58));
    }

    .ft-voice optgroup,
    .ft-voice option {
      background-color: #061112;
      color: var(--ink);
    }

    .ft-voice optgroup {
      color: #46f0d7;
      font-weight: 900;
    }

    .ft-voice option {
      font-weight: 760;
      padding: 10px 12px;
    }

    .ft-voice option:checked {
      color: #061316;
      background:
        linear-gradient(135deg, rgba(108, 240, 164, 0.95), rgba(70, 240, 215, 0.94)),
        #46f0d7;
    }

    .ft-voice optgroup.ft-voice-group-embedded {
      color: #d86cff;
    }

    .ft-voice optgroup.ft-voice-group-browser {
      color: #6cf0a4;
    }

    .ft-voice optgroup.ft-voice-group-edge {
      color: #46f0d7;
    }

    .ft-voice optgroup.ft-voice-group-microsoft {
      color: #8fd3ff;
    }

    .ft-voice optgroup.ft-voice-group-sot {
      color: #ffd166;
    }

    .ft-voice option.ft-embedded-option {
      color: #d86cff;
      background-color: #061112;
    }

    .ft-voice option.ft-browser-option {
      color: #d9fff6;
      background-color: #061112;
    }

    .ft-voice option.ft-edge-option {
      color: #7df4ff;
      background-color: #061112;
    }

    .ft-voice option.ft-microsoft-option {
      color: #8fd3ff;
      background-color: #061112;
    }

    .ft-voice option.ft-sot-option {
      color: #ffe08a;
      background-color: #061112;
    }

    .ft-voice option.ft-loading-option {
      color: rgba(170, 200, 193, 0.82);
      background-color: #061112;
    }

    .ft-voice-shell:focus-within {
      border-color: rgba(108, 240, 164, 0.72);
      box-shadow:
        0 0 0 3px rgba(108, 240, 164, 0.1),
        0 0 24px rgba(70, 240, 215, 0.2);
    }

    .ft-load-voice-shell {
      height: auto;
      min-height: 46px;
    }

    .ft-play {
      border: 0;
      padding: 0 15px;
      background: linear-gradient(135deg, var(--cyan), #d86cff);
      color: #061316;
      cursor: pointer;
      justify-self: start;
      box-shadow: 0 0 22px rgba(70, 240, 215, 0.25);
      white-space: nowrap;
    }

    .ft-next {
      border: 1px solid rgba(108, 240, 164, 0.42);
      padding: 0 15px;
      background: rgba(3, 13, 14, 0.72);
      color: var(--ink);
      cursor: pointer;
      white-space: nowrap;
    }

    .ft-next-row {
      display: flex;
      justify-content: flex-end;
      margin-top: 4px;
      flex: 0 0 auto;
      min-height: 42px;
    }

    .ft-next-row:has(.ft-next.is-hidden) {
      display: none;
      margin-top: 0;
    }

    .ft-next-row .ft-next {
      min-width: 126px;
      border-color: rgba(108, 240, 164, 0.52);
    }

    .ft-next.is-ready {
      border-color: rgba(108, 240, 164, 0.9);
      background: linear-gradient(135deg, rgba(108, 240, 164, 0.98), rgba(70, 240, 215, 0.94));
      color: #061316;
      box-shadow: 0 0 26px rgba(70, 240, 215, 0.28), 0 0 44px rgba(108, 240, 164, 0.16);
      animation: none;
    }

    .ft-next.is-attention,
    .ft-next.is-ready.is-attention,
    .ft-next.is-ready:disabled.is-attention {
      animation: nextAttentionBlink 620ms ease-in-out 4;
    }

    .ft-next:disabled {
      cursor: not-allowed;
      opacity: 0.74;
    }

    .ft-next.is-ready:disabled {
      animation: none;
      box-shadow: 0 0 16px rgba(70, 240, 215, 0.12);
      opacity: 0.82;
    }

    .ft-play:hover,
    .ft-play:focus-visible,
    .ft-next:hover,
    .ft-next:focus-visible {
      outline: none;
      filter: brightness(1.08);
    }

    .ft-play:disabled {
      cursor: wait;
      opacity: 0.72;
    }

    .ft-voice-picker {
      position: fixed;
      inset: 0;
      z-index: 44;
      display: none;
      align-items: flex-end;
      justify-content: center;
      padding: 14px;
      background:
        radial-gradient(circle at 50% 12%, rgba(70, 240, 215, 0.22), transparent 36%),
        rgba(2, 8, 9, 0.72);
      backdrop-filter: blur(13px);
      opacity: 0;
    }

    .ft-voice-picker.is-open {
      display: flex;
      animation: pickerFadeIn 180ms ease forwards;
    }

    .ft-voice-picker.is-closing {
      display: flex;
      animation: pickerFadeOut 170ms ease forwards;
    }

    .ft-voice-picker-panel {
      width: min(520px, 100%);
      max-height: min(76vh, 620px);
      border: 1px solid rgba(70, 240, 215, 0.44);
      border-radius: 24px;
      overflow: hidden;
      background:
        linear-gradient(180deg, rgba(12, 42, 40, 0.96), rgba(4, 14, 16, 0.97)),
        #061112;
      box-shadow:
        0 32px 90px rgba(0, 0, 0, 0.58),
        inset 0 0 34px rgba(70, 240, 215, 0.1);
      transform: translateY(22px) scale(0.98);
    }

    .ft-voice-picker.is-open .ft-voice-picker-panel {
      animation: pickerPanelIn 280ms cubic-bezier(.16, .84, .22, 1) forwards;
    }

    .ft-voice-picker.is-closing .ft-voice-picker-panel {
      animation: pickerPanelOut 170ms ease forwards;
    }

    .ft-voice-picker-head {
      display: grid;
      grid-template-columns: 1fr 38px;
      gap: 10px;
      align-items: center;
      padding: 15px 15px 12px;
      border-bottom: 1px solid rgba(70, 240, 215, 0.16);
      background:
        linear-gradient(90deg, rgba(108, 240, 164, 0.16), rgba(216, 108, 255, 0.1)),
        rgba(3, 13, 14, 0.52);
    }

    .ft-voice-picker-title {
      margin: 0;
      color: var(--ink);
      font-size: 13px;
      line-height: 1.2;
      font-weight: 950;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    .ft-voice-picker-close {
      width: 38px;
      height: 38px;
      border: 1px solid rgba(70, 240, 215, 0.3);
      border-radius: 13px;
      background: rgba(3, 13, 14, 0.72);
      color: var(--ink);
      font-size: 20px;
      line-height: 1;
    }

    .ft-voice-picker-list {
      max-height: min(62vh, 510px);
      overflow: auto;
      padding: 11px;
      scrollbar-color: rgba(70, 240, 215, 0.45) rgba(3, 13, 14, 0.3);
    }

    .ft-voice-picker-group {
      margin: 9px 5px 7px;
      color: #46f0d7;
      font-size: 11px;
      font-weight: 950;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    .ft-voice-choice {
      width: 100%;
      min-height: 48px;
      margin: 0 0 8px;
      border: 1px solid rgba(70, 240, 215, 0.18);
      border-radius: 16px;
      display: grid;
      grid-template-columns: 26px minmax(0, 1fr);
      gap: 9px;
      align-items: center;
      background:
        linear-gradient(135deg, rgba(70, 240, 215, 0.08), rgba(216, 108, 255, 0.04)),
        rgba(3, 13, 14, 0.72);
      color: var(--ink);
      padding: 9px 11px;
      text-align: left;
      box-shadow: inset 0 0 0 1px rgba(239, 254, 250, 0.02);
    }

    .ft-voice-choice-dot {
      width: 20px;
      height: 20px;
      border-radius: 999px;
      border: 1px solid rgba(108, 240, 164, 0.54);
      background: radial-gradient(circle, rgba(108, 240, 164, 0.9), rgba(70, 240, 215, 0.2) 48%, transparent 56%);
      box-shadow: 0 0 12px rgba(70, 240, 215, 0.18);
    }

    .ft-voice-choice-text {
      min-width: 0;
      overflow: hidden;
      overflow-wrap: anywhere;
      white-space: normal;
      line-height: 1.22;
      font-size: 13px;
      font-weight: 850;
    }

    .ft-voice-choice.is-active {
      border-color: rgba(108, 240, 164, 0.72);
      background:
        linear-gradient(135deg, rgba(108, 240, 164, 0.22), rgba(70, 240, 215, 0.16)),
        rgba(3, 13, 14, 0.88);
      box-shadow: 0 0 22px rgba(70, 240, 215, 0.18);
    }

    .ft-voice-choice.is-embedded .ft-voice-choice-dot {
      border-color: rgba(216, 108, 255, 0.72);
      background: radial-gradient(circle, rgba(216, 108, 255, 0.9), rgba(70, 240, 215, 0.22) 50%, transparent 58%);
      box-shadow: 0 0 14px rgba(216, 108, 255, 0.28);
    }

    .ft-voice-choice.is-sot .ft-voice-choice-dot {
      border-color: rgba(255, 209, 102, 0.72);
      background: radial-gradient(circle, rgba(255, 209, 102, 0.95), rgba(108, 240, 164, 0.22) 50%, transparent 58%);
    }

    .ft-voice-choice.is-microsoft .ft-voice-choice-dot {
      border-color: rgba(143, 211, 255, 0.72);
      background: radial-gradient(circle, rgba(143, 211, 255, 0.95), rgba(70, 240, 215, 0.2) 50%, transparent 58%);
    }

    .ft-play.is-loading {
      animation: playPulse 900ms ease-in-out infinite alternate;
    }

    .ft-next.is-hidden {
      display: none;
    }

    .ft-tts-status {
      min-height: 18px;
      margin-top: 8px;
      color: var(--muted);
      font-size: 12px;
      line-height: 1.35;
    }

    .ft-tts-status.is-error {
      color: var(--red);
    }

    @keyframes beamIn {
      from { opacity: 0; transform: translateX(-50%) scaleY(0.2); }
      to { opacity: 1; transform: translateX(-50%) scaleY(1); }
    }

    @keyframes hologramOpen {
      0% { opacity: 0; transform: translateY(18px) scaleY(0.06); filter: blur(6px); }
      46% { opacity: 1; transform: translateY(0) scaleY(1.06); filter: blur(1px); }
      100% { opacity: 1; transform: translateY(0) scaleY(1); filter: blur(0); }
    }

    @keyframes scan {
      0% { transform: translateY(0); opacity: 0; }
      20% { opacity: 1; }
      75% { opacity: 0.5; }
      100% { transform: translateY(390%); opacity: 0; }
    }

    @keyframes connectorIn {
      to { opacity: 1; }
    }

    @keyframes connectorDraw {
      to { stroke-dashoffset: 0; }
    }

    @keyframes connectorDash {
      to { stroke-dashoffset: -40; }
    }

    @keyframes ipaIn {
      to { opacity: 1; transform: translateY(-50%) translateX(0) scale(1); }
    }

    @keyframes playPulse {
      from { box-shadow: 0 0 18px rgba(70, 240, 215, 0.22); }
      to { box-shadow: 0 0 28px rgba(216, 108, 255, 0.42); }
