    @keyframes nextReadyPulse {
      from { transform: translateY(0); box-shadow: 0 0 22px rgba(70, 240, 215, 0.24), 0 0 34px rgba(108, 240, 164, 0.1); }
      to { transform: translateY(-1px); box-shadow: 0 0 32px rgba(70, 240, 215, 0.38), 0 0 56px rgba(108, 240, 164, 0.2); }
    }

    @keyframes nextAttentionBlink {
