    .ft-paragraph-mode {
      --paragraph-stage-pad: clamp(18px, 4vw, 54px);
      --paragraph-side-lane: 12vw;
      --paragraph-side-gap: 1vw;
      --paragraph-side-margin: 1vw;
      --paragraph-matrix-width: min(
        1080px,
        max(
          480px,
          calc(
            100vw
            - var(--paragraph-side-lane)
            - var(--paragraph-side-lane)
            - var(--paragraph-side-gap)
            - var(--paragraph-side-gap)
            - var(--paragraph-side-margin)
            - var(--paragraph-side-margin)
          )
        )
      );
      position: fixed;
      inset: 0;
      z-index: 160;
      display: grid;
      grid-template-rows: minmax(0, 1fr) auto;
      gap: 18px;
      padding: var(--paragraph-stage-pad);
      background:
        radial-gradient(circle at 18% 16%, rgba(38, 248, 255, 0.14), transparent 30%),
        radial-gradient(circle at 82% 18%, rgba(255, 186, 73, 0.12), transparent 28%),
        linear-gradient(135deg, rgba(2, 8, 18, 0.96), rgba(3, 18, 32, 0.94));
      color: #e9fbff;
      overflow: hidden;
    }

    .ft-paragraph-mode.is-hidden {
      display: none;
    }

    .ft-paragraph-mode.is-space-s {
      --paragraph-stage-pad: 5px;
      --paragraph-spoken-card-width: 212px;
      --paragraph-phonetic-card-width: 304px;
      --paragraph-bottom-side-width: 214px;
      --paragraph-bottom-center-offset: calc((var(--paragraph-spoken-card-width) - var(--paragraph-phonetic-card-width)) * 0.5);
      --paragraph-side-card-drop: clamp(44px, 3.8vw, 62px);
      --paragraph-side-lane: var(--paragraph-spoken-card-width);
      --paragraph-side-gap: 5px;
      --paragraph-side-margin: 5px;
      --paragraph-matrix-width: min(
        1080px,
        max(
          440px,
          calc(
            100vw
            - var(--paragraph-spoken-card-width)
            - var(--paragraph-phonetic-card-width)
            - var(--paragraph-side-gap)
            - var(--paragraph-side-gap)
            - var(--paragraph-side-margin)
            - var(--paragraph-side-margin)
          )
        )
      );
    }

    .ft-paragraph-shell {
      display: grid;
      place-items: center;
      min-height: 0;
    }

    .ft-paragraph-mode.is-space-s .ft-paragraph-shell {
      grid-template-columns: var(--paragraph-spoken-card-width) minmax(440px, var(--paragraph-matrix-width)) var(--paragraph-phonetic-card-width);
      align-items: stretch;
      justify-content: center;
      gap: 5px;
      width: 100%;
      padding-top: 16px;
      box-sizing: border-box;
      justify-self: center;
    }

    .ft-space-s-side-card {
      position: relative;
      display: none;
      min-width: 0;
      min-height: 220px;
      max-height: 100%;
      overflow: hidden;
      padding: 18px;
      border: 1px solid rgba(112, 246, 255, 0.36);
      clip-path: polygon(0 18px, 18px 0, calc(100% - 28px) 0, 100% 24px, 100% calc(100% - 24px), calc(100% - 24px) 100%, 0 100%);
      background:
        linear-gradient(135deg, rgba(71, 244, 255, 0.13), rgba(2, 14, 26, 0.9) 48%, rgba(255, 218, 105, 0.09)),
        repeating-linear-gradient(180deg, rgba(120, 246, 255, 0.055) 0 1px, transparent 1px 18px),
        rgba(2, 12, 24, 0.82);
      box-shadow:
        0 0 0 1px rgba(255, 255, 255, 0.045) inset,
        0 20px 54px rgba(0, 0, 0, 0.3),
        0 0 28px rgba(65, 238, 255, 0.1);
    }

    .ft-paragraph-mode.is-space-s .ft-space-s-side-card {
      display: grid;
      grid-template-rows: auto auto minmax(0, 1fr);
      gap: 10px;
      padding: 14px 12px;
      align-self: stretch;
      min-height: 0;
      margin-top: var(--paragraph-side-card-drop);
      max-height: calc(100% - var(--paragraph-side-card-drop));
    }

    .ft-space-s-spoken-card {
      width: var(--paragraph-spoken-card-width);
      max-width: var(--paragraph-spoken-card-width);
      justify-self: end;
    }

    .ft-space-s-phonetic-card {
      width: var(--paragraph-phonetic-card-width);
      max-width: var(--paragraph-phonetic-card-width);
      justify-self: start;
      cursor: pointer;
    }

    .ft-space-s-phonetic-card[data-voice-mode="alt"] {
      border-color: rgba(255, 226, 132, 0.42);
      box-shadow:
        0 0 0 1px rgba(255, 255, 255, 0.045) inset,
