      border: 1px solid rgba(118, 247, 255, 0.12);
      background:
        linear-gradient(90deg, transparent, rgba(94, 246, 255, 0.16), transparent),
        repeating-linear-gradient(90deg, rgba(94, 246, 255, 0.06) 0 1px, transparent 1px 16px);
      opacity: 0.78;
