    .ft-space-s-spoken-token.is-good {
      color: #eafff3;
      border-color: rgba(91, 255, 165, 0.42);
      background:
        linear-gradient(90deg, rgba(91, 255, 165, 0.1), rgba(91, 255, 165, 0.32), rgba(255, 226, 132, 0.18), rgba(91, 255, 165, 0.08)),
        rgba(4, 24, 22, 0.78);
      text-shadow: 0 0 12px rgba(91, 255, 165, 0.58);
