    .ft-space-s-spoken-token.is-latest.is-fresh::after {
      content: "";
      position: absolute;
      top: -0.18em;
      bottom: -0.18em;
      left: -40%;
      width: 34%;
      background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.86), rgba(86, 246, 255, 0.6), transparent);
