    .ft-paragraph-card {
      width: min(1080px, 100%);
      max-height: 100%;
      min-height: 0;
      position: relative;
      display: grid;
      grid-template-rows: auto minmax(0, 1fr);
      gap: 22px;
      isolation: isolate;
      overflow: hidden;
      padding: clamp(22px, 3vw, 42px);
      border: 1px solid rgba(120, 246, 255, 0.5);
      clip-path: polygon(0 22px, 22px 0, calc(100% - 42px) 0, 100% 34px, 100% calc(100% - 30px), calc(100% - 30px) 100%, 0 100%);
      background:
        radial-gradient(circle at 12% 8%, rgba(70, 255, 210, 0.2), transparent 28%),
        radial-gradient(circle at 92% 12%, rgba(255, 208, 92, 0.14), transparent 26%),
        linear-gradient(135deg, rgba(6, 31, 48, 0.96), rgba(1, 9, 22, 0.94) 52%, rgba(18, 20, 40, 0.92)),
        rgba(2, 18, 32, 0.9);
      box-shadow:
        0 0 0 1px rgba(255, 255, 255, 0.07) inset,
        0 0 0 8px rgba(70, 240, 255, 0.025) inset,
        0 26px 80px rgba(0, 0, 0, 0.42),
        0 0 62px rgba(34, 235, 255, 0.18);
      scrollbar-color: rgba(84, 241, 255, 0.48) rgba(2, 12, 24, 0.5);
