      .ft-paragraph-mode.is-space-s .ft-paragraph-bottom-shell {
        grid-template-columns:
          var(--paragraph-bottom-side-width)
          minmax(0, var(--paragraph-matrix-width))
          var(--paragraph-bottom-side-width);
        width: min(
          calc(var(--paragraph-matrix-width) + (var(--paragraph-bottom-side-width) * 2) + 24px),
          100%
        );
      }

      .ft-paragraph-mode.is-space-s .ft-paragraph-bottom-shell .ft-paragraph-dock {
        width: min(100%, max(360px, calc(var(--paragraph-matrix-width) * 0.9)));
        justify-self: center;
        transform: translateX(var(--paragraph-bottom-center-offset));
      }
    }

    .ft-paragraph-card::before,
    .ft-paragraph-card::after {
      content: "";
      position: absolute;
      pointer-events: none;
      z-index: 0;
    }

    .ft-paragraph-card::before {
      inset: 9px;
      clip-path: polygon(0 16px, 16px 0, calc(100% - 34px) 0, 100% 27px, 100% calc(100% - 23px), calc(100% - 23px) 100%, 0 100%);
      border: 1px solid rgba(111, 242, 255, 0.18);
      background:
        linear-gradient(90deg, transparent 0 9%, rgba(111, 242, 255, 0.32) 9% 10.4%, transparent 10.4% 68%, rgba(255, 224, 132, 0.24) 68% 69.2%, transparent 69.2%),
        linear-gradient(180deg, rgba(111, 242, 255, 0.08), transparent 24% 72%, rgba(255, 224, 132, 0.06)),
        repeating-linear-gradient(90deg, rgba(111, 242, 255, 0.055) 0 1px, transparent 1px 22px);
      opacity: 0.88;
