    .ft-paragraph-card::after {
      left: 22px;
      right: 22px;
      top: 18px;
      height: 2px;
      background: linear-gradient(90deg, transparent, rgba(75, 244, 255, 0.1), #52f6ff, #ffe48e, rgba(75, 244, 255, 0.18), transparent);
      box-shadow: 0 0 20px rgba(82, 246, 255, 0.52), 0 0 34px rgba(255, 228, 142, 0.18);
