    .ft-paragraph-token.is-active-segment:not(.is-revealed)::before {
      opacity: 0.92;
      background:
        linear-gradient(90deg, transparent 0 10%, rgba(127, 247, 255, 0.48) 10% 16%, transparent 16% 68%, rgba(255, 225, 126, 0.36) 68% 74%, transparent 74%),
        repeating-linear-gradient(90deg, rgba(127, 247, 255, 0.16) 0 1px, transparent 1px 0.38em);
    }

    .ft-paragraph-token.is-active-segment.is-revealed:not(.is-current) {
      text-shadow:
