        0 0 18px rgba(255, 214, 112, 0.08);
    }

    .ft-paragraph-token.is-space-s-matched {
      color: #eafff3;
      border-color: rgba(91, 255, 165, 0.48);
      background:
        linear-gradient(135deg, rgba(91, 255, 165, 0.14), rgba(78, 246, 255, 0.04)),
        rgba(3, 22, 20, 0.35);
      box-shadow:
        0 0 0 1px rgba(91, 255, 165, 0.18) inset,
        0 0 18px rgba(91, 255, 165, 0.22),
        0 0 26px rgba(80, 245, 255, 0.08);
      text-shadow:
        0 0 12px rgba(91, 255, 165, 0.68),
        0 0 20px rgba(255, 226, 132, 0.18);
      animation: ftSpaceSMatrixMatch 860ms cubic-bezier(0.16, 1, 0.3, 1) both;
    }

    .ft-paragraph-token.is-space-s-matched .ft-paragraph-token-tag::before {
      content: "OK";
      color: #eafff3;
      border-color: rgba(91, 255, 165, 0.54);
      background:
        linear-gradient(115deg, rgba(91, 255, 165, 0.28), rgba(10, 30, 26, 0.86) 50%, rgba(78, 246, 255, 0.22)),
        rgba(3, 22, 20, 0.68);
    }

    .ft-paragraph-mode.is-space-l .ft-paragraph-token.is-space-l-unlocked:not(.is-space-s-matched) {
      color: rgba(235, 252, 255, 0.92);
      border-color: rgba(111, 219, 255, 0.34);
      background:
        linear-gradient(135deg, rgba(111, 219, 255, 0.12), rgba(255, 226, 132, 0.06)),
        rgba(5, 18, 30, 0.5);
      box-shadow:
        0 0 0 1px rgba(111, 219, 255, 0.12) inset,
        0 0 16px rgba(111, 219, 255, 0.08);
    }

    .ft-paragraph-mode.is-space-l .ft-paragraph-token.is-space-l-missed {
      color: #fff4f4;
      border-color: rgba(255, 92, 124, 0.66);
      background:
        linear-gradient(135deg, rgba(255, 92, 124, 0.24), rgba(24, 8, 18, 0.74) 58%, rgba(255, 177, 104, 0.12)),
        rgba(30, 7, 16, 0.82);
      box-shadow:
        0 0 0 1px rgba(255, 92, 124, 0.2) inset,
        0 0 18px rgba(255, 92, 124, 0.24),
        0 0 28px rgba(255, 177, 104, 0.1);
      text-shadow:
        0 0 12px rgba(255, 92, 124, 0.46),
        0 0 20px rgba(255, 177, 104, 0.16);
      animation: ftParagraphWrongPulse 760ms cubic-bezier(0.2, 0.9, 0.2, 1) both;
    }

    .ft-paragraph-mode.is-space-l .ft-paragraph-token.is-space-l-missed .ft-paragraph-token-tag::before {
      content: "RETRY";
      color: #fff4f4;
      border-color: rgba(255, 92, 124, 0.58);
      background:
        linear-gradient(115deg, rgba(255, 92, 124, 0.32), rgba(40, 8, 20, 0.9) 52%, rgba(255, 177, 104, 0.18)),
        rgba(30, 7, 16, 0.74);
    }

    .ft-paragraph-mode.is-space-l .ft-paragraph-token.is-space-l-hidden {
      color: transparent !important;
      -webkit-text-fill-color: transparent;
      text-shadow: none !important;
    }

    .ft-paragraph-mode.is-space-l .ft-paragraph-punct.is-space-l-hidden {
      color: transparent !important;
      text-shadow: none !important;
    }

    .ft-paragraph-mode.is-space-l .ft-paragraph-token.is-space-l-choice {
      cursor: pointer;
      border-color: rgba(255, 226, 132, 0.64);
      background:
        linear-gradient(135deg, rgba(255, 226, 132, 0.16), rgba(111, 219, 255, 0.1)),
