      box-shadow:
        0 0 0 1px rgba(255, 226, 132, 0.18) inset,
        0 0 18px rgba(255, 226, 132, 0.2),
        0 0 26px rgba(111, 219, 255, 0.12);
      animation: ftSpaceLChoicePulse 1.45s ease-in-out infinite;
    }

    .ft-paragraph-mode.is-space-l .ft-paragraph-token.is-space-l-choice .ft-paragraph-token-tag::before {
      content: "PICK";
