        rgba(16, 22, 30, 0.88);
      box-shadow:
        0 0 0 1px rgba(255, 244, 196, 0.22) inset,
        0 0 18px rgba(255, 221, 120, 0.34),
        0 0 30px rgba(78, 246, 255, 0.22),
        0 0 42px rgba(255, 226, 132, 0.14);
      text-shadow:
        0 0 14px rgba(255, 233, 154, 0.72),
        0 0 22px rgba(78, 246, 255, 0.26);
      transform: translateY(-2px) scale(1.035);
      animation: ftParagraphAudioReadPulse 900ms cubic-bezier(0.16, 1, 0.3, 1) infinite;
    }

    .ft-paragraph-mode.is-paragraph-audio-reading .ft-paragraph-token.is-reading .ft-paragraph-token-tag::before {
      content: "PLAY";
      color: #ffffff;
      border-color: rgba(255, 238, 176, 0.82);
      background:
        linear-gradient(115deg, rgba(255, 226, 126, 0.42), rgba(18, 31, 40, 0.78) 48%, rgba(78, 246, 255, 0.34)),
        linear-gradient(180deg, rgba(255, 255, 255, 0.18), transparent 54%),
        rgba(38, 25, 8, 0.62);
      box-shadow:
        0 0 0 1px rgba(255, 255, 255, 0.1) inset,
        -0.12em 0 0 rgba(255, 214, 103, 0.38) inset,
        0 0 12px rgba(255, 219, 108, 0.42),
        0 0 18px rgba(72, 238, 255, 0.28);
    }

    .ft-paragraph-mode.is-paragraph-audio-reading .ft-paragraph-token.is-reading .ft-paragraph-token-tag::after {
