      animation: ftParagraphAudioReadSweep 760ms cubic-bezier(0.16, 1, 0.3, 1) infinite;
    }

    .ft-paragraph-punct {
      display: inline-block;
      position: relative;
      margin: 0 0.03em 0.18em 0;
      color: rgba(174, 232, 238, 0.58);
      text-shadow: 0 0 10px rgba(69, 237, 255, 0.14);
      user-select: none;
      -webkit-user-select: none;
      transition: color 220ms ease, text-shadow 220ms ease, transform 220ms ease;
    }

    .ft-paragraph-punct.is-active-segment {
      color: #ffe7a3;
      text-shadow:
        0 0 10px rgba(255, 216, 115, 0.48),
        0 0 18px rgba(69, 237, 255, 0.22);
      transform: translateY(-0.02em);
    }

    .ft-paragraph-punct.is-revealed {
      color: #f6feff;
      text-shadow: 0 0 10px rgba(95, 246, 255, 0.28);
    }

    .ft-paragraph-punct.is-hinted {
      color: #ffb24f;
      text-shadow:
        0 0 10px rgba(255, 178, 79, 0.55),
        0 0 18px rgba(255, 97, 65, 0.22);
    }

    .ft-paragraph-mode.is-paragraph-audio-reading .ft-paragraph-punct.is-reading {
      color: #fff2c5;
      text-shadow:
        0 0 12px rgba(255, 221, 120, 0.56),
        0 0 18px rgba(78, 246, 255, 0.24);
      transform: translateY(-0.05em) scale(1.04);
    }

    .ft-paragraph-token.is-current {
      border-color: rgba(255, 225, 122, 0.78);
      box-shadow:
        0 0 0 1px rgba(255, 225, 122, 0.28) inset,
        0 0 22px rgba(255, 225, 122, 0.28),
        0 0 28px rgba(66, 244, 255, 0.12);
      transform: translateY(-1px);
    }

    .ft-paragraph-token.is-revealed.has-word-note {
      cursor: pointer;
      text-decoration: none;
    }

    .ft-paragraph-token.is-revealed.has-word-note:hover {
      color: #ffffff;
      text-shadow:
        0 0 12px rgba(95, 246, 255, 0.48),
        0 0 20px rgba(255, 226, 132, 0.24);
    }

    .ft-paragraph-space {
      white-space: pre-wrap;
      user-select: none;
      -webkit-user-select: none;
    }

    .ft-paragraph-word-notes {
      --paragraph-note-top: 104px;
      --paragraph-note-height: min(420px, 52vh);
      --paragraph-note-width: var(--paragraph-side-lane);
      --paragraph-note-left: var(--paragraph-side-margin);
      --paragraph-note-right: var(--paragraph-side-margin);
      position: fixed;
      inset: 0;
      z-index: 172;
      pointer-events: none;
    }

    .ft-paragraph-word-notes.is-hidden {
      display: none;
    }

    .ft-paragraph-word-note {
      position: absolute;
      top: var(--paragraph-note-top);
      width: var(--paragraph-note-width);
      max-height: var(--paragraph-note-height);
      min-height: 132px;
      display: grid;
      grid-template-rows: auto minmax(0, 1fr);
      gap: 8px;
      padding: 13px 14px 14px;
      overflow: hidden;
      pointer-events: auto;
      color: #eaffff;
      border: 1px solid rgba(99, 244, 255, 0.42);
      clip-path: polygon(0 16px, 16px 0, calc(100% - 26px) 0, 100% 22px, 100% 100%, 22px 100%, 0 calc(100% - 22px));
      background:
        radial-gradient(circle at 16% 0%, rgba(95, 246, 255, 0.16), transparent 34%),
        radial-gradient(circle at 96% 100%, rgba(255, 226, 132, 0.12), transparent 34%),
        linear-gradient(145deg, rgba(2, 24, 38, 0.94), rgba(1, 8, 18, 0.92));
      box-shadow:
        0 18px 54px rgba(0, 0, 0, 0.38),
        0 0 0 1px rgba(255, 255, 255, 0.05) inset,
        0 0 28px rgba(62, 242, 255, 0.12);
      animation: ftParagraphWordNoteIn 260ms cubic-bezier(0.16, 1, 0.3, 1) both;
    }

    .ft-paragraph-word-note.is-left {
      left: var(--paragraph-note-left);
    }

    .ft-paragraph-word-note.is-right {
      right: var(--paragraph-note-right);
      border-color: rgba(255, 226, 132, 0.4);
    }

    .ft-paragraph-word-note::before {
      content: "";
      position: absolute;
      inset: 6px;
      pointer-events: none;
      border: 1px solid rgba(255, 255, 255, 0.055);
      clip-path: polygon(0 12px, 12px 0, calc(100% - 22px) 0, 100% 18px, 100% 100%, 18px 100%, 0 calc(100% - 18px));
      background:
        linear-gradient(90deg, rgba(95, 246, 255, 0.22), transparent 18% 78%, rgba(255, 226, 132, 0.18)),
        repeating-linear-gradient(90deg, rgba(95, 246, 255, 0.055) 0 1px, transparent 1px 18px);
      opacity: 0.72;
    }

    .ft-paragraph-word-note-head {
      position: relative;
      z-index: 1;
      display: grid;
      grid-template-columns: minmax(0, 1fr) auto;
      gap: 8px;
      align-items: start;
    }

    .ft-paragraph-word-note-kicker {
      color: rgba(170, 250, 255, 0.82);
      font-size: 9px;
      font-weight: 950;
      letter-spacing: 0.18em;
      text-transform: uppercase;
    }

    .ft-paragraph-word-note-title {
      margin-top: 4px;
      color: #ffffff;
      font-size: 17px;
      font-weight: 950;
      line-height: 1.15;
      overflow-wrap: anywhere;
      text-shadow:
        0 0 12px rgba(95, 246, 255, 0.34),
        0 0 18px rgba(255, 226, 132, 0.14);
    }

    .ft-paragraph-word-note-close {
      width: 28px;
      height: 28px;
      border: 1px solid rgba(255, 226, 132, 0.38);
      color: #ffe684;
      background: rgba(0, 9, 18, 0.68);
      clip-path: polygon(0 7px, 7px 0, 100% 0, 100% calc(100% - 7px), calc(100% - 7px) 100%, 0 100%);
      font-weight: 950;
      cursor: pointer;
      box-shadow: 0 0 12px rgba(255, 226, 132, 0.1);
    }

    .ft-paragraph-word-note-body {
      position: relative;
      z-index: 1;
      min-height: 64px;
      overflow: auto;
      padding: 10px 11px;
      color: #eaffff;
      border: 1px solid rgba(95, 246, 255, 0.18);
      background:
        linear-gradient(135deg, rgba(95, 246, 255, 0.08), rgba(255, 226, 132, 0.035)),
        rgba(0, 8, 17, 0.56);
      font-size: 13px;
      line-height: 1.5;
      white-space: pre-wrap;
      overflow-wrap: anywhere;
      scrollbar-color: rgba(92, 246, 255, 0.5) rgba(0, 8, 17, 0.36);
      text-shadow: 0 0 10px rgba(95, 246, 255, 0.12);
    }

    .ft-paragraph-word-note-body.is-typing::after {
      content: "";
      display: inline-block;
      width: 7px;
      height: 1.1em;
      margin-left: 3px;
      vertical-align: -0.16em;
      background: linear-gradient(180deg, #5ff6ff, #ffe684);
      box-shadow: 0 0 12px rgba(95, 246, 255, 0.58);
      animation: ftParagraphWordNoteCaret 520ms ease-in-out infinite;
    }

    @media (min-width: 900px) {
      .ft-paragraph-word-note {
        gap: 6px;
        padding: clamp(8px, 0.7vw, 13px);
      }

      .ft-paragraph-word-note::before {
        inset: clamp(4px, 0.4vw, 6px);
      }

      .ft-paragraph-word-note-head {
        gap: 5px;
      }

      .ft-paragraph-word-note-kicker {
        font-size: clamp(11px, 0.72vw, 13px);
        letter-spacing: 0.1em;
      }

      .ft-paragraph-word-note-title {
        font-size: clamp(15px, 1.04vw, 20px);
        line-height: 1.12;
      }

      .ft-paragraph-word-note-close {
        width: clamp(22px, 1.55vw, 28px);
        height: clamp(22px, 1.55vw, 28px);
      }

      .ft-paragraph-word-note-body {
        min-height: 52px;
        padding: clamp(7px, 0.6vw, 10px);
        font-size: clamp(14px, 0.88vw, 16px);
        line-height: 1.42;
      }
    }

    .ft-paragraph-dock {
      width: min(980px, 100%);
      justify-self: center;
      display: grid;
      position: relative;
      isolation: isolate;
      gap: 12px;
      padding: 18px 18px 16px;
      border: 1px solid rgba(105, 244, 255, 0.48);
      clip-path: polygon(0 18px, 18px 0, calc(100% - 44px) 0, 100% 32px, 100% 100%, 34px 100%, 0 calc(100% - 34px));
      background:
        linear-gradient(135deg, rgba(5, 30, 42, 0.92), rgba(2, 10, 22, 0.94) 48%, rgba(18, 20, 38, 0.9)),
        radial-gradient(circle at 12% 0%, rgba(58, 242, 255, 0.22), transparent 34%),
