    .ft-paragraph-input-row::before {
      inset: -6px;
      clip-path: polygon(0 0, calc(100% - 22px) 0, 100% 22px, 100% 100%, 22px 100%, 0 calc(100% - 22px));
      border: 1px solid rgba(86, 246, 255, 0.28);
      background:
        linear-gradient(90deg, transparent 0 12%, rgba(82, 246, 255, 0.24) 12% 14%, transparent 14% 72%, rgba(255, 226, 132, 0.2) 72% 74%, transparent 74%),
        linear-gradient(180deg, rgba(82, 246, 255, 0.06), transparent 50%, rgba(255, 226, 132, 0.05));
      box-shadow:
        0 0 0 1px rgba(255, 255, 255, 0.04) inset,
        0 0 24px rgba(64, 243, 255, 0.1);
