    .ft-paragraph-input-row::after {
      top: -4px;
      bottom: -4px;
      left: -24%;
      width: 18%;
      background:
        linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.78), rgba(82, 246, 255, 0.68), rgba(255, 226, 132, 0.5), transparent);
      filter: blur(5px);
      transform: skewX(-18deg);
