    .ft-paragraph-input-row.is-paragraph-typing::before {
      animation: ftParagraphInputFramePulse 520ms cubic-bezier(0.16, 1, 0.3, 1) both;
    }

    .ft-paragraph-input-row.is-paragraph-typing::after {
      animation: ftParagraphInputSweep 560ms cubic-bezier(0.16, 1, 0.3, 1) both;
    }

    .ft-paragraph-input-row.is-paragraph-good::before {
      border-color: rgba(91, 255, 165, 0.56);
      box-shadow:
        0 0 0 1px rgba(91, 255, 165, 0.18) inset,
        0 0 28px rgba(91, 255, 165, 0.22),
        0 0 22px rgba(255, 226, 132, 0.1);
      animation: ftParagraphInputGoodPulse 760ms cubic-bezier(0.16, 1, 0.3, 1) both;
    }

    .ft-paragraph-input-row.is-paragraph-good::after {
      background:
        linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.84), rgba(91, 255, 165, 0.72), rgba(255, 226, 132, 0.62), transparent);
      animation: ftParagraphInputSweep 720ms cubic-bezier(0.16, 1, 0.3, 1) both;
    }

    .ft-paragraph-input-row.is-paragraph-wrong::before {
      border-color: rgba(255, 95, 115, 0.56);
      box-shadow:
        0 0 0 1px rgba(255, 95, 115, 0.18) inset,
        0 0 28px rgba(255, 95, 115, 0.2),
        0 0 18px rgba(255, 178, 79, 0.08);
      animation: ftParagraphInputWrongPulse 620ms cubic-bezier(0.16, 1, 0.3, 1) both;
    }

    .ft-paragraph-input-row.is-paragraph-wrong::after {
      background:
        linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.74), rgba(255, 95, 115, 0.72), rgba(255, 178, 79, 0.5), transparent);
      animation: ftParagraphInputSweep 620ms cubic-bezier(0.16, 1, 0.3, 1) both;
    }

    .ft-paragraph-input-wrap {
      position: relative;
      z-index: 2;
      display: block;
      min-width: 0;
      overflow: hidden;
      border: 1px solid rgba(100, 235, 255, 0.54);
      clip-path: polygon(0 0, calc(100% - 18px) 0, 100% 18px, 100% 100%, 0 100%);
