    }

    .ft-paragraph-input-wrap.is-manual-locked {
      border-color: rgba(96, 188, 198, 0.42);
      box-shadow:
        0 0 0 1px rgba(173, 240, 245, 0.04) inset,
        0 0 16px rgba(67, 245, 255, 0.05);
      filter: saturate(0.9);
