    .ft-paragraph-input-wrap:focus-within {
      border-color: rgba(255, 216, 103, 0.82);
      box-shadow:
        0 0 30px rgba(255, 216, 103, 0.2),
        0 0 34px rgba(67, 245, 255, 0.12),
        0 0 0 1px rgba(255, 216, 103, 0.24) inset;
    }

    .ft-paragraph-input-ghost {
      position: absolute;
      inset: 0;
      display: block;
      min-width: 100%;
      padding: 16px 18px;
      overflow: visible;
      white-space: pre;
      color: #efffff;
      font-size: 19px;
      line-height: normal;
      pointer-events: none;
      transform: translateX(var(--paragraph-input-scroll, 0px));
      text-shadow: 0 0 10px rgba(67, 245, 255, 0.12);
    }

    .ft-paragraph-input-last {
      position: relative;
      display: inline-block;
      color: #ffffff;
      text-shadow:
        0 0 12px rgba(82, 246, 255, 0.48),
        0 0 20px rgba(255, 226, 132, 0.18);
    }

    .ft-paragraph-input-last::before,
    .ft-paragraph-input-last::after {
      content: "";
      position: absolute;
      pointer-events: none;
      opacity: 0;
    }

    .ft-paragraph-input-last::before {
      inset: -0.08em -0.18em -0.1em;
      z-index: -1;
      background:
        linear-gradient(90deg, rgba(78, 246, 255, 0.06), rgba(78, 246, 255, 0.34), rgba(255, 226, 132, 0.22), rgba(78, 246, 255, 0.06));
      border: 1px solid rgba(100, 244, 255, 0.24);
      clip-path: polygon(0 0, calc(100% - 0.36em) 0, 100% 0.34em, 100% 100%, 0.28em 100%, 0 calc(100% - 0.28em));
      box-shadow: 0 0 16px rgba(67, 245, 255, 0.16);
    }

    .ft-paragraph-input-last::after {
      top: -0.24em;
      bottom: -0.24em;
      left: -36%;
      width: 32%;
      background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.88), rgba(86, 246, 255, 0.62), transparent);
      filter: blur(0.04em);
      transform: skewX(-18deg);
    }

    .ft-paragraph-input-last.is-typing::before {
      animation: ftParagraphLastWordPlate 620ms cubic-bezier(0.16, 1, 0.3, 1) both;
    }

    .ft-paragraph-input-last.is-typing::after {
      animation: ftParagraphLastWordSweep 680ms cubic-bezier(0.16, 1, 0.3, 1) both;
    }

    .ft-paragraph-input-last.is-good {
      color: #eafff3;
      text-shadow:
        0 0 12px rgba(91, 255, 165, 0.66),
        0 0 22px rgba(255, 226, 132, 0.3);
    }

    .ft-paragraph-input-last.is-good::before {
      border-color: rgba(91, 255, 165, 0.34);
      background: linear-gradient(90deg, rgba(91, 255, 165, 0.08), rgba(91, 255, 165, 0.38), rgba(255, 226, 132, 0.26), rgba(91, 255, 165, 0.08));
      box-shadow: 0 0 18px rgba(91, 255, 165, 0.2);
      animation: ftParagraphLastWordPlate 780ms cubic-bezier(0.16, 1, 0.3, 1) both;
    }

    .ft-paragraph-input-last.is-good::after {
      background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.88), rgba(91, 255, 165, 0.72), rgba(255, 226, 132, 0.48), transparent);
      animation: ftParagraphLastWordSweep 780ms cubic-bezier(0.16, 1, 0.3, 1) both;
    }

    .ft-paragraph-input-last.is-wrong {
      color: #fff3f4;
      text-shadow:
        0 0 12px rgba(255, 95, 115, 0.66),
        0 0 18px rgba(255, 178, 79, 0.24);
    }

    .ft-paragraph-input-last.is-wrong::before {
      border-color: rgba(255, 95, 115, 0.34);
      background: linear-gradient(90deg, rgba(255, 95, 115, 0.08), rgba(255, 95, 115, 0.34), rgba(255, 178, 79, 0.22), rgba(255, 95, 115, 0.08));
      box-shadow: 0 0 18px rgba(255, 95, 115, 0.2);
      animation: ftParagraphLastWordWrong 620ms cubic-bezier(0.16, 1, 0.3, 1) both;
    }

    .ft-paragraph-input-last.is-wrong::after {
      background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.84), rgba(255, 95, 115, 0.72), transparent);
      animation: ftParagraphLastWordSweep 620ms cubic-bezier(0.16, 1, 0.3, 1) both;
    }

    .ft-paragraph-input {
      position: relative;
      z-index: 2;
      width: 100%;
      padding: 16px 18px;
      border: 0;
      border-radius: 0;
      background: transparent;
      color: transparent;
      caret-color: #fff1a8;
      font-size: 19px;
      outline: none;
      box-shadow: none;
      transition: border-color 180ms ease, box-shadow 180ms ease, filter 180ms ease;
    }

    .ft-paragraph-input[readonly] {
      cursor: default;
    }

    .ft-paragraph-input-row.is-manual-locked .ft-paragraph-input {
      caret-color: transparent;
    }

    .ft-paragraph-input::placeholder {
      color: rgba(185, 248, 255, 0.42);
    }

    .ft-paragraph-input-row.is-paragraph-typing .ft-paragraph-input-wrap {
      filter: brightness(1.08);
      border-color: rgba(112, 246, 255, 0.78);
      box-shadow:
        0 0 0 1px rgba(112, 246, 255, 0.16) inset,
        0 0 26px rgba(67, 245, 255, 0.16),
        0 0 18px rgba(255, 226, 132, 0.08);
    }

    .ft-paragraph-input-row.is-paragraph-good .ft-paragraph-input-wrap {
      border-color: rgba(91, 255, 165, 0.78);
      box-shadow:
        0 0 0 1px rgba(91, 255, 165, 0.18) inset,
        0 0 28px rgba(91, 255, 165, 0.18),
        0 0 22px rgba(255, 226, 132, 0.1);
    }

    .ft-paragraph-input-row.is-paragraph-wrong .ft-paragraph-input-wrap {
      border-color: rgba(255, 95, 115, 0.78);
      box-shadow:
        0 0 0 1px rgba(255, 95, 115, 0.18) inset,
        0 0 28px rgba(255, 95, 115, 0.16);
    }

    .ft-paragraph-replay {
      position: relative;
      z-index: 1;
      min-width: 68px;
      min-height: 44px;
      padding: 0 12px;
      border: 1px solid rgba(96, 235, 255, 0.36);
      clip-path: polygon(0 0, calc(100% - 11px) 0, 100% 11px, 100% 100%, 11px 100%, 0 calc(100% - 11px));
      color: rgba(232, 252, 255, 0.96);
      font-size: 11px;
      font-weight: 900;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      background:
        linear-gradient(135deg, rgba(78, 246, 255, 0.14), rgba(3, 14, 24, 0.9) 52%, rgba(255, 226, 132, 0.12)),
        rgba(4, 16, 28, 0.88);
      box-shadow:
        0 0 0 1px rgba(255, 255, 255, 0.04) inset,
        0 0 18px rgba(67, 245, 255, 0.08);
      cursor: pointer;
      transition: border-color 180ms ease, box-shadow 180ms ease, transform 180ms ease, opacity 180ms ease;
    }

    .ft-paragraph-replay.is-ready {
      border-color: rgba(96, 235, 255, 0.52);
      box-shadow:
        0 0 0 1px rgba(255, 255, 255, 0.05) inset,
        0 0 20px rgba(67, 245, 255, 0.12),
        0 0 14px rgba(255, 226, 132, 0.08);
    }

    .ft-paragraph-replay.is-playing {
      border-color: rgba(255, 226, 132, 0.62);
      box-shadow:
        0 0 0 1px rgba(255, 255, 255, 0.05) inset,
        0 0 22px rgba(255, 226, 132, 0.16),
        0 0 16px rgba(67, 245, 255, 0.12);
      transform: translateY(-1px);
