    .ft-paragraph-replay:disabled {
      opacity: 0.36;
      cursor: default;
      box-shadow: none;
    }

    .ft-paragraph-next {
      position: relative;
      z-index: 1;
      min-width: 120px;
      border: 1px solid rgba(95, 241, 255, 0.62);
      clip-path: polygon(0 0, calc(100% - 16px) 0, 100% 16px, 100% 100%, 16px 100%, 0 calc(100% - 16px));
      color: #06131d;
      font-weight: 900;
      text-transform: uppercase;
      letter-spacing: 0.12em;
      background:
        linear-gradient(135deg, #42f4ff, #fff08b),
        repeating-linear-gradient(90deg, rgba(255, 255, 255, 0.26) 0 1px, transparent 1px 8px);
      cursor: pointer;
      box-shadow: 0 0 20px rgba(66, 244, 255, 0.24);
      animation: ftParagraphButtonEnergy 2.8s ease-in-out infinite;
    }

    .ft-paragraph-next:disabled {
      opacity: 0.45;
      cursor: default;
      animation: none;
    }

    .ft-paragraph-status {
      min-height: 20px;
      display: flex;
      align-items: center;
      gap: 8px;
      color: rgba(184, 248, 255, 0.9);
      font-size: 12px;
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }

    .ft-paragraph-status::before {
      content: "";
      width: 7px;
      height: 7px;
      border-radius: 50%;
      background: #43f5ff;
      box-shadow: 0 0 12px rgba(67, 245, 255, 0.92), 0 0 24px rgba(255, 224, 120, 0.24);
      animation: ftParagraphStatusPulse 1.8s ease-in-out infinite;
      flex: 0 0 auto;
    }

    .ft-paragraph-mode.is-space-s-mic-live .ft-paragraph-status::before {
      background: #55ff9d;
      box-shadow: 0 0 14px rgba(91, 255, 165, 0.96), 0 0 24px rgba(67, 245, 255, 0.24);
      animation-duration: 900ms;
    }

    .ft-paragraph-explain-layer {
      position: fixed;
      inset: 0;
      z-index: 175;
      display: grid;
      place-items: center;
      padding: clamp(16px, 4vw, 44px);
      background:
        radial-gradient(circle at 50% 38%, rgba(66, 244, 255, 0.13), transparent 36%),
        rgba(0, 5, 12, 0.58);
      backdrop-filter: blur(8px);
    }

    .ft-paragraph-explain-layer.is-hidden {
      display: none;
    }

    .ft-paragraph-explain-card {
      width: min(760px, 100%);
      max-height: min(680px, 88vh);
      display: grid;
      grid-template-rows: auto minmax(0, 1fr) auto;
      position: relative;
      isolation: isolate;
      padding: 20px;
      border: 1px solid rgba(105, 244, 255, 0.5);
      clip-path: polygon(0 24px, 24px 0, calc(100% - 54px) 0, 100% 38px, 100% 100%, 34px 100%, 0 calc(100% - 34px));
      background:
        radial-gradient(circle at 12% 0%, rgba(80, 247, 255, 0.18), transparent 32%),
        radial-gradient(circle at 92% 100%, rgba(255, 218, 112, 0.14), transparent 30%),
        linear-gradient(135deg, rgba(5, 30, 44, 0.96), rgba(1, 10, 22, 0.97));
      box-shadow:
        0 24px 90px rgba(0, 0, 0, 0.56),
        0 0 70px rgba(44, 238, 255, 0.18),
        0 0 0 1px rgba(255, 255, 255, 0.06) inset;
      animation: ftParagraphExplainIn 360ms cubic-bezier(0.16, 1, 0.3, 1) both;
    }

    .ft-paragraph-explain-card::before {
      content: "";
      position: absolute;
      inset: 8px;
      pointer-events: none;
      border: 1px solid rgba(255, 226, 134, 0.18);
      clip-path: polygon(0 16px, 16px 0, calc(100% - 42px) 0, 100% 29px, 100% 100%, 25px 100%, 0 calc(100% - 25px));
      background:
        linear-gradient(90deg, rgba(78, 246, 255, 0.28), transparent 13% 82%, rgba(255, 226, 134, 0.24)),
        repeating-linear-gradient(90deg, rgba(78, 246, 255, 0.05) 0 1px, transparent 1px 20px);
      opacity: 0.72;
      z-index: -1;
    }

    .ft-paragraph-explain-head {
      display: grid;
      grid-template-columns: minmax(0, 1fr) auto;
      gap: 14px;
      align-items: start;
      margin-bottom: 16px;
    }

    .ft-paragraph-explain-kicker {
      color: rgba(166, 246, 255, 0.84);
      font-size: 11px;
      font-weight: 900;
      letter-spacing: 0.22em;
      text-transform: uppercase;
    }

    .ft-paragraph-explain-title {
      margin-top: 8px;
      color: #ffffff;
      font-size: clamp(20px, 2.3vw, 30px);
      font-weight: 900;
      line-height: 1.14;
      text-shadow: 0 0 20px rgba(67, 245, 255, 0.2);
    }

    .ft-paragraph-explain-close {
      width: 38px;
      height: 38px;
      border: 1px solid rgba(255, 226, 134, 0.42);
      color: #fff0a8;
      background: rgba(2, 12, 24, 0.74);
      clip-path: polygon(0 9px, 9px 0, 100% 0, 100% calc(100% - 9px), calc(100% - 9px) 100%, 0 100%);
      font-size: 21px;
      line-height: 1;
      cursor: pointer;
      box-shadow: 0 0 18px rgba(255, 226, 134, 0.12);
    }

    .ft-paragraph-explain-body {
      min-height: 180px;
      overflow: auto;
      padding: 18px;
      color: #eaffff;
      border: 1px solid rgba(95, 241, 255, 0.22);
      clip-path: polygon(0 14px, 14px 0, 100% 0, 100% calc(100% - 18px), calc(100% - 18px) 100%, 0 100%);
      background:
        linear-gradient(135deg, rgba(72, 241, 255, 0.08), rgba(255, 225, 122, 0.04)),
        rgba(0, 9, 18, 0.58);
      font-size: clamp(16px, 1.6vw, 20px);
      line-height: 1.58;
      white-space: pre-wrap;
      scrollbar-color: rgba(84, 241, 255, 0.48) rgba(2, 12, 24, 0.5);
    }

    .ft-paragraph-explain-foot {
      display: grid;
      grid-template-columns: auto minmax(84px, 1fr) auto;
      gap: 12px;
      align-items: center;
      margin-top: 16px;
    }

    .ft-paragraph-explain-nav {
      min-height: 38px;
      padding: 0 14px;
      border: 1px solid rgba(105, 244, 255, 0.42);
      color: #dffcff;
      background:
        linear-gradient(135deg, rgba(70, 244, 255, 0.14), rgba(255, 226, 134, 0.06)),
        rgba(1, 12, 22, 0.78);
      clip-path: polygon(0 9px, 9px 0, 100% 0, 100% calc(100% - 9px), calc(100% - 9px) 100%, 0 100%);
      font-size: 11px;
      font-weight: 950;
      letter-spacing: 0.16em;
