    .ft-paragraph-explain-index {
      justify-self: center;
      color: rgba(255, 226, 134, 0.92);
      font-size: 12px;
      font-weight: 900;
      letter-spacing: 0.18em;
      text-transform: uppercase;
      text-shadow: 0 0 14px rgba(255, 226, 134, 0.2);
    }

    @keyframes ftParagraphDockScan {
      0%, 100% {
        transform: scaleX(0.22);
        opacity: 0.22;
      }
      42% {
        transform: scaleX(0.92);
        opacity: 0.95;
      }
      64% {
        transform: scaleX(0.46);
        opacity: 0.38;
      }
    }

    @keyframes ftParagraphCardScan {
      0%, 100% {
        transform: translateX(-6%) scaleX(0.18);
        opacity: 0.16;
      }
      34% {
        transform: translateX(18%) scaleX(0.62);
        opacity: 0.72;
      }
      58% {
        transform: translateX(62%) scaleX(0.32);
        opacity: 0.38;
      }
      76% {
        transform: translateX(92%) scaleX(0.12);
        opacity: 0.12;
      }
    }

    @keyframes ftParagraphButtonEnergy {
      0%, 100% {
        filter: brightness(1);
        transform: translateY(0);
      }
      45% {
        filter: brightness(1.18);
        transform: translateY(-1px);
      }
