      }
      50% {
        transform: scale(1.16);
        opacity: 1;
      }
    }

    @keyframes ftParagraphMicBar {
      0%, 100% {
        transform: scaleY(0.34);
        opacity: 0.68;
      }
      35% {
        transform: scaleY(1);
        opacity: 1;
