  border-bottom: 1px solid rgba(120, 73, 34, 0.14);
  color: #6f4f36;
  background: transparent;
}

.ft-space-test-pagebar b {
  color: #2b2118;
  font-size: 1.05rem;
}

.ft-space-test-pagebar span {
  min-width: 62px;
  padding: 6px 10px;
  border: 1px solid rgba(194, 100, 30, 0.24);
  border-radius: 999px;
  color: #9a4f13;
  background: #fff4e3;
  font-size: 0.82rem;
  font-weight: 900;
  text-align: center;
}

.ft-space-test-page-grid {
  display: grid;
  grid-template-columns: minmax(0, 0.92fr) minmax(0, 1.08fr);
  gap: 18px;
  align-items: start;
  min-height: 100%;
}

.ft-space-test-page-grid.has-resource-panel {
  grid-template-columns: minmax(0, 0.94fr) minmax(0, 1.06fr);
}

.ft-space-test-resource-panel,
.ft-space-test-question-panel {
  min-width: 0;
  display: grid;
  gap: 14px;
}

.ft-space-test-resource-panel {
  padding-right: 12px;
  border-right: 1px solid rgba(120, 73, 34, 0.14);
}

.ft-space-test-question-panel {
  padding-left: 12px;
}

.ft-space-test-empty-panel {
  padding: 18px;
  border: 1px dashed rgba(147, 97, 51, 0.38);
  border-radius: 8px;
  color: #7a5c42;
  background: rgba(255, 250, 242, 0.74);
}

.ft-space-test-text {
  max-width: 980px;
  color: #382b20;
  font-size: 1.04rem;
  line-height: 1.78;
}

.ft-space-test-text p {
  margin: 0 0 1em;
}

.ft-space-test-media {
  max-width: 1080px;
  margin: 18px 0;
}

.ft-space-test-media img {
  display: block;
  max-width: 100%;
  max-height: 64dvh;
  border: 1px solid rgba(120, 73, 34, 0.16);
  border-radius: 8px;
  object-fit: contain;
  background: #fffaf2;
}

.ft-space-test-media figcaption,
.ft-space-test-audio span,
.ft-space-test-points {
  color: #8a6a4a;
  font-size: 0.82rem;
  font-weight: 850;
}

.ft-space-test-audio {
  max-width: 980px;
  display: grid;
  gap: 8px;
  margin: 18px 0;
  padding: 14px;
  border: 1px solid rgba(194, 100, 30, 0.18);
  border-radius: 8px;
  background: #fff2dc;
}

.ft-space-test-audio audio {
  width: 100%;
}

.ft-space-test-question {
  max-width: 1080px;
  margin: 20px 0;
  padding: clamp(16px, 2.1vw, 24px);
  border: 1px solid rgba(147, 97, 51, 0.16);
  border-left: 4px solid #d97706;
  border-radius: 8px;
  background: #fffaf2;
  box-shadow: 0 10px 24px rgba(90, 55, 24, 0.08);
}

.ft-space-test-question h3 {
  margin: 0 0 8px;
  color: #2b2118;
  font-size: 1.08rem;
  line-height: 1.4;
}

.ft-space-test-choices {
  display: grid;
  grid-template-columns: 1fr;
  gap: 12px;
  margin-top: 16px;
}

.ft-space-test-choices label {
  position: relative;
  display: grid;
  grid-template-columns: auto 38px minmax(0, 1fr);
  gap: 12px;
  align-items: center;
  min-height: 62px;
  padding: 12px 14px;
  border: 1px solid rgba(120, 73, 34, 0.14);
  border-radius: 8px;
  background: linear-gradient(180deg, #fffdf8 0%, #fff6e8 100%);
  box-shadow: 0 6px 18px rgba(90, 55, 24, 0.05);
}

.ft-space-test-choices label:hover {
  border-color: rgba(217, 119, 6, 0.34);
  background: #fff1d8;
}

.ft-space-test-choices label:has(input:checked) {
  border-color: rgba(217, 119, 6, 0.55);
  background: linear-gradient(180deg, #fff2d9 0%, #ffe4bd 100%);
  box-shadow: inset 0 0 0 1px rgba(217, 119, 6, 0.18), 0 8px 20px rgba(146, 84, 18, 0.10);
}

.ft-space-test-choices input {
  margin: 0;
  accent-color: #c2410c;
}

.ft-space-test-choice-key {
  width: 34px;
  height: 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  color: #9a4f13;
  background: #fff0d7;
  font-weight: 950;
}

.ft-space-test-choices label:has(input:checked) .ft-space-test-choice-key {
  color: #ffffff;
  background: #c2410c;
}

.ft-space-test-choice-text {
  min-width: 0;
  color: #332519;
  line-height: 1.45;
}

.ft-space-test-question textarea {
  width: 100%;
  min-height: 180px;
  margin-top: 14px;
  padding: 14px;
  border: 1px solid rgba(120, 73, 34, 0.18);
  border-radius: 8px;
  resize: vertical;
  color: #2a211a;
  background: #fffdf8;
  font: inherit;
  line-height: 1.55;
}

.ft-space-test-question textarea:focus,
.ft-space-test-choices label:focus-within {
  outline: 2px solid rgba(217, 119, 6, 0.24);
  outline-offset: 2px;
}

.ft-space-test-question.is-ai-graded {
  border-left-color: #14b8a6;
}

.ft-space-test-speaking-vi {
  margin: 0 0 12px;
  color: #7a4f27;
  line-height: 1.5;
}

.ft-space-test-speaking-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 14px;
}

.ft-space-test-speaking-actions button {
  min-height: 42px;
  padding: 0 16px;
  border: 1px solid rgba(120, 73, 34, 0.18);
  border-radius: 6px;
  color: #2a211a;
  background: #fffdf8;
  font-weight: 850;
  cursor: pointer;
}

.ft-space-test-speaking-actions button:hover {
  border-color: rgba(217, 119, 6, 0.38);
  background: #fff1d8;
}

.ft-space-test-speaking-actions button.is-recording {
  border-color: #dc2626;
  color: #ffffff;
  background: #dc2626;
}

.ft-space-test-speaking-status {
  min-height: 24px;
  margin-top: 12px;
  color: #8a5a2b;
  font-size: 0.9rem;
  font-weight: 800;
}

.ft-space-test-speaking-transcript {
  margin-top: 12px;
  padding: 12px 14px;
  border: 1px solid rgba(20, 184, 166, 0.24);
  border-radius: 8px;
  background: #f0fdfa;
}

.ft-space-test-speaking-transcript b {
  color: #0f766e;
  font-size: 0.78rem;
  text-transform: uppercase;
}

.ft-space-test-speaking-transcript p {
  margin: 6px 0 0;
  color: #23423c;
  line-height: 1.55;
}

.ft-space-test-result {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 18px;
  border-color: rgba(217, 119, 6, 0.20);
  background: #fff2dc;
}

.ft-space-test-result strong {
  color: #9a4f13;
  font-size: 1.2rem;
}

.ft-space-test-nav {
  grid-column: 1 / -1;
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  padding: 12px;
  background: #fff7ed;
}

.ft-space-test-nav button {
  min-width: 104px;
  min-height: 42px;
  padding: 0 16px;
  border: 1px solid rgba(120, 73, 34, 0.16);
  border-radius: 6px;
  background: #fffdf8;
  color: #2a211a;
  font-weight: 850;
  cursor: pointer;
}

.ft-space-test-nav button.is-exit {
  margin-right: auto;
  border-color: rgba(185, 28, 28, 0.22);
  color: #ffffff;
  background: #b91c1c;
}

.ft-space-test-nav button.is-exit:not(:disabled):hover {
  background: #991b1b;
}

.ft-space-test-nav button:not(:disabled):hover {
  border-color: rgba(217, 119, 6, 0.36);
  background: #fff1d8;
}

.ft-space-test-nav button.is-submit {
  border-color: #c2410c;
  color: #ffffff;
  background: #c2410c;
}

.ft-space-test-nav button.is-submit:not(:disabled):hover {
  background: #9a3412;
}

.ft-space-test-nav button:disabled {
  opacity: 0.5;
  cursor: default;
}

@media (max-width: 900px) {
  .ft-space-test-root {
    overflow: auto;
    padding: 10px;
  }

  .ft-space-test-shell {
    height: auto;
    min-height: calc(100dvh - 20px);
    grid-template-columns: 1fr;
    grid-template-rows: auto auto minmax(50dvh, auto) auto auto;
  }

  .ft-space-test-header,
  .ft-space-test-instructions,
  .ft-space-test-page,
  .ft-space-test-result,
  .ft-space-test-nav {
    grid-column: 1;
    grid-row: auto;
  }

  .ft-space-test-header,
  .ft-space-test-result,
  .ft-space-test-nav {
    align-items: stretch;
    flex-direction: column;
  }

  .ft-space-test-header-actions {
    width: 100%;
    justify-content: space-between;
  }

  .ft-space-test-header h1 {
    max-width: 100%;
  }

  .ft-space-test-instructions {
    max-height: 28dvh;
  }

  .ft-space-test-page {
    overflow: visible;
  }

  .ft-space-test-page-grid,
  .ft-space-test-page-grid.has-resource-panel {
    grid-template-columns: 1fr;
  }

  .ft-space-test-resource-panel,
  .ft-space-test-question-panel {
    padding: 0;
    border-right: 0;
  }

  .ft-space-test-choices label {
    grid-template-columns: auto 34px minmax(0, 1fr);
  }

  .ft-space-test-nav button {
    width: 100%;
  }

  .ft-space-test-nav button.is-exit {
    margin-right: 0;
  }
}
